dered list ②, divider ③ and individual items ④. The last item is visually dimmed and aria-current=\"page\".", "svgViewBox": "0 0 700 100"}, "cssVars": [{"name": "--origam-breadcrumb---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.breadcrumb.css_vars.color", "descriptionFallback": "Default text color of the breadcrumb container."}, {"name": "--origam-breadcrumb---background", "defaultValue": "transparent", "descriptionKey": "components.breadcrumb.css_vars.background", "descriptionFallback": "Container background (transparent by default)."}, {"name": "--origam-breadcrumb---padding-block-start", "defaultValue": "{space.2}", "descriptionKey": "components.breadcrumb.css_vars.padding_block_start", "descriptionFallback": "Block-start padding (density-adjusted at render time)."}, {"name": "--origam-breadcrumb---padding-inline-start", "defaultValue": "{space.2}", "descriptionKey": "components.breadcrumb.css_vars.padding_inline_start", "descriptionFallback": "Inline-start padding."}, {"name": "--origam-breadcrumb---border-radius", "defaultValue": "0px", "descriptionKey": "components.breadcrumb.css_vars.border_radius", "descriptionFallback": "Container border-radius. Overridden by rounded prop."}, {"name": "--origam-breadcrumb---box-shadow", "defaultValue": "{shadow.none}", "descriptionKey": "components.breadcrumb.css_vars.box_shadow", "descriptionFallback": "Container box-shadow. Overridden by elevation."}, {"name": "--origam-breadcrumb-item---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.breadcrumb.css_vars.item_color", "descriptionFallback": "Default item text color."}, {"name": "--origam-breadcrumb-item---hover-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.breadcrumb.css_vars.item_hover_color", "descriptionFallback": "Item color on hover (link affordance)."}, {"name": "--origam-breadcrumb-item---active-color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.breadcrumb.css_vars.item_active_color", "descriptionFallback": "Color of the current-page item (last crumb)."}, {"name": "--origam-breadcrumb-divider---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.breadcrumb.css_vars.divider_color", "descriptionFallback": "Divider glyph or icon color."}, {"name": "--origam-breadcrumb-divider---padding-inline", "defaultValue": "{space.2}", "descriptionKey": "components.breadcrumb.css_vars.divider_padding", "descriptionFallback": "Horizontal padding around the divider (breathing room between crumbs)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.breadcrumb.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.breadcrumb.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.breadcrumb.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.breadcrumb.exposed.load", "descriptionFallback": "Injects the computed style sheet."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.breadcrumb.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.breadcrumb.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "divider", "options": [{"label": "/", "value": "/"}, {"label": ">", "value": ">"}, {"label": "mdi-chevron-right", "value": "mdi-chevron-right"}, {"label": "mdi-arrow-right", "value": "mdi-arrow-right"}], "labelKey": "components.breadcrumb.playground.divider", "defaultValue": "/", "labelFallback": "Divider"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}], "labelKey": "components.breadcrumb.playground.color", "defaultValue": "", "labelFallback": "Color"}, {"kind": "select", "prop": "density", "options": [{"label": "comfortable", "value": "comfortable"}, {"label": "default", "value": "default"}, {"label": "compact", "value": "compact"}], "labelKey": "components.breadcrumb.playground.density", "defaultValue": "default", "labelFallback": "Density"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.breadcrumb.playground.disabled", "defaultValue": false, "labelFallback": "Disabled (all)"}, {"kind": "select", "prop": "elevation", "options": [{"label": "(none)", "value": ""}, {"label": "elevated", "value": "elevated"}], "labelKey": "components.breadcrumb.playground.elevation", "defaultValue": "", "labelFallback": "Elevation"}]}, "previewVariants": [{"label": "default", "props": {"divider": "/"}}, {"label": "icon divider", "props": {"color": "primary", "divider": "mdi-chevron-right"}}, {"label": "with color", "props": {"color": "primary", "bgColor": "primary", "divider": "/"}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a4e7d241-4045-4f14-b58c-01b2f4aeb426', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'breadcrumb-divider', 'BreadcrumbDivider', 'Navigation', NULL, 'mdi-slash-forward', 'components.catalog.breadcrumb_divider.description', 'Separator rendered between breadcrumb items. Defaults to "/" but accepts any text string or MDI icon identifier.', NULL, NULL, 'origam-breadcrumb-divider', NULL, 'packages/ds/src/components/Breadcrumb/OrigamBreadcrumbDivider.vue', 'origam', NULL, NULL, '/stories/?story=components-breadcrumb--design', '/docs/components/Breadcrumb/OrigamBreadcrumb.html', 'breadcrumb', '{"a11y": {"notes": [{"noteKey": "components.breadcrumb_divider.a11y.aria_hidden", "noteFallback": "OrigamBreadcrumbDivider is aria-hidden by design — it is a purely visual separator and should not be read by screen readers. The aria-hidden attribute is applied on the parent <li> by OrigamBreadcrumb."}, {"noteKey": "components.breadcrumb_divider.a11y.v_contrast", "noteFallback": "The v-contrast directive is applied to the root element for automatic contrast adjustment when a custom color prop is provided."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-breadcrumb-divider---color", "descriptionKey": "components.breadcrumb_divider.tokens.color", "descriptionFallback": "Divider glyph color."}, {"type": "dimension", "value": "var(--origam-space---2)", "tokenPath": "--origam-breadcrumb-divider---padding-inline", "descriptionKey": "components.breadcrumb_divider.tokens.padding_inline", "descriptionFallback": "Horizontal padding around the divider character."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"400\" height=\"120\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"60\" y=\"30\" width=\"280\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"130\" y=\"44\" width=\"140\" height=\"32\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"200\" y=\"65\" font-size=\"18\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">/</text>\n  <circle cx=\"68\" cy=\"38\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"68\" y=\"42.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"138\" cy=\"46\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"138\" y=\"50.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <line x1=\"78\" y1=\"36\" x2=\"120\" y2=\"20\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"124\" y=\"18\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-breadcrumb-divider</text>\n  <line x1=\"147\" y1=\"46\" x2=\"200\" y2=\"108\" stroke=\"var(--origam-color__action--primary---bgHover, #a855f7)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"202\" y=\"112\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">text or origam-icon</text>\n", "code": "<!-- root: <span> by default, customisable via tag prop -->\n<span class=\"origam-breadcrumb-divider\">\n  <!-- icon branch: divider is an MDI identifier -->\n  <origam-icon :icon=\"divider\" />\n  <!-- or text branch: divider is a plain string -->\n  {{ divider }}\n  <!-- or default slot override -->\n  <slot />\n</span>", "legend": [{"cls": ".origam-breadcrumb-divider", "num": 1, "descriptionKey": "components.breadcrumb_divider.anatomy.root", "descriptionFallback": "Root element (default: <code>&lt;span&gt;</code>). Carries padding, color and density classes. Usually rendered inside a <code>&lt;li aria-hidden&gt;</code> from OrigamBreadcrumb."}, {"cls": "(text or origam-icon)", "num": 2, "descriptionKey": "components.breadcrumb_divider.anatomy.content", "descriptionFallback": "Content: raw text when <code>divider</code> is a plain string; <code>&lt;origam-icon&gt;</code> when it is an MDI icon identifier (resolved via <code>MDI_ICONS</code> enum check)."}], "classes": [{"cls": "origam-breadcrumb-divider", "descriptionKey": "components.breadcrumb_divider.anatomy.root", "descriptionFallback": "Root element. Inline-block, vertical-align: middle. Padding inherited from density modifier."}], "svgDesc": "Schematic of the BreadcrumbDivider component with 2 numbered parts.", "svgTitle": "Anatomy of OrigamBreadcrumbDivider", "rootClass": "origam-breadcrumb-divider", "figcaption": "Anatomy of <code>&lt;origam-breadcrumb-divider&gt;</code> — root <code>&lt;span&gt;</code> ① hosts text or an <code>&lt;origam-icon&gt;</code> ② depending on whether <code>divider</code> is an MDI identifier.", "svgViewBox": "0 0 400 120"}, "cssVars": [{"name": "--origam-breadcrumb-divider---color", "defaultValue": "var(--origam-breadcrumb-divider---color-token, inherit)", "descriptionKey": "components.breadcrumb_divider.css_vars.color", "descriptionFallback": "Divider foreground color. Falls back to inherit so it matches the surrounding text by default."}, {"name": "--origam-breadcrumb-divider---background", "defaultValue": "transparent", "descriptionKey": "components.breadcrumb_divider.css_vars.background", "descriptionFallback": "Divider background (transparent by default)."}, {"name": "--origam-breadcrumb-divider---padding-inline", "defaultValue": "8px", "descriptionKey": "components.breadcrumb_divider.css_vars.padding_inline", "descriptionFallback": "Horizontal padding on both sides of the divider. Applied to both padding-inline-start and padding-inline-end."}, {"name": "--origam-breadcrumb-divider---opacity", "defaultValue": "1", "descriptionKey": "components.breadcrumb_divider.css_vars.opacity", "descriptionFallback": "Divider opacity (1 by default)."}, {"name": "--origam-breadcrumb-divider---density", "defaultValue": "0px", "descriptionKey": "components.breadcrumb_divider.css_vars.density", "descriptionFallback": "Density offset applied to padding calculations. comfortable: −8px, default: 0px, compact: +8px."}, {"name": "--origam-breadcrumb-divider---transition", "defaultValue": "transform, color 0.2s, 0.1s cubic-bezier(0.4, 0, 0.2, 1)", "descriptionKey": "components.breadcrumb_divider.css_vars.transition", "descriptionFallback": "Transition applied to transform and color properties."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.breadcrumb_divider.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.breadcrumb_divider.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed breadcrumbDividerStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.breadcrumb_divider.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.breadcrumb_divider.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.breadcrumb_divider.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.breadcrumb_divider.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "divider", "options": [{"label": "/", "value": "/"}, {"label": ">", "value": ">"}, {"label": "|", "value": "|"}, {"label": "mdi-chevron-right", "value": "mdi-chevron-right"}, {"label": "mdi-arrow-right", "value": "mdi-arrow-right"}, {"label": "mdi-slash-forward", "value": "mdi-slash-forward"}], "labelKey": "components.breadcrumb_divider.playground.divider", "defaultValue": "/", "labelFallback": "Divider"}, {"kind": "select", "prop": "color", "options": [{"label": "(inherit)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "danger", "value": "danger"}], "labelKey": "components.breadcrumb_divider.playground.color", "defaultValue": "", "labelFallback": "Color"}, {"kind": "select", "prop": "density", "options": [{"label": "comfortable", "value": "comfortable"}, {"label": "default", "value": "default"}, {"label": "compact", "value": "compact"}], "labelKey": "components.breadcrumb_divider.playground.density", "defaultValue": "default", "labelFallback": "Density"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('ee06d258-1d4b-4e83-9458-13f6b1a25e56', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'breadcrumb-item', 'BreadcrumbItem', 'Navigation', NULL, 'mdi-link-variant', 'components.catalog.breadcrumb_item.description', 'Individual breadcrumb link or span within an OrigamBreadcrumb trail. Supports router links, prepend/append icons, hover and active states.', NULL, NULL, 'origam-breadcrumb-item', NULL, 'packages/ds/src/components/Breadcrumb/OrigamBreadcrumbItem.vue', 'origam', NULL, NULL, '/stories/?story=components-breadcrumb--design', '/docs/components/Breadcrumb/OrigamBreadcrumb.html', 'breadcrumb', '{"a11y": {"notes": [{"noteKey": "components.breadcrumb_item.a11y.aria_current", "noteFallback": "aria-current=\"page\" is set on the active item (isActive = true) to indicate the current page to screen readers."}, {"noteKey": "components.breadcrumb_item.a11y.disabled_opacity", "noteFallback": "Disabled items use opacity and pointer-events: none rather than the native disabled attribute (which does not work on anchors)."}, {"noteKey": "components.breadcrumb_item.a11y.v_contrast", "noteFallback": "The v-contrast directive is applied to the root element for automatic contrast when a custom color is set."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.breadcrumb_item.a11y.key_tab", "actionFallback": "Moves focus to the breadcrumb item when it is a link."}, {"key": "Enter", "actionKey": "components.breadcrumb_item.a11y.key_enter", "actionFallback": "Follows the link (href / to) of the focused item."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__text---primary)", "tokenPath": "--origam-breadcrumb-item---color", "descriptionKey": "components.breadcrumb_item.tokens.color", "descriptionFallback": "Default item text color."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-breadcrumb-item---hover-color", "descriptionKey": "components.breadcrumb_item.tokens.hover_color", "descriptionFallback": "Item color on hover (link affordance)."}, {"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-breadcrumb-item---active-color", "descriptionKey": "components.breadcrumb_item.tokens.active_color", "descriptionFallback": "Color of the current-page item (last crumb, disabled state)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"140\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"50\" y=\"30\" width=\"500\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"70\" y=\"48\" width=\"50\" height=\"44\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"95\" y=\"74\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">icon</text>\n  <rect x=\"130\" y=\"48\" width=\"260\" height=\"44\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"260\" y=\"74\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Home</text>\n  <rect x=\"400\" y=\"48\" width=\"50\" height=\"44\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"425\" y=\"74\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">icon</text>\n  <circle cx=\"58\" cy=\"38\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"58\" y=\"42.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"78\" cy=\"50\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"78\" y=\"54.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"138\" cy=\"50\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"138\" y=\"54.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"408\" cy=\"50\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"408\" y=\"54.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <line x1=\"68\" y1=\"36\" x2=\"110\" y2=\"14\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"114\" y=\"12\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-breadcrumb-item</text>\n", "code": "<!-- root: resolves to <span> or <a> via useLink -->\n<component :is=\"link.tag\" class=\"origam-breadcrumb-item\"\n  :aria-current=\"isActive ? ''page'' : undefined\">\n  <!-- prepend area (hasPrepend) -->\n  <span class=\"origam-breadcrumbs__prepend\">\n    <slot name=\"prepend\">\n      <origam-avatar v-if=\"prependAvatar\" :image=\"prependAvatar\" />\n      <origam-icon v-if=\"prependIcon\" :icon=\"prependIcon\" />\n    </slot>\n  </span>\n  <!-- default slot / title text -->\n  <slot name=\"default\">\n    <span>{{ title }}</span>\n  </slot>\n  <!-- append area (hasAppend) -->\n  <span class=\"origam-breadcrumbs__append\">\n    <slot name=\"append\">\n      <origam-avatar v-if=\"appendAvatar\" :image=\"appendAvatar\" />\n      <origam-icon v-if=\"appendIcon\" :icon=\"appendIcon\" />\n    </slot>\n  </span>\n</component>", "legend": [{"cls": ".origam-breadcrumb-item", "num": 1, "descriptionKey": "components.breadcrumb_item.anatomy.root", "descriptionFallback": "Root element. Renders as <code>&lt;span&gt;</code> or <code>&lt;a&gt;</code> via useLink. Carries color, border, rounded and density classes. Modifier <code>--link</code> when href is set; <code>--disabled</code> when disabled."}, {"cls": ".origam-breadcrumbs__prepend", "num": 2, "descriptionKey": "components.breadcrumb_item.anatomy.prepend", "descriptionFallback": "Prepend slot host. Inline-flex container rendering <code>prependAvatar</code>, <code>prependIcon</code> or the <code>#prepend</code> slot. Rendered only when <code>hasPrepend</code> is true."}, {"cls": "(default slot)", "num": 3, "descriptionKey": "components.breadcrumb_item.anatomy.content", "descriptionFallback": "Content area. Renders <code>&lt;span&gt;{{ title }}&lt;/span&gt;</code> by default. Override with the <code>#default</code> slot."}, {"cls": ".origam-breadcrumbs__append", "num": 4, "descriptionKey": "components.breadcrumb_item.anatomy.append", "descriptionFallback": "Append slot host. Inline-flex container rendering <code>appendAvatar</code>, <code>appendIcon</code> or the <code>#append</code> slot. Rendered only when <code>hasAppend</code> is true."}], "classes": [{"cls": "origam-breadcrumb-item", "descriptionKey": "components.breadcrumb_item.anatomy.root", "descriptionFallback": "Root element. inline-flex, align-items: center. Text-decoration controlled via CSS var."}, {"cls": "origam-breadcrumb-item--link", "descriptionKey": "components.breadcrumb_item.anatomy.link_modifier", "descriptionFallback": "Applied when the item has an href (link affordance styling)."}, {"cls": "origam-breadcrumb-item--disabled", "descriptionKey": "components.breadcrumb_item.anatomy.disabled_modifier", "descriptionFallback": "Applied when disabled=true. Sets opacity and pointer-events: none."}, {"cls": "origam-breadcrumbs__prepend", "descriptionKey": "components.breadcrumb_item.anatomy.prepend", "descriptionFallback": "Prepend slot host — inline-flex container for icon/avatar before the title."}, {"cls": "origam-breadcrumbs__append", "descriptionKey": "components.breadcrumb_item.anatomy.append", "descriptionFallback": "Append slot host — inline-flex container for icon/avatar after the title."}], "svgDesc": "Schematic of the BreadcrumbItem component with 4 numbered internal parts.", "svgTitle": "Anatomy of OrigamBreadcrumbItem", "rootClass": "origam-breadcrumb-item", "figcaption": "Anatomy of <code>&lt;origam-breadcrumb-item&gt;</code> — root element ① (<code>&lt;span&gt;</code> or <code>&lt;a&gt;</code>), prepend slot ②, content area ③, append slot ④. Active items receive <code>aria-current=\"page\"</code>.", "svgViewBox": "0 0 600 140"}, "cssVars": [{"name": "--origam-breadcrumb-item---color", "defaultValue": "var(--origam-breadcrumb-item---color-token, inherit)", "descriptionKey": "components.breadcrumb_item.css_vars.color", "descriptionFallback": "Item foreground color. Falls back to inherit."}, {"name": "--origam-breadcrumb-item---background", "defaultValue": "transparent", "descriptionKey": "components.breadcrumb_item.css_vars.background", "descriptionFallback": "Item background color (transparent by default)."}, {"name": "--origam-breadcrumb-item---opacity", "defaultValue": "1", "descriptionKey": "components.breadcrumb_item.css_vars.opacity", "descriptionFallback": "Item opacity. Set to --origam-breadcrumb-item---opacity-disabled (0.5) when disabled."}, {"name": "--origam-breadcrumb-item---text-decoration", "defaultValue": "none", "descriptionKey": "components.breadcrumb_item.css_vars.text_decoration", "descriptionFallback": "Text decoration of the item (none by default; can be set to underline for links)."}, {"name": "--origam-breadcrumb-item---padding-block-start", "defaultValue": "8px", "descriptionKey": "components.breadcrumb_item.css_vars.padding_block_start", "descriptionFallback": "Block-start padding (density-adjusted at render time)."}, {"name": "--origam-breadcrumb-item---padding-inline-start", "defaultValue": "8px", "descriptionKey": "components.breadcrumb_item.css_vars.padding_inline_start", "descriptionFallback": "Inline-start padding (density-adjusted at render time)."}, {"name": "--origam-breadcrumb-item---density", "defaultValue": "0px", "descriptionKey": "components.breadcrumb_item.css_vars.density", "descriptionFallback": "Density offset applied to padding. comfortable: −8px, default: 0px, compact: +8px."}, {"name": "--origam-breadcrumb-item---border-radius", "defaultValue": "0px", "descriptionKey": "components.breadcrumb_item.css_vars.border_radius", "descriptionFallback": "Item border-radius. Overridden by the rounded prop."}, {"name": "--origam-breadcrumb-item---transition", "defaultValue": "transform, color 0.2s, 0.1s cubic-bezier(0.4, 0, 0.2, 1)", "descriptionKey": "components.breadcrumb_item.css_vars.transition", "descriptionFallback": "Transition applied to transform and color properties."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.breadcrumb_item.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.breadcrumb_item.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed breadcrumbItemStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.breadcrumb_item.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.breadcrumb_item.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.breadcrumb_item.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.breadcrumb_item.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.breadcrumb_item.playground.title", "defaultValue": "Home", "labelFallback": "Title"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}], "labelKey": "components.breadcrumb_item.playground.color", "defaultValue": "", "labelFallback": "Color"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.breadcrumb_item.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "select", "prop": "prependIcon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-home", "value": "mdi-home"}, {"label": "mdi-puzzle-outline", "value": "mdi-puzzle-outline"}, {"label": "mdi-folder", "value": "mdi-folder"}], "labelKey": "components.breadcrumb_item.playground.prepend_icon", "defaultValue": "", "labelFallback": "Prepend icon"}, {"kind": "select", "prop": "density", "options": [{"label": "comfortable", "value": "comfortable"}, {"label": "default", "value": "default"}, {"label": "compact", "value": "compact"}], "labelKey": "components.breadcrumb_item.playground.density", "defaultValue": "default", "labelFallback": "Density"}]}, "previewVariants": [{"label": "default", "props": {"href": "/", "title": "Home"}}, {"label": "active", "props": {"title": "Breadcrumb", "active": true, "disabled": true}}, {"label": "with icon", "props": {"color": "primary", "title": "Components", "prependIcon": "mdi-puzzle-outline"}}, {"label": "disabled", "props": {"title": "Disabled", "disabled": true}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('1b5d2607-be81-4b1b-bb5a-8377b1b4676c', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'btn', 'Btn', 'Form & Input', NULL, 'mdi-gesture-tap-button', 'components.catalog.btn.description', 'test camel', NULL, NULL, 'origam-btn', NULL, 'packages/ds/src/components/Btn/OrigamBtn.vue', 'origam', NULL, NULL, 'https://example.com', '/docs/components/Btn/OrigamBtn.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.btn.a11y.disabled_note", "noteFallback": "When disabled=true and tag is <a>, aria-disabled=\"true\" is set instead of the disabled attribute (which has no effect on anchors). Pointer events are removed via CSS."}, {"noteKey": "components.btn.a11y.focus_note", "noteFallback": "Focus-visible outline uses 2px solid currentColor with a 2px offset. The outline is only shown for keyboard navigation (not mouse click)."}, {"noteKey": "components.btn.a11y.loading_note", "noteFallback": "When loading=true, OrigamProgress is injected with role=\"progressbar\". The button is non-interactive (pointer-events: none) during loading."}, {"noteKey": "components.btn.a11y.reduced_motion_note", "noteFallback": "All transitions are disabled under prefers-reduced-motion: reduce."}, {"noteKey": "components.btn.a11y.icon_note", "noteFallback": "Icon-only buttons (icon prop) must have an aria-label describing the action — the label text is not visible."}], "roles": ["button"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.btn.a11y.key_activate", "actionFallback": "Activates the button (fires click event). Native <button> behavior."}, {"key": "Tab", "actionKey": "components.btn.a11y.key_tab", "actionFallback": "Moves focus to the next interactive element."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__action--secondary---bg)", "tokenPath": "--origam-btn---background-color", "descriptionKey": "components.btn.tokens.background_color", "descriptionFallback": "Default button background. References the semantic secondary action background."}, {"type": "color", "value": "var(--origam-color__action--secondary---fg)", "tokenPath": "--origam-btn---color", "descriptionKey": "components.btn.tokens.color", "descriptionFallback": "Default foreground color (text and icons)."}, {"type": "dimension", "value": "var(--origam-radius---sm)", "tokenPath": "--origam-btn---border-radius", "descriptionKey": "components.btn.tokens.border_radius", "descriptionFallback": "Default border radius. Overridden to {radius.full} for icon-only buttons."}, {"type": "dimension", "value": "var(--origam-btn---height-md, 36px)", "tokenPath": "--origam-btn---height", "descriptionKey": "components.btn.tokens.height", "descriptionFallback": "Default height. Size variants override this (height-xs=20px … height-xl=52px)."}, {"type": "fontWeight", "value": "var(--origam-font__weight---medium)", "tokenPath": "--origam-btn---font-weight", "descriptionKey": "components.btn.tokens.font_weight", "descriptionFallback": "Label font weight."}, {"type": "duration", "value": "var(--origam-motion__duration---slow)", "tokenPath": "--origam-btn---transition-duration", "descriptionKey": "components.btn.tokens.transition_duration", "descriptionFallback": "Duration of shadow, transform, opacity and background transitions."}, {"type": "shadow", "value": "var(--origam-shadow---md)", "tokenPath": "--origam-btn---box-shadow-elevated", "descriptionKey": "components.btn.tokens.box_shadow_elevated", "descriptionFallback": "Box shadow for variant=\"elevated\"."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "