INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('497c6fab-6fd7-4db2-a73f-46a5b324dfeb', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'color-picker', 'ColorPicker', 'Form & Input', NULL, 'mdi-palette', 'components.catalog.color_picker.description', 'Full-featured HSVA colour picker. Includes a gradient canvas, hue/alpha sliders, hex/RGB/HSL/HSV input fields and optional swatches. Composes OrigamColorPickerCanvas, OrigamColorPickerPreview, OrigamColorPickerEdit and OrigamColorPickerSwatches.', NULL, NULL, 'origam-color-picker', NULL, 'packages/ds/src/components/ColorPicker/OrigamColorPicker.vue', 'origam', NULL, NULL, '/stories/?story=components-colorpicker--design', '/docs/components/ColorPicker/OrigamColorPicker.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.color_picker.a11y.canvas_label", "noteFallback": "The canvas carries an aria-label describing the gradient region. The drag cursor position is announced via aria-valuemin/valuemax/valuenow attributes."}, {"noteKey": "components.color_picker.a11y.input_labels", "noteFallback": "Each text input has a visible label matching the mode (HEX, R, G, B, H, S, L…). Screen readers read the label and current value together."}], "roles": ["group"], "keyboard": [{"key": "Tab", "actionKey": "components.color_picker.a11y.key_tab", "actionFallback": "Moves focus between canvas, sliders, input fields and mode switcher."}, {"key": "Arrow keys (canvas)", "actionKey": "components.color_picker.a11y.key_canvas_arrows", "actionFallback": "Moves the canvas cursor by 1% increments in saturation/value. Allows precise colour selection without a mouse."}, {"key": "Arrow keys (sliders)", "actionKey": "components.color_picker.a11y.key_slider_arrows", "actionFallback": "Adjusts the hue or alpha slider value by 1 step."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---2)", "tokenPath": "--origam-color-picker__edit---gap", "descriptionKey": "components.color_picker.tokens.edit_gap", "descriptionFallback": "Gap between edit input fields."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"300\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"175\" y=\"20\" width=\"350\" height=\"260\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"183\" y=\"28\" width=\"334\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" opacity=\"0.7\"/>\n  <circle cx=\"310\" cy=\"88\" r=\"8\" fill=\"white\" stroke=\"white\" stroke-width=\"2\" opacity=\"0.9\"/>\n  <rect x=\"183\" y=\"156\" width=\"334\" height=\"24\" rx=\"4\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.06))\"/>\n  <rect x=\"195\" y=\"162\" width=\"28\" height=\"12\" rx=\"6\" fill=\"#7c3aed\"/>\n  <rect x=\"233\" y=\"162\" width=\"270\" height=\"12\" rx=\"6\" fill=\"linear-gradient(to right, red, blue)\"/>\n  <rect x=\"183\" y=\"186\" width=\"334\" height=\"24\" rx=\"4\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.04))\"/>\n  <text x=\"350\" y=\"202\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">HEX / RGB / HSL inputs</text>\n  <rect x=\"183\" y=\"218\" width=\"334\" height=\"52\" rx=\"4\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.04))\"/>\n  <text x=\"350\" y=\"248\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"sans-serif\">Swatches (optional)</text>\n  <circle cx=\"183\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"183\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"310\" cy=\"80\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"310\" y=\"84\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"195\" cy=\"156\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"195\" y=\"160\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"350\" cy=\"180\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"350\" y=\"184\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"350\" cy=\"212\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"350\" y=\"216\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"350\" cy=\"265\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"350\" y=\"269\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <text x=\"350\" y=\"290\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">Each sub-component emits update:colorHsv — changes bubble up to OrigamColorPicker</text>\n", "code": "<origam-picker class=\"origam-color-picker\">\n  <!-- canvas (drag cursor to pick S+V) -->\n  <origam-color-picker-canvas\n    :color-hsv=\"currentColor\"\n    :height=\"canvasHeight\"\n    @update:color-hsv=\"handleUpdateColor\"\n  />\n\n  <!-- controls: preview sliders + input fields -->\n  <div class=\"origam-color-picker__controls\">\n    <origam-color-picker-preview\n      :color-hsv=\"currentColor\"\n      :hide-alpha=\"!mode.endsWith(''a'')\"\n      @update:color-hsv=\"handleUpdateColor\"\n    />\n    <origam-color-picker-edit\n      :color-hsv=\"currentColor\"\n      :mode=\"mode\"\n      :modes=\"modes\"\n      @update:mode=\"handleUpdateMode\"\n      @update:color-hsv=\"handleUpdateColor\"\n    />\n  </div>\n\n  <!-- swatches grid (optional) -->\n  <origam-color-picker-swatches\n    v-if=\"showSwatches\"\n    :color-hsv=\"currentColor\"\n    @update:color-hsv=\"handleUpdateColor\"\n  />\n\n  <!-- #actions slot forwarded from OrigamPicker -->\n  <template #actions>\n    <slot name=\"actions\" />\n  </template>\n</origam-picker>", "legend": [{"cls": ".origam-color-picker", "num": 1, "descriptionKey": "components.color_picker.anatomy.root", "descriptionFallback": "Root element wrapping OrigamPicker. Inherits picker chrome (title, header, actions slots)."}, {"cls": ".origam-color-picker-canvas", "num": 2, "descriptionKey": "components.color_picker.anatomy.canvas", "descriptionFallback": "Gradient canvas (OrigamColorPickerCanvas). Drag to change saturation + value. Hidden when hideCanvas=true."}, {"cls": ".origam-color-picker-preview", "num": 3, "descriptionKey": "components.color_picker.anatomy.preview", "descriptionFallback": "Hue and alpha sliders + preview swatch (OrigamColorPickerPreview). Hidden when hideSliders=true."}, {"cls": ".origam-color-picker__controls", "num": 4, "descriptionKey": "components.color_picker.anatomy.controls", "descriptionFallback": "Row grouping the preview strip and edit inputs."}, {"cls": ".origam-color-picker-edit", "num": 5, "descriptionKey": "components.color_picker.anatomy.edit", "descriptionFallback": "Input fields + mode switcher (OrigamColorPickerEdit). Hidden when hideInputs=true."}, {"cls": ".origam-color-picker-swatches", "num": 6, "descriptionKey": "components.color_picker.anatomy.swatches", "descriptionFallback": "Predefined swatch grid (OrigamColorPickerSwatches). Visible only when showSwatches=true."}], "classes": [{"cls": "origam-color-picker", "descriptionKey": "components.color_picker.anatomy.root", "descriptionFallback": "Root picker panel."}, {"cls": "origam-color-picker__controls", "descriptionKey": "components.color_picker.anatomy.controls", "descriptionFallback": "Row grouping preview sliders + inputs."}, {"cls": "origam-color-picker-canvas", "descriptionKey": "components.color_picker.anatomy.canvas", "descriptionFallback": "Gradient canvas sub-component."}, {"cls": "origam-color-picker-preview", "descriptionKey": "components.color_picker.anatomy.preview", "descriptionFallback": "Hue/alpha sliders + preview swatch."}, {"cls": "origam-color-picker-edit", "descriptionKey": "components.color_picker.anatomy.edit", "descriptionFallback": "HEX/RGB/HSL/HSV input fields."}, {"cls": "origam-color-picker-swatches", "descriptionKey": "components.color_picker.anatomy.swatches", "descriptionFallback": "Predefined colour swatches grid."}], "svgDesc": "Schematic of the ColorPicker with 6 numbered internal parts.", "svgTitle": "Anatomy of OrigamColorPicker", "rootClass": "origam-color-picker", "figcaption": "Anatomy of <code>&lt;origam-color-picker&gt;</code> — 6 composable regions.", "svgViewBox": "0 0 700 300"}, "cssVars": [{"name": "--origam-color-picker---background-color", "defaultValue": "{color.surface.raised}", "descriptionKey": "components.color_picker.css_vars.bg", "descriptionFallback": "Picker panel background colour."}, {"name": "--origam-color-picker---border-radius", "defaultValue": "{radius.md}", "descriptionKey": "components.color_picker.css_vars.border_radius", "descriptionFallback": "Picker panel corner radius."}, {"name": "--origam-color-picker---min-width", "defaultValue": "300px", "descriptionKey": "components.color_picker.css_vars.min_width", "descriptionFallback": "Minimum width of the picker panel."}, {"name": "--origam-color-picker__canvas---border-radius", "defaultValue": "{radius.sm}", "descriptionKey": "components.color_picker.css_vars.canvas_border_radius", "descriptionFallback": "Canvas corner radius."}, {"name": "--origam-color-picker__cursor---size", "defaultValue": "16px", "descriptionKey": "components.color_picker.css_vars.cursor_size", "descriptionFallback": "Size of the drag cursor circle on the canvas."}, {"name": "--origam-color-picker__preview---width", "defaultValue": "32px", "descriptionKey": "components.color_picker.css_vars.preview_width", "descriptionFallback": "Width of the current colour preview swatch."}, {"name": "--origam-color-picker__preview---height", "defaultValue": "32px", "descriptionKey": "components.color_picker.css_vars.preview_height", "descriptionFallback": "Height of the current colour preview swatch."}, {"name": "--origam-color-picker__swatches---item-size", "defaultValue": "20px", "descriptionKey": "components.color_picker.css_vars.swatches_item_size", "descriptionFallback": "Size of each swatch tile."}, {"name": "--origam-color-picker__hue-slider---height", "defaultValue": "12px", "descriptionKey": "components.color_picker.css_vars.hue_slider_height", "descriptionFallback": "Height of the hue slider track."}, {"name": "--origam-color-picker__alpha-slider---height", "defaultValue": "12px", "descriptionKey": "components.color_picker.css_vars.alpha_slider_height", "descriptionFallback": "Height of the alpha slider track."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.color_picker.exposed.filter_props", "descriptionFallback": "Utility to forward filtered props to OrigamPicker or sub-components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.color_picker.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.color_picker.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.color_picker.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.color_picker.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.color_picker.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "switch", "prop": "hideCanvas", "labelKey": "components.color_picker.playground.hide_canvas", "defaultValue": false, "labelFallback": "Hide canvas"}, {"kind": "switch", "prop": "hideSliders", "labelKey": "components.color_picker.playground.hide_sliders", "defaultValue": false, "labelFallback": "Hide sliders"}, {"kind": "switch", "prop": "hideInputs", "labelKey": "components.color_picker.playground.hide_inputs", "defaultValue": false, "labelFallback": "Hide inputs"}, {"kind": "switch", "prop": "showSwatches", "labelKey": "components.color_picker.playground.show_swatches", "defaultValue": false, "labelFallback": "Show swatches"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.color_picker.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('f1af16c6-1116-464d-a2f2-5528833d7457', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'color-picker-canvas', 'ColorPickerCanvas', 'Form & Input', NULL, 'mdi-gradient-horizontal', 'components.catalog.color_picker_canvas.description', 'Gradient canvas where the user drags or keyboard-navigates a cursor to pick saturation and brightness from the HSV colour space.', NULL, NULL, 'origam-color-picker-canvas', NULL, 'packages/ds/src/components/ColorPicker/OrigamColorPickerCanvas.vue', 'origam', NULL, NULL, '/stories/?story=components-colorpicker--design', '/docs/components/ColorPicker/OrigamColorPicker.html', 'color-picker', '{"a11y": {"notes": [{"noteKey": "components.color_picker_canvas.a11y.role", "noteFallback": "The root element uses role=\"application\" and aria-valuetext exposing the current saturation and brightness percentages. The underlying canvas element has aria-hidden=\"true\"."}, {"noteKey": "components.color_picker_canvas.a11y.focus", "noteFallback": "Focus-visible outline (2px solid --origam-color__border---focus) is applied on :focus-visible. The component is focusable via tabindex=\"0\"."}], "roles": ["application"], "keyboard": [{"key": "Arrow keys", "actionKey": "components.color_picker_canvas.a11y.key_arrows", "actionFallback": "Moves the colour cursor by ±1% saturation (horizontal) or value (vertical). Hold Shift for ±5% steps."}, {"key": "Home / End", "actionKey": "components.color_picker_canvas.a11y.key_home_end", "actionFallback": "Home sets saturation to 0 (fully desaturated). End sets saturation to 1 (fully saturated)."}, {"key": "Page Up / Page Down", "actionKey": "components.color_picker_canvas.a11y.key_page", "actionFallback": "Page Up sets value to 1 (fully bright). Page Down sets value to 0 (black)."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"500\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"280\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <defs>\n    <linearGradient id=\"grad-s\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"white\"/>\n      <stop offset=\"100%\" stop-color=\"#7c3aed\"/>\n    </linearGradient>\n    <linearGradient id=\"grad-v\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"transparent\"/>\n      <stop offset=\"100%\" stop-color=\"black\"/>\n    </linearGradient>\n  </defs>\n  <rect x=\"20\" y=\"20\" width=\"280\" height=\"120\" rx=\"4\" fill=\"url(#grad-s)\"/>\n  <rect x=\"20\" y=\"20\" width=\"280\" height=\"120\" rx=\"4\" fill=\"url(#grad-v)\"/>\n  <rect x=\"22\" y=\"22\" width=\"276\" height=\"116\" rx=\"3\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <circle cx=\"180\" cy=\"60\" r=\"8\" fill=\"none\" stroke=\"white\" stroke-width=\"2\" filter=\"drop-shadow(0 0 2px rgba(0,0,0,0.5))\"/>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"176\" cy=\"56\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"176\" y=\"60\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"30\" cy=\"130\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"30\" y=\"134\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <line x1=\"37\" y1=\"28\" x2=\"330\" y2=\"20\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"334\" y=\"23\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-color-picker-canvas</text>\n  <line x1=\"185\" y1=\"56\" x2=\"330\" y2=\"60\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.5))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"334\" y=\"63\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">__dot (draggable cursor)</text>\n  <line x1=\"39\" y1=\"130\" x2=\"330\" y2=\"100\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.5))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"334\" y=\"103\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">canvas (aria-hidden)</text>\n", "code": "<div class=\"origam-color-picker-canvas\" role=\"application\" tabindex=\"0\">\n  <canvas aria-hidden=\"true\" />\n  <div class=\"origam-color-picker-canvas__dot\" />\n</div>", "legend": [{"cls": ".origam-color-picker-canvas", "num": 1, "descriptionKey": "components.color_picker_canvas.anatomy.root", "descriptionFallback": "Root <code>&lt;div&gt;</code> with <code>role=\"application\"</code>, <code>tabindex=\"0\"</code>, keyboard and pointer listeners. Observed by <code>useResizeObserver</code> to keep the canvas dimensions in sync."}, {"cls": ".origam-color-picker-canvas__dot", "num": 2, "descriptionKey": "components.color_picker_canvas.anatomy.dot", "descriptionFallback": "Absolute circle that follows the current saturation/value position. Has <code>--disabled</code> modifier when disabled."}, {"cls": "canvas (internal)", "num": 3, "descriptionKey": "components.color_picker_canvas.anatomy.canvas", "descriptionFallback": "Native <code>&lt;canvas&gt;</code> element with <code>aria-hidden=\"true\"</code>. The saturation/value gradient is painted via Canvas 2D API."}], "classes": [{"cls": "origam-color-picker-canvas", "descriptionKey": "components.color_picker_canvas.anatomy.root", "descriptionFallback": "Root container with overflow hidden and touch-action none."}, {"cls": "origam-color-picker-canvas__dot", "descriptionKey": "components.color_picker_canvas.anatomy.dot", "descriptionFallback": "Draggable cursor rendered as an absolute circle."}, {"cls": "origam-color-picker-canvas__dot--disabled", "descriptionKey": "components.color_picker_canvas.anatomy.dot_disabled", "descriptionFallback": "Applied when disabled=true. Reduces shadow opacity."}], "svgDesc": "Schematic of ColorPickerCanvas with 3 internal parts.", "svgTitle": "Anatomy of OrigamColorPickerCanvas", "rootClass": "origam-color-picker-canvas", "figcaption": "Anatomy of <code>&lt;origam-color-picker-canvas&gt;</code> — 3 parts. The gradient is drawn on a <code>&lt;canvas&gt;</code> element; the dot follows pointer/keyboard.", "svgViewBox": "0 0 500 160"}, "cssVars": [], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.color_picker_canvas.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.color_picker_canvas.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.color_picker_canvas.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.color_picker_canvas.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.color_picker_canvas.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.color_picker_canvas.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.color_picker_canvas.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('01f707aa-efd7-493c-83bf-d5fe5c7b120b', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'color-picker-edit', 'ColorPickerEdit', 'Form & Input', NULL, 'mdi-pencil-box-outline', 'components.catalog.color_picker_edit.description', 'Colour edit panel for OrigamColorPicker. Renders a row of text inputs for the active colour mode (RGB, RGBA, HSL, HSLA, HEX, HEXA) and a cycle button to switch between enabled modes.', NULL, NULL, 'origam-color-picker-edit', NULL, 'packages/ds/src/components/ColorPicker/OrigamColorPickerEdit.vue', 'origam', NULL, NULL, '/stories/?story=components-colorpicker--design', '/docs/components/ColorPicker/OrigamColorPickerEdit.html', 'color-picker', '{"a11y": {"notes": [{"noteKey": "components.color_picker_edit.a11y.labels", "noteFallback": "Each input is paired with a visible channel label (R, G, B, A, #…). Consumers should provide an accessible aria-label or wrap in a <fieldset><legend> when embedding standalone."}, {"noteKey": "components.color_picker_edit.a11y.disabled", "noteFallback": "When disabled=true, the native disabled attribute is set on every input, preventing keyboard and pointer interaction."}, {"noteKey": "components.color_picker_edit.a11y.cycle_button", "noteFallback": "The mode cycle button (origam-btn) has an icon only — always pair with an aria-label on the parent ColorPicker or provide a tooltip."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.color_picker_edit.a11y.key_tab", "actionFallback": "Moves focus between channel inputs and the cycle button."}, {"key": "Enter", "actionKey": "components.color_picker_edit.a11y.key_enter", "actionFallback": "Commits the typed value in the focused channel input (native input onChange)."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---2)", "tokenPath": "--origam-color-picker__edit---gap", "descriptionKey": "components.color_picker_edit.tokens.gap", "descriptionFallback": "Gap between fields."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #f9fafb)\" rx=\"4\"/>\n  <rect x=\"16\" y=\"24\" width=\"668\" height=\"100\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"16\" font-size=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"700\">origam-color-picker-edit ①</text>\n  <rect x=\"40\" y=\"44\" width=\"88\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <rect x=\"44\" y=\"50\" width=\"80\" height=\"28\" rx=\"3\" fill=\"#fff\" stroke=\"var(--origam-color__border---default, #a3a3a3)\" stroke-width=\"1\"/>\n  <text x=\"84\" y=\"68\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #6b7280)\" text-anchor=\"middle\" font-family=\"monospace\">255</text>\n  <text x=\"84\" y=\"90\" font-size=\"7.5\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"sans-serif\">R</text>\n  <rect x=\"140\" y=\"44\" width=\"88\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <rect x=\"144\" y=\"50\" width=\"80\" height=\"28\" rx=\"3\" fill=\"#fff\" stroke=\"var(--origam-color__border---default, #a3a3a3)\" stroke-width=\"1\"/>\n  <text x=\"184\" y=\"68\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #6b7280)\" text-anchor=\"middle\" font-family=\"monospace\">128</text>\n  <text x=\"184\" y=\"90\" font-size=\"7.5\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"sans-serif\">G</text>\n  <rect x=\"240\" y=\"44\" width=\"88\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <rect x=\"244\" y=\"50\" width=\"80\" height=\"28\" rx=\"3\" fill=\"#fff\" stroke=\"var(--origam-color__border---default, #a3a3a3)\" stroke-width=\"1\"/>\n  <text x=\"284\" y=\"68\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #6b7280)\" text-anchor=\"middle\" font-family=\"monospace\">64</text>\n  <text x=\"284\" y=\"90\" font-size=\"7.5\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"sans-serif\">B</text>\n  <rect x=\"340\" y=\"44\" width=\"88\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <rect x=\"344\" y=\"50\" width=\"80\" height=\"28\" rx=\"3\" fill=\"#fff\" stroke=\"var(--origam-color__border---default, #a3a3a3)\" stroke-width=\"1\"/>\n  <text x=\"384\" y=\"68\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #6b7280)\" text-anchor=\"middle\" font-family=\"monospace\">1</text>\n  <text x=\"384\" y=\"90\" font-size=\"7.5\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"sans-serif\">A</text>\n  <text x=\"40\" y=\"28\" font-size=\"7.5\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-family=\"''JetBrains Mono'',monospace\">__field ②  __input ③  __label ④</text>\n  <rect x=\"452\" y=\"52\" width=\"36\" height=\"36\" rx=\"18\" fill=\"var(--origam-color__surface---overlay, #f3f4f6)\" stroke=\"var(--origam-color__border---default, #d1d5db)\" stroke-width=\"1\"/>\n  <text x=\"470\" y=\"74\" font-size=\"14\" fill=\"var(--origam-color__text---secondary, #6b7280)\" text-anchor=\"middle\" font-family=\"sans-serif\">↕</text>\n  <text x=\"490\" y=\"74\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" font-family=\"''JetBrains Mono'',monospace\">origam-btn (cycle) ④+</text>\n", "code": "<div class=\"origam-color-picker-edit\">\n  <!-- one __field per channel of the active mode -->\n  <div class=\"origam-color-picker-edit__field\">\n    <input class=\"origam-color-picker-edit__input\" />\n    <span class=\"origam-color-picker-edit__label\">R</span>\n  </div>\n  <div class=\"origam-color-picker-edit__field\">\n    <input class=\"origam-color-picker-edit__input\" />\n    <span class=\"origam-color-picker-edit__label\">G</span>\n  </div>\n  <!-- … more channels … -->\n  <!-- cycle button — only when enabledModes.length > 1 -->\n  <origam-btn icon=\"mdi-unfold-less-horizontal\" size=\"x-small\" @click=\"handleUpdateMode\" />\n</div>", "legend": [{"cls": ".origam-color-picker-edit", "num": 1, "descriptionKey": "components.color_picker_edit.anatomy.root", "descriptionFallback": "Root element. flex row — channels sit inline. The cycle button appends at the end."}, {"cls": ".origam-color-picker-edit__field", "num": 2, "descriptionKey": "components.color_picker_edit.anatomy.field", "descriptionFallback": "Per-channel wrapper. flex column + text-align: center. Full-width with margin-inline-end between siblings."}, {"cls": ".origam-color-picker-edit__input", "num": 3, "descriptionKey": "components.color_picker_edit.anatomy.input", "descriptionFallback": "Native <input> element for the channel value. onChange triggers update:colorHsv after mode conversion."}, {"cls": ".origam-color-picker-edit__label", "num": 4, "descriptionKey": "components.color_picker_edit.anatomy.label", "descriptionFallback": "Channel label below the input (e.g. \"R\", \"G\", \"B\", \"A\", \"#\"). Font-size 0.75rem."}], "classes": [{"cls": "origam-color-picker-edit", "descriptionKey": "components.color_picker_edit.anatomy.root", "descriptionFallback": "Root flex container."}, {"cls": "origam-color-picker-edit__field", "descriptionKey": "components.color_picker_edit.anatomy.field", "descriptionFallback": "Per-channel wrapper (flex column)."}, {"cls": "origam-color-picker-edit__input", "descriptionKey": "components.color_picker_edit.anatomy.input", "descriptionFallback": "Native channel input."}, {"cls": "origam-color-picker-edit__label", "descriptionKey": "components.color_picker_edit.anatomy.label", "descriptionFallback": "Channel label below the input."}], "svgDesc": "Schematic of the ColorPickerEdit component with 4 numbered internal parts.", "svgTitle": "Anatomy of OrigamColorPickerEdit", "rootClass": "origam-color-picker-edit", "figcaption": "Anatomy of <code>&lt;origam-color-picker-edit&gt;</code> — 4 internal parts. Each mode channel gets a <code>__field</code> ② wrapper containing an <code>__input</code> ③ (native <code>&lt;input&gt;</code>) and a <code>__label</code> ④. The cycle button (origam-btn) appears only when more than one mode is enabled.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-color-picker---edit---input-width", "defaultValue": "48px", "descriptionKey": "components.color_picker_edit.css_vars.input_width", "descriptionFallback": "Width of each channel input field."}, {"name": "--origam-color-picker---edit---gap", "defaultValue": "{space.2}", "descriptionKey": "components.color_picker_edit.css_vars.gap", "descriptionFallback": "Gap between channel fields."}, {"name": "--origam-color-picker---edit---label-color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.color_picker_edit.css_vars.label_color", "descriptionFallback": "Colour of the channel label text (R, G, B, A, #)."}, {"name": "--origam-color-picker---edit---label-font-size", "defaultValue": "{font.size.xs}", "descriptionKey": "components.color_picker_edit.css_vars.label_font_size", "descriptionFallback": "Font size of the channel label."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.color_picker_edit.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.color_picker_edit.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.color_picker_edit.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.color_picker_edit.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.color_picker_edit.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.color_picker_edit.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "mode", "options": [{"label": "rgb", "value": "rgb"}, {"label": "rgba", "value": "rgba"}, {"label": "hsl", "value": "hsl"}, {"label": "hsla", "value": "hsla"}, {"label": "hex", "value": "hex"}, {"label": "hexa", "value": "hexa"}], "labelKey": "components.color_picker_edit.playground.mode", "defaultValue": "rgba", "labelFallback": "Mode"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.color_picker_edit.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}]}, "previewVariants": [{"label": "rgba mode", "props": {"mode": "rgba"}, "ariaLabel": "RGBA mode edit panel"}, {"label": "hex mode", "props": {"mode": "hex"}, "ariaLabel": "HEX mode edit panel"}, {"label": "disabled", "props": {"mode": "rgba", "disabled": true}, "ariaLabel": "Disabled edit panel"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d7642990-c828-466f-a24b-e12f7c83033f', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'color-picker-field', 'ColorPickerField', 'Form & Input', NULL, 'mdi-eyedropper-variant', 'components.catalog.color_picker_field.description', 'Text field input that opens a ColorPicker in a dropdown menu. The selected colour is displayed as a swatch inside the field prefix.', NULL, NULL, 'origam-color-picker-field', NULL, 'packages/ds/src/components/ColorPickerField/OrigamColorPickerField.vue', 'origam', NULL, NULL, '/stories/?story=components-colorpickerfield--design', '/docs/components/ColorPickerField/OrigamColorPickerField.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.color_picker_field.a11y.combobox", "noteFallback": "The field behaves as a combobox: aria-haspopup=\"dialog\" and aria-expanded reflect the popover open state."}, {"noteKey": "components.color_picker_field.a11y.swatch", "noteFallback": "The colour swatch is decorative (aria-hidden=\"true\"). The accessible value is provided by the text input which holds the hex string."}], "roles": ["combobox"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.color_picker_field.a11y.key_open", "actionFallback": "Opens the colour picker popover."}, {"key": "Escape", "actionKey": "components.color_picker_field.a11y.key_close", "actionFallback": "Closes the colour picker popover without applying changes."}, {"key": "Tab", "actionKey": "components.color_picker_field.a11y.key_tab", "actionFallback": "Moves focus into or out of the picker panel when open."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "200px", "tokenPath": "--origam-color-picker-field---min-width", "descriptionKey": "components.color_picker_field.tokens.min_width", "descriptionFallback": "Minimum field width."}, {"type": "dimension", "value": "24px", "tokenPath": "--origam-color-picker-field__swatch---width", "descriptionKey": "components.color_picker_field.tokens.swatch_width", "descriptionFallback": "Swatch width."}, {"type": "dimension", "value": "24px", "tokenPath": "--origam-color-picker-field__swatch---height", "descriptionKey": "components.color_picker_field.tokens.swatch_height", "descriptionFallback": "Swatch height."}, {"type": "dimension", "value": "var(--origam-radius---sm)", "tokenPath": "--origam-color-picker-field__swatch---border-radius", "descriptionKey": "components.color_picker_field.tokens.swatch_border_radius", "descriptionFallback": "Swatch corner radius."}, {"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-color-picker-field__icon---color", "descriptionKey": "components.color_picker_field.tokens.icon_color", "descriptionFallback": "Chevron icon colour."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"100\" y=\"40\" width=\"500\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.35))\" stroke-width=\"1.5\"/>\n  <text x=\"132\" y=\"60\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"sans-serif\">Brand colour</text>\n  <rect x=\"116\" y=\"68\" width=\"24\" height=\"24\" rx=\"4\" fill=\"#7c3aed\" stroke=\"rgba(124,58,237,0.3)\" stroke-width=\"1\"/>\n  <rect x=\"152\" y=\"68\" width=\"380\" height=\"24\" rx=\"3\" fill=\"transparent\"/>\n  <text x=\"154\" y=\"84\" font-size=\"12\" fill=\"var(--origam-color__text---primary, #1a0f3c)\" font-family=\"''JetBrains Mono'',monospace\">#7c3aed</text>\n  <text x=\"556\" y=\"84\" font-size=\"16\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"sans-serif\">⌄</text>\n  <circle cx=\"108\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"108\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"116\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"116\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"350\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"350\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"556\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"556\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <text x=\"350\" y=\"165\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">Clicking the field or swatch opens an OrigamColorPicker in an OrigamMenu popover</text>\n", "code": "<origam-text-field class=\"origam-color-picker-field\">\n  <template #prependInner>\n    <!-- colour swatch -->\n    <span class=\"origam-color-picker-field__swatch\"\n      :style=\"{ backgroundColor: modelValue }\"\n    />\n  </template>\n\n  <!-- native input for the hex value -->\n  <input class=\"origam-text-field__input\" :value=\"modelValue\" />\n\n  <!-- dropdown chevron -->\n  <template #appendInner>\n    <origam-icon class=\"origam-color-picker-field__chevron\" />\n  </template>\n</origam-text-field>\n\n<!-- colour picker in a popover -->\n<origam-menu v-model=\"menu\">\n  <origam-color-picker v-model=\"modelValue\" @update:modelValue=\"handleChange\" />\n</origam-menu>", "legend": [{"cls": ".origam-color-picker-field", "num": 1, "descriptionKey": "components.color_picker_field.anatomy.root", "descriptionFallback": "Root element — extends OrigamTextField with a colour swatch prefix."}, {"cls": ".origam-color-picker-field__swatch", "num": 2, "descriptionKey": "components.color_picker_field.anatomy.swatch", "descriptionFallback": "Small coloured square inside the input prefix. Shows the current selected colour. Clicking opens the picker."}, {"cls": ".origam-text-field__input", "num": 3, "descriptionKey": "components.color_picker_field.anatomy.input", "descriptionFallback": "Editable text input showing the colour value (hex string). Clearing triggers openOnClear if enabled."}, {"cls": ".origam-color-picker-field__chevron", "num": 4, "descriptionKey": "components.color_picker_field.anatomy.chevron", "descriptionFallback": "Append icon indicating the dropdown can be opened."}], "classes": [{"cls": "origam-color-picker-field", "descriptionKey": "components.color_picker_field.anatomy.root", "descriptionFallback": "Root field element."}, {"cls": "origam-color-picker-field__swatch", "descriptionKey": "components.color_picker_field.anatomy.swatch", "descriptionFallback": "Colour preview swatch inside the input prefix."}, {"cls": "origam-color-picker-field__chevron", "descriptionKey": "components.color_picker_field.anatomy.chevron", "descriptionFallback": "Dropdown chevron icon."}], "svgDesc": "Schematic of the ColorPickerField with 4 numbered internal parts.", "svgTitle": "Anatomy of OrigamColorPickerField", "rootClass": "origam-color-picker-field", "figcaption": "Anatomy of <code>&lt;origam-color-picker-field&gt;</code> — 4 visual parts.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-color-picker-field---min-width", "defaultValue": "200px", "descriptionKey": "components.color_picker_field.css_vars.min_width", "descriptionFallback": "Minimum width of the field."}, {"name": "--origam-color-picker-field__swatch---width", "defaultValue": "24px", "descriptionKey": "components.color_picker_field.css_vars.swatch_width", "descriptionFallback": "Width of the colour swatch inside the input."}, {"name": "--origam-color-picker-field__swatch---height", "defaultValue": "24px", "descriptionKey": "components.color_picker_field.css_vars.swatch_height", "descriptionFallback": "Height of the colour swatch."}, {"name": "--origam-color-picker-field__swatch---border-radius", "defaultValue": "{radius.sm}", "descriptionKey": "components.color_picker_field.css_vars.swatch_border_radius", "descriptionFallback": "Border radius of the colour swatch."}, {"name": "--origam-color-picker-field__icon---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.color_picker_field.css_vars.icon_color", "descriptionFallback": "Colour of the dropdown chevron icon."}, {"name": "--origam-color-picker-field__icon---color-hover", "defaultValue": "{color.text.primary}", "descriptionKey": "components.color_picker_field.css_vars.icon_color_hover", "descriptionFallback": "Colour of the chevron icon on hover."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.color_picker_field.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to OrigamTextField."}, {"name": "isFocused", "type": "Ref<boolean>", "descriptionKey": "components.color_picker_field.exposed.is_focused", "descriptionFallback": "True while the field is focused."}, {"name": "menu", "type": "Ref<boolean>", "descriptionKey": "components.color_picker_field.exposed.menu", "descriptionFallback": "Controls the picker popover open state programmatically."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.color_picker_field.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.color_picker_field.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.color_picker_field.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.color_picker_field.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.color_picker_field.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "text", "prop": "label", "labelKey": "components.color_picker_field.playground.label", "defaultValue": "Brand colour", "labelFallback": "Label"}, {"kind": "select", "prop": "variant", "options": [{"label": "outlined", "value": "outlined"}, {"label": "filled", "value": "filled"}, {"label": "underlined", "value": "underlined"}, {"label": "plain", "value": "plain"}], "labelKey": "components.color_picker_field.playground.variant", "defaultValue": "outlined", "labelFallback": "Variant"}, {"kind": "select", "prop": "density", "options": [{"label": "default", "value": "default"}, {"label": "comfortable", "value": "comfortable"}, {"label": "compact", "value": "compact"}], "labelKey": "components.color_picker_field.playground.density", "defaultValue": "default", "labelFallback": "Density"}, {"kind": "switch", "prop": "clearable", "labelKey": "components.color_picker_field.playground.clearable", "defaultValue": false, "labelFallback": "Clearable"}, {"kind": "switch", "prop": "closeOnSelect", "labelKey": "components.color_picker_field.playground.close_on_select", "defaultValue": false, "labelFallback": "Close on select"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.color_picker_field.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}]}, "previewVariants": [{"label": "default", "props": {"label": "Brand colour", "modelValue": "#7c3aed"}, "slotContent": ""}, {"label": "outlined", "props": {"label": "Outlined", "variant": "outlined", "modelValue": "#7c3aed"}, "slotContent": ""}, {"label": "disabled", "props": {"label": "Disabled", "disabled": true, "modelValue": "#7c3aed"}, "slotContent": ""}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('70b88dc3-e197-497e-8964-0876c7d568e1', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'color-picker-preview', 'ColorPickerPreview', 'Form & Input', NULL, 'mdi-eyedropper-variant', 'components.catalog.color_picker_preview.description', 'Hue and alpha sliders with a colour preview swatch and optional eye-dropper button.', NULL, NULL, 'origam-color-picker-preview', NULL, 'packages/ds/src/components/ColorPicker/OrigamColorPickerPreview.vue', 'origam', NULL, NULL, '/stories/?story=components-colorpicker--design', '/docs/components/ColorPicker/OrigamColorPicker.html', 'color-picker', '{"a11y": {"notes": [{"noteKey": "components.color_picker_preview.a11y.slider_note", "noteFallback": "Each SliderField is a native range-like widget with aria-valuemin, aria-valuemax and aria-valuenow. Keyboard navigation is handled by OrigamSliderField."}, {"noteKey": "components.color_picker_preview.a11y.eye_dropper_note", "noteFallback": "The eye-dropper button is only rendered when window.EyeDropper is available (Chromium 95+). On unsupported browsers the slot is absent."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.color_picker_preview.a11y.key_tab", "actionFallback": "Moves focus between the hue slider, alpha slider, and eye-dropper button."}, {"key": "Arrow Left / Right", "actionKey": "components.color_picker_preview.a11y.key_arrows", "actionFallback": "Adjusts the focused slider (hue or alpha) by one step."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\" height=\"140\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"16\" y=\"28\" width=\"528\" height=\"84\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <circle cx=\"52\" cy=\"70\" r=\"22\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.15))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1.5\"/>\n  <rect x=\"86\" y=\"38\" width=\"388\" height=\"16\" rx=\"4\" fill=\"linear-gradient(to right, red, #ff0, #0f0, #0ff, #00f, #f0f, red)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\"/>\n  <rect x=\"86\" y=\"38\" width=\"388\" height=\"16\" rx=\"4\" fill=\"url(#hue-grad)\" stroke=\"none\"/>\n  <defs>\n    <linearGradient id=\"hue-grad\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"red\"/>\n      <stop offset=\"17%\" stop-color=\"yellow\"/>\n      <stop offset=\"33%\" stop-color=\"lime\"/>\n      <stop offset=\"50%\" stop-color=\"cyan\"/>\n      <stop offset=\"67%\" stop-color=\"blue\"/>\n      <stop offset=\"83%\" stop-color=\"magenta\"/>\n      <stop offset=\"100%\" stop-color=\"red\"/>\n    </linearGradient>\n  </defs>\n  <rect x=\"86\" y=\"64\" width=\"388\" height=\"16\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\"/>\n  <rect x=\"86\" y=\"64\" width=\"388\" height=\"16\" rx=\"4\" fill=\"url(#alpha-grad)\" opacity=\"0.7\" stroke=\"none\"/>\n  <defs>\n    <linearGradient id=\"alpha-grad\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"transparent\"/>\n      <stop offset=\"100%\" stop-color=\"#7c3aed\"/>\n    </linearGradient>\n  </defs>\n  <rect x=\"486\" y=\"38\" width=\"42\" height=\"42\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.15))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1.5\"/>\n  <circle cx=\"24\" cy=\"36\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"24\" y=\"40\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"50\" cy=\"50\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"50\" y=\"54\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"90\" cy=\"36\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"90\" y=\"40\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"90\" cy=\"62\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"90\" y=\"66\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <line x1=\"33\" y1=\"36\" x2=\"280\" y2=\"14\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"284\" y=\"17\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-color-picker-preview</text>\n", "code": "<div class=\"origam-color-picker-preview\">\n  <!-- optional eye-dropper button (EyeDropper API support required) -->\n  <div class=\"origam-color-picker-preview__eye-dropper\">\n    <origam-btn :icon=\"MDI_ICONS.EYEDROPPER\" />\n  </div>\n  <!-- colour preview swatch -->\n  <div class=\"origam-color-picker-preview__dot\">\n    <div :style=\"{ background: currentColor }\" />\n  </div>\n  <!-- sliders -->\n  <div class=\"origam-color-picker-preview__sliders\">\n    <origam-slider-field class=\"origam-color-picker-preview__track origam-color-picker-preview__hue\" />\n    <origam-slider-field class=\"origam-color-picker-preview__track origam-color-picker-preview__alpha\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-color-picker-preview", "num": 1, "descriptionKey": "components.color_picker_preview.anatomy.root", "descriptionFallback": "Root <code>&lt;div&gt;</code> with <code>display: flex; align-items: center</code>. Has <code>--hide-alpha</code> BEM modifier when <code>hideAlpha=true</code>."}, {"cls": ".origam-color-picker-preview__dot", "num": 2, "descriptionKey": "components.color_picker_preview.anatomy.dot", "descriptionFallback": "Circular swatch showing the current colour. Uses a checkerboard background for transparency. 30x30px, <code>border-radius: 50%</code>."}, {"cls": ".origam-color-picker-preview__hue", "num": 3, "descriptionKey": "components.color_picker_preview.anatomy.hue", "descriptionFallback": "<code>OrigamSliderField</code> ranging 0–360 for hue. Track background is the full hue gradient. Fill track is hidden."}, {"cls": ".origam-color-picker-preview__alpha", "num": 4, "descriptionKey": "components.color_picker_preview.anatomy.alpha", "descriptionFallback": "<code>OrigamSliderField</code> ranging 0–1 for alpha (step 1/256). Track background is a transparency-to-current-colour gradient. Conditionally rendered via <code>v-if=\"!hideAlpha\"</code>."}], "classes": [{"cls": "origam-color-picker-preview", "descriptionKey": "components.color_picker_preview.anatomy.root", "descriptionFallback": "Root flex container."}, {"cls": "origam-color-picker-preview--hide-alpha", "descriptionKey": "components.color_picker_preview.anatomy.hide_alpha", "descriptionFallback": "BEM modifier applied when hideAlpha=true. Hides the alpha slider row."}, {"cls": "origam-color-picker-preview__eye-dropper", "descriptionKey": "components.color_picker_preview.anatomy.eye_dropper", "descriptionFallback": "Wrapper for the eye-dropper button. Shown only when EyeDropper API is supported."}, {"cls": "origam-color-picker-preview__dot", "descriptionKey": "components.color_picker_preview.anatomy.dot", "descriptionFallback": "Round swatch displaying the current picked colour with checkerboard underlay."}, {"cls": "origam-color-picker-preview__sliders", "descriptionKey": "components.color_picker_preview.anatomy.sliders", "descriptionFallback": "Flex column container for hue and alpha sliders."}, {"cls": "origam-color-picker-preview__track", "descriptionKey": "components.color_picker_preview.anatomy.track", "descriptionFallback": "Shared modifier on both slider tracks. Sets width: 100% and removes the fill track."}, {"cls": "origam-color-picker-preview__hue", "descriptionKey": "components.color_picker_preview.anatomy.hue", "descriptionFallback": "Hue slider (0–360). Track painted with the full rainbow gradient."}, {"cls": "origam-color-picker-preview__alpha", "descriptionKey": "components.color_picker_preview.anatomy.alpha", "descriptionFallback": "Alpha slider (0–1). Track painted with a transparent-to-colour gradient with a checkerboard underlay."}], "svgDesc": "Schematic of ColorPickerPreview with 4 internal parts.", "svgTitle": "Anatomy of OrigamColorPickerPreview", "rootClass": "origam-color-picker-preview", "figcaption": "Anatomy of <code>&lt;origam-color-picker-preview&gt;</code> — 4 parts: root flex container ①, preview dot ②, hue slider ③, alpha slider ④ (hidden when <code>hideAlpha</code>).", "svgViewBox": "0 0 560 140"}, "cssVars": [{"name": "--origam-color-picker-preview---width", "defaultValue": "32px", "descriptionKey": "components.color_picker_preview.css_vars.width", "descriptionFallback": "Width of the preview dot swatch."}, {"name": "--origam-color-picker-preview---height", "defaultValue": "32px", "descriptionKey": "components.color_picker_preview.css_vars.height", "descriptionFallback": "Height of the preview dot swatch."}, {"name": "--origam-color-picker-preview---border-radius", "defaultValue": "{radius.sm}", "descriptionKey": "components.color_picker_preview.css_vars.border_radius", "descriptionFallback": "Border-radius of the preview dot swatch."}, {"name": "--origam-color-picker-color-hsv", "defaultValue": "computed from colorHsv", "descriptionKey": "components.color_picker_preview.css_vars.color_hsv", "descriptionFallback": "CSS custom property injected at runtime with the current hue as a CSS colour. Used as the end stop of the alpha gradient track."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.color_picker_preview.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.color_picker_preview.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.color_picker_preview.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.color_picker_preview.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.color_picker_preview.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.color_picker_preview.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.color_picker_preview.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "hideAlpha", "labelKey": "components.color_picker_preview.playground.hide_alpha", "defaultValue": false, "labelFallback": "Hide Alpha"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8a3bd2f6-5062-4eb8-a5cb-5612890a7c62', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'color-picker-swatches', 'ColorPickerSwatches', 'Form & Input', NULL, 'mdi-palette-swatch', 'components.catalog.color_picker_swatches.description', 'Scrollable grid of predefined colour swatches. Clicking a swatch emits the selected HSVA colour.', NULL, NULL, 'origam-color-picker-swatches', NULL, 'packages/ds/src/components/ColorPicker/OrigamColorPickerSwatches.vue', 'origam', NULL, NULL, '/stories/?story=components-colorpicker--design', '/docs/components/ColorPicker/OrigamColorPicker.html', 'color-picker', '{"a11y": {"notes": [{"noteKey": "components.color_picker_swatches.a11y.contrast_note", "noteFallback": "The checkmark icon colour is automatically chosen for contrast: white on dark colours and black on light colours (getContrast utility, threshold >2)."}, {"noteKey": "components.color_picker_swatches.a11y.aria_note", "noteFallback": "Swatch tiles do not currently expose aria-label with the colour value. It is recommended to add aria-label with the hex value when using the component standalone."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.color_picker_swatches.a11y.key_tab", "actionFallback": "Navigates between interactive swatch tiles."}, {"key": "Enter / Space", "actionKey": "components.color_picker_swatches.a11y.key_activate", "actionFallback": "Selects the focused swatch and emits update:colorHsv."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"480\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"440\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"32\" y=\"32\" width=\"60\" height=\"96\" rx=\"2\" fill=\"var(--origam-color__surface---sunken, #f3e8ff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\"/>\n  <rect x=\"36\" y=\"36\" width=\"52\" height=\"16\" rx=\"2\" fill=\"#f44336\"/>\n  <rect x=\"36\" y=\"56\" width=\"52\" height=\"16\" rx=\"2\" fill=\"#e91e63\"/>\n  <rect x=\"36\" y=\"76\" width=\"52\" height=\"16\" rx=\"2\" fill=\"#9c27b0\"/>\n  <rect x=\"36\" y=\"96\" width=\"52\" height=\"16\" rx=\"2\" fill=\"#7c3aed\"/>\n  <rect x=\"100\" y=\"32\" width=\"60\" height=\"96\" rx=\"2\" fill=\"var(--origam-color__surface---sunken, #f3e8ff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\"/>\n  <rect x=\"104\" y=\"36\" width=\"52\" height=\"16\" rx=\"2\" fill=\"#3f51b5\"/>\n  <rect x=\"104\" y=\"56\" width=\"52\" height=\"16\" rx=\"2\" fill=\"#2196f3\"/>\n  <rect x=\"104\" y=\"76\" width=\"52\" height=\"16\" rx=\"2\" fill=\"#03a9f4\"/>\n  <rect x=\"104\" y=\"96\" width=\"52\" height=\"16\" rx=\"2\" fill=\"#00bcd4\"/>\n  <rect x=\"168\" y=\"32\" width=\"60\" height=\"96\" rx=\"2\" fill=\"var(--origam-color__surface---sunken, #f3e8ff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\"/>\n  <rect x=\"172\" y=\"36\" width=\"52\" height=\"16\" rx=\"2\" fill=\"#4caf50\"/>\n  <rect x=\"172\" y=\"56\" width=\"52\" height=\"16\" rx=\"2\" fill=\"#8bc34a\"/>\n  <rect x=\"172\" y=\"76\" width=\"52\" height=\"16\" rx=\"2\" fill=\"#cddc39\"/>\n  <rect x=\"172\" y=\"96\" width=\"52\" height=\"16\" rx=\"2\" fill=\"#ffeb3b\"/>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"34\" cy=\"34\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"34\" y=\"38\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"38\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"38\" y=\"42\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <line x1=\"37\" y1=\"28\" x2=\"280\" y2=\"16\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"284\" y=\"19\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-color-picker-swatches</text>\n  <line x1=\"43\" y1=\"34\" x2=\"280\" y2=\"40\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.5))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"284\" y=\"43\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">__swatch (column)</text>\n  <line x1=\"47\" y1=\"40\" x2=\"280\" y2=\"64\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.5))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"284\" y=\"67\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">__color (tile, 45x18px)</text>\n", "code": "<div class=\"origam-color-picker-swatches\" :style=\"{ maxHeight }\">\n  <div v-for=\"swatch in swatches\" class=\"origam-color-picker-swatches__swatch\">\n    <div\n      v-for=\"color in swatch\"\n      class=\"origam-color-picker-swatches__color\"\n      @click=\"handleUpdateColor(color)\"\n    >\n      <div :style=\"{ backgroundColor: background(color) }\">\n        <!-- checkmark shown when color matches current selection -->\n        <origam-icon v-if=\"isActive(color)\" :icon=\"MDI_ICONS.CHECK_CIRCLE_OUTLINE\" />\n      </div>\n    </div>\n  </div>\n</div>", "legend": [{"cls": ".origam-color-picker-swatches", "num": 1, "descriptionKey": "components.color_picker_swatches.anatomy.root", "descriptionFallback": "Root <code>&lt;div&gt;</code> with <code>overflow-y: auto</code>. <code>maxHeight</code> is injected as inline style to cap the scrollable area."}, {"cls": ".origam-color-picker-swatches__swatch", "num": 2, "descriptionKey": "components.color_picker_swatches.anatomy.swatch", "descriptionFallback": "Column wrapper rendered per item in the outer <code>swatches</code> array. <code>display: flex; flex-direction: column</code>."}, {"cls": ".origam-color-picker-swatches__color", "num": 3, "descriptionKey": "components.color_picker_swatches.anatomy.color", "descriptionFallback": "Individual swatch tile (45x18px). Has a checkerboard underlay for transparency. Renders a checkmark icon (<code>OrigamIcon</code>) when the tile matches the current colour."}], "classes": [{"cls": "origam-color-picker-swatches", "descriptionKey": "components.color_picker_swatches.anatomy.root", "descriptionFallback": "Root scrollable container. Outer div of the grid."}, {"cls": "origam-color-picker-swatches__swatch", "descriptionKey": "components.color_picker_swatches.anatomy.swatch", "descriptionFallback": "Column flex container. One per entry in the swatches array."}, {"cls": "origam-color-picker-swatches__color", "descriptionKey": "components.color_picker_swatches.anatomy.color", "descriptionFallback": "Individual swatch tile with click handler. 45x18px, border-radius 2px."}], "svgDesc": "Schematic of ColorPickerSwatches with 3 internal parts.", "svgTitle": "Anatomy of OrigamColorPickerSwatches", "rootClass": "origam-color-picker-swatches", "figcaption": "Anatomy of <code>&lt;origam-color-picker-swatches&gt;</code> — 3 parts: scrollable root ①, column wrapper ②, colour tile ③.", "svgViewBox": "0 0 480 160"}, "cssVars": [{"name": "--origam-color-picker-swatches---item-size", "defaultValue": "20px", "descriptionKey": "components.color_picker_swatches.css_vars.item_size", "descriptionFallback": "Size of individual swatch colour tiles."}, {"name": "--origam-color-picker-swatches---gap", "defaultValue": "{space.1}", "descriptionKey": "components.color_picker_swatches.css_vars.gap", "descriptionFallback": "Gap between swatch tiles."}, {"name": "--origam-color-picker-swatches---border-radius", "defaultValue": "{radius.sm}", "descriptionKey": "components.color_picker_swatches.css_vars.border_radius", "descriptionFallback": "Border-radius of each swatch tile."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.color_picker_swatches.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.color_picker_swatches.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.color_picker_swatches.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.color_picker_swatches.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.color_picker_swatches.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.color_picker_swatches.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.color_picker_swatches.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('119047b3-4380-4fc8-93bc-696e6f6af84e', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'command-palette', 'CommandPalette', 'Navigation', NULL, 'mdi-magnify', 'components.catalog.command_palette.description', '⌘K-style command launcher overlay with fuzzy search, hotkey registration and a plugin registry via useCommand().', NULL, NULL, 'origam-command-palette', NULL, 'packages/ds/src/components/CommandPalette/OrigamCommandPalette.vue', 'origam', NULL, NULL, '/stories/?story=components-commandpalette--design', '/docs/components/CommandPalette/OrigamCommandPalette.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.command_palette.a11y.combobox_note", "noteFallback": "The search input uses role=\"combobox\" with aria-controls pointing to the listbox, aria-expanded reflecting whether results are shown, and aria-activedescendant tracking the highlighted option."}, {"noteKey": "components.command_palette.a11y.dialog_note", "noteFallback": "The dialog panel uses role=\"dialog\" aria-modal=\"true\" and aria-labelledby pointing to the search input id. Focus is trapped inside while the palette is open."}, {"noteKey": "components.command_palette.a11y.disabled_command_note", "noteFallback": "Disabled commands have aria-disabled=\"true\" and cannot be selected via keyboard or mouse."}], "roles": ["dialog", "combobox", "listbox", "option"], "keyboard": [{"key": "↑ / ↓", "actionKey": "components.command_palette.a11y.key_navigate", "actionFallback": "Move highlight between command items in the result list."}, {"key": "Enter", "actionKey": "components.command_palette.a11y.key_select", "actionFallback": "Execute the currently highlighted command."}, {"key": "Escape", "actionKey": "components.command_palette.a11y.key_close", "actionFallback": "Close the palette (when closeOnEscape=true)."}, {"key": "⌘K / Ctrl+K", "actionKey": "components.command_palette.a11y.key_open", "actionFallback": "Toggle the palette open from anywhere in the page (global hotkey)."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---raised)", "tokenPath": "--origam-command-palette---background-color", "descriptionKey": "components.command_palette.tokens.background_color", "descriptionFallback": "Dialog panel background."}, {"type": "dimension", "value": "var(--origam-radius---lg)", "tokenPath": "--origam-command-palette---border-radius", "descriptionKey": "components.command_palette.tokens.border_radius", "descriptionFallback": "Dialog panel border-radius."}, {"type": "shadow", "value": "var(--origam-shadow---xl)", "tokenPath": "--origam-command-palette---box-shadow", "descriptionKey": "components.command_palette.tokens.box_shadow", "descriptionFallback": "Dialog panel elevation shadow."}, {"type": "color", "value": "var(--origam-color__action--secondary---bg)", "tokenPath": "--origam-command-palette__item---background-color-active", "descriptionKey": "components.command_palette.tokens.item_background_color_active", "descriptionFallback": "Active item background."}, {"type": "dimension", "value": "640px", "tokenPath": "--origam-command-palette---width", "descriptionKey": "components.command_palette.tokens.width", "descriptionFallback": "Default dialog width."}, {"type": "color", "value": "rgba(0, 0, 0, 0.45)", "tokenPath": "--origam-command-palette--backdrop---background-color", "descriptionKey": "components.command_palette.tokens.backdrop_background_color", "descriptionFallback": "Backdrop overlay color."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"320\" fill=\"var(--origam-color__surface---sunken, #f5f5f5)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"280\" rx=\"4\" fill=\"rgba(0,0,0,0.4)\" stroke=\"none\"/>\n  <rect x=\"100\" y=\"60\" width=\"500\" height=\"220\" rx=\"12\" fill=\"var(--origam-color__surface---elevated, #fff)\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.12))\" stroke-width=\"1.5\"/>\n  <rect x=\"100\" y=\"60\" width=\"500\" height=\"54\" rx=\"0\" fill=\"none\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.1))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <circle cx=\"126\" cy=\"87\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"126\" y=\"91.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <rect x=\"148\" y=\"70\" width=\"330\" height=\"34\" rx=\"6\" fill=\"var(--origam-color__surface---sunken, #f5f5f5)\" stroke=\"none\"/>\n  <text x=\"162\" y=\"92\" font-size=\"11\" fill=\"var(--origam-color__text---disabled, #aaa)\" font-family=\"''JetBrains Mono'',monospace\">Type a command…</text>\n  <circle cx=\"490\" cy=\"87\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"490\" y=\"91.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <rect x=\"100\" y=\"114\" width=\"500\" height=\"120\" fill=\"var(--origam-color__surface---elevated, #fff)\" stroke=\"none\"/>\n  <circle cx=\"116\" cy=\"130\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"116\" y=\"134.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <text x=\"130\" y=\"128\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #666)\" font-family=\"''JetBrains Mono'',monospace\">NAVIGATION</text>\n  <rect x=\"108\" y=\"140\" width=\"484\" height=\"36\" rx=\"6\" fill=\"var(--origam-color__action--secondary---bg, rgba(124,58,237,0.08))\"/>\n  <circle cx=\"124\" cy=\"158\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"124\" y=\"162.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <text x=\"148\" y=\"161\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui,sans-serif\">Go to Settings</text>\n  <rect x=\"500\" y=\"148\" width=\"80\" height=\"20\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(0,0,0,0.2))\" stroke-width=\"1\"/>\n  <text x=\"540\" y=\"161\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #666)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">⌘K</text>\n  <circle cx=\"116\" cy=\"206\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"116\" y=\"210.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <rect x=\"100\" y=\"234\" width=\"500\" height=\"46\" rx=\"0\" fill=\"var(--origam-color__surface---sunken, #f9f9f9)\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.08))\" stroke-width=\"1\"/>\n  <circle cx=\"116\" cy=\"257\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"116\" y=\"261.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <text x=\"300\" y=\"280\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b0b0b0)\" text-anchor=\"middle\" font-style=\"italic\">① = backdrop (fixed / inset 0). ② = dialog (role=\"dialog\"). ③ = group-title. ④ = item (role=\"option\"). ⑤ = empty slot. ⑥ = footer.</text>\n", "code": "<!-- fixed backdrop + blur -->\n<div class=\"origam-command-palette\" @click.self=\"close\">\n  <!-- dialog panel (role=\"dialog\" aria-modal=\"true\") -->\n  <div class=\"origam-command-palette__dialog\" role=\"dialog\" aria-modal=\"true\">\n\n    <!-- search bar -->\n    <div class=\"origam-command-palette__search\">\n      <origam-icon class=\"origam-command-palette__search-icon\" />\n      <input role=\"combobox\" class=\"origam-command-palette__input\" />\n    </div>\n\n    <!-- result listbox -->\n    <div class=\"origam-command-palette__list\" role=\"listbox\">\n      <!-- per-group subheader -->\n      <div class=\"origam-command-palette__group-title\">Navigation</div>\n\n      <!-- each command row -->\n      <div class=\"origam-command-palette__item\" role=\"option\">\n        <origam-icon class=\"origam-command-palette__item-icon\" />\n        <span class=\"origam-command-palette__item-text\">\n          <span class=\"origam-command-palette__item-label\">Go to Settings</span>\n          <span class=\"origam-command-palette__item-description\">…</span>\n        </span>\n        <span class=\"origam-command-palette__item-kbd\">\n          <origam-kbd :combination=\"[''meta'', ''k'']\" />\n        </span>\n      </div>\n\n      <!-- empty state (slot) -->\n      <slot name=\"empty\">\n        <div class=\"origam-command-palette__empty\">No results</div>\n      </slot>\n    </div>\n\n    <!-- footer (slot) -->\n    <slot name=\"footer\">\n      <div class=\"origam-command-palette__footer\">…</div>\n    </slot>\n  </div>\n</div>", "legend": [{"cls": ".origam-command-palette__search", "num": 1, "descriptionKey": "components.command_palette.anatomy.search", "descriptionFallback": "Search bar row. Contains a magnify icon and a <code>&lt;input role=\"combobox\"&gt;</code>."}, {"cls": ".origam-command-palette__dialog", "num": 2, "descriptionKey": "components.command_palette.anatomy.dialog", "descriptionFallback": "Dialog panel (<code>role=\"dialog\" aria-modal=\"true\"</code>). Width controlled by <code>--origam-command-palette---width</code>."}, {"cls": ".origam-command-palette__group-title", "num": 3, "descriptionKey": "components.command_palette.anatomy.group_title", "descriptionFallback": "Group subheader. Rendered for each distinct <code>group</code> value on commands."}, {"cls": ".origam-command-palette__item", "num": 4, "descriptionKey": "components.command_palette.anatomy.item", "descriptionFallback": "Command row (<code>role=\"option\"</code>). Active row receives the active background token. Hosts icon, label, description and kbd hint."}, {"cls": ".origam-command-palette__empty", "num": 5, "descriptionKey": "components.command_palette.anatomy.empty", "descriptionFallback": "Empty-state container. Rendered when no commands match. Replaced by the <code>#empty</code> slot."}, {"cls": ".origam-command-palette__footer", "num": 6, "descriptionKey": "components.command_palette.anatomy.footer", "descriptionFallback": "Footer bar with keyboard shortcut hints (<code>↑↓</code> navigate, <code>↵</code> select, <code>Esc</code> close). Replaced by the <code>#footer</code> slot."}], "classes": [{"cls": "origam-command-palette", "descriptionKey": "components.command_palette.anatomy.root", "descriptionFallback": "Root fixed overlay (backdrop). z-index from --origam-command-palette---z-index (2500)."}, {"cls": "origam-command-palette__dialog", "descriptionKey": "components.command_palette.anatomy.dialog", "descriptionFallback": "Dialog panel. role=\"dialog\" aria-modal=\"true\"."}, {"cls": "origam-command-palette__search", "descriptionKey": "components.command_palette.anatomy.search", "descriptionFallback": "Search bar row with icon + input."}, {"cls": "origam-command-palette__input", "descriptionKey": "components.command_palette.anatomy.input", "descriptionFallback": "Text input (role=\"combobox\") driving the fuzzy search."}, {"cls": "origam-command-palette__list", "descriptionKey": "components.command_palette.anatomy.list", "descriptionFallback": "Scrollable result listbox (role=\"listbox\")."}, {"cls": "origam-command-palette__group-title", "descriptionKey": "components.command_palette.anatomy.group_title", "descriptionFallback": "Group subheader rendered when commands have a group value."}, {"cls": "origam-command-palette__item", "descriptionKey": "components.command_palette.anatomy.item", "descriptionFallback": "Command row (role=\"option\"). Active state applies background-color-active token."}, {"cls": "origam-command-palette__item-icon", "descriptionKey": "components.command_palette.anatomy.item_icon", "descriptionFallback": "Optional icon at the start of the command row."}, {"cls": "origam-command-palette__item-label", "descriptionKey": "components.command_palette.anatomy.item_label", "descriptionFallback": "Primary label text."}, {"cls": "origam-command-palette__item-description", "descriptionKey": "components.command_palette.anatomy.item_description", "descriptionFallback": "Secondary description line under the label."}, {"cls": "origam-command-palette__item-kbd", "descriptionKey": "components.command_palette.anatomy.item_kbd", "descriptionFallback": "Keyboard shortcut hint area using OrigamKbd."}, {"cls": "origam-command-palette__empty", "descriptionKey": "components.command_palette.anatomy.empty", "descriptionFallback": "Empty-state message rendered when no commands match."}, {"cls": "origam-command-palette__footer", "descriptionKey": "components.command_palette.anatomy.footer", "descriptionFallback": "Footer bar with keyboard navigation hints."}, {"cls": "origam-command-palette__loading", "descriptionKey": "components.command_palette.anatomy.loading", "descriptionFallback": "Loading indicator rendered inside the list when loading=true."}], "svgDesc": "Schematic of the CommandPalette component with numbered internal parts.", "svgTitle": "Anatomy of OrigamCommandPalette", "rootClass": "origam-command-palette", "figcaption": "Anatomy of <code>&lt;origam-command-palette&gt;</code> — 6 internal regions. The backdrop ① is a fixed scrim with blur; the dialog ② contains the search bar, listbox, and footer.", "svgViewBox": "0 0 700 320"}, "cssVars": [{"name": "--origam-command-palette---z-index", "defaultValue": "{zIndex.modal} → 2500", "descriptionKey": "components.command_palette.css_vars.z_index", "descriptionFallback": "Stack order of the fixed backdrop."}, {"name": "--origam-command-palette---padding-top", "defaultValue": "18vh", "descriptionKey": "components.command_palette.css_vars.padding_top", "descriptionFallback": "Vertical offset from the top of the viewport to the dialog panel."}, {"name": "--origam-command-palette---width", "defaultValue": "640px", "descriptionKey": "components.command_palette.css_vars.width", "descriptionFallback": "Width of the dialog panel. Clamped to calc(100vw - 32px) on small screens."}, {"name": "--origam-command-palette---background-color", "defaultValue": "{color.surface.raised}", "descriptionKey": "components.command_palette.css_vars.background_color", "descriptionFallback": "Dialog panel background color."}, {"name": "--origam-command-palette---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.command_palette.css_vars.color", "descriptionFallback": "Dialog panel foreground color."}, {"name": "--origam-command-palette---border-radius", "defaultValue": "{radius.lg} → 12px", "descriptionKey": "components.command_palette.css_vars.border_radius", "descriptionFallback": "Dialog panel border-radius."}, {"name": "--origam-command-palette---box-shadow", "defaultValue": "{shadow.xl}", "descriptionKey": "components.command_palette.css_vars.box_shadow", "descriptionFallback": "Box shadow on the dialog panel."}, {"name": "--origam-command-palette--backdrop---background-color", "defaultValue": "rgba(0, 0, 0, 0.45)", "descriptionKey": "components.command_palette.css_vars.backdrop_background_color", "descriptionFallback": "Semi-transparent backdrop color."}, {"name": "--origam-command-palette--backdrop---backdrop-filter", "defaultValue": "blur(6px)", "descriptionKey": "components.command_palette.css_vars.backdrop_filter", "descriptionFallback": "Backdrop blur applied to the fixed scrim."}, {"name": "--origam-command-palette__item---background-color-active", "defaultValue": "{color.action.secondary.bg}", "descriptionKey": "components.command_palette.css_vars.item_background_color_active", "descriptionFallback": "Background of the currently highlighted command item."}], "exposed": [{"name": "query", "type": "Ref<string>", "descriptionKey": "components.command_palette.exposed.query", "descriptionFallback": "Reactive current search query string."}, {"name": "filtered", "type": "ComputedRef<ICommand[]>", "descriptionKey": "components.command_palette.exposed.filtered", "descriptionFallback": "Computed list of commands that match the current query."}, {"name": "activeIndex", "type": "Ref<number>", "descriptionKey": "components.command_palette.exposed.active_index", "descriptionFallback": "Index of the currently highlighted command item in the filtered list."}, {"name": "isActive", "type": "Ref<boolean>", "descriptionKey": "components.command_palette.exposed.is_active", "descriptionFallback": "Whether the palette is currently open."}], "playground": {"controls": [{"kind": "switch", "prop": "modelValue", "labelKey": "components.command_palette.playground.model_value", "defaultValue": false, "labelFallback": "Open"}, {"kind": "switch", "prop": "loading", "labelKey": "components.command_palette.playground.loading", "defaultValue": false, "labelFallback": "Loading"}, {"kind": "switch", "prop": "closeOnSelect", "labelKey": "components.command_palette.playground.close_on_select", "defaultValue": true, "labelFallback": "Close on select"}, {"kind": "switch", "prop": "closeOnBackdrop", "labelKey": "components.command_palette.playground.close_on_backdrop", "defaultValue": true, "labelFallback": "Close on backdrop"}, {"kind": "text", "prop": "placeholder", "labelKey": "components.command_palette.playground.placeholder", "defaultValue": "Type a command…", "labelFallback": "Placeholder"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
