, {"cls": ".origam-date-picker-header__content", "num": 3, "descriptionKey": "components.date_picker_header.anatomy.content", "descriptionFallback": "Animated content area (wrapped in OrigamTransition)."}, {"cls": ".origam-date-picker-header__append", "num": 4, "descriptionKey": "components.date_picker_header.anatomy.append", "descriptionFallback": "Append grid area."}], "classes": [{"cls": "origam-date-picker-header", "descriptionKey": "components.date_picker_header.anatomy.root", "descriptionFallback": "Root grid container."}, {"cls": "origam-date-picker-header__prepend", "descriptionKey": "components.date_picker_header.anatomy.prepend", "descriptionFallback": "Prepend area."}, {"cls": "origam-date-picker-header__content", "descriptionKey": "components.date_picker_header.anatomy.content", "descriptionFallback": "Animated header value area."}, {"cls": "origam-date-picker-header__append", "descriptionKey": "components.date_picker_header.anatomy.append", "descriptionFallback": "Append area."}, {"cls": "origam-date-picker-header--clickable", "descriptionKey": "components.date_picker_header.anatomy.clickable", "descriptionFallback": "Applied when a click listener is attached; adds cursor:pointer on the content."}], "svgDesc": "A grid-based header with prepend, animated content, and append areas.", "svgTitle": "Anatomy of OrigamDatePickerHeader", "rootClass": "origam-date-picker-header", "figcaption": "Anatomy of <code>&lt;origam-date-picker-header&gt;</code> — root grid ①, prepend area ②, animated content ③, append area ④.", "svgViewBox": "0 0 560 100"}, "cssVars": [{"name": "--origam-date-picker---header-background-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.date_picker_header.css_vars.bg", "descriptionFallback": "Header background colour."}, {"name": "--origam-date-picker---header-color", "defaultValue": "{color.action.primary.fg}", "descriptionKey": "components.date_picker_header.css_vars.color", "descriptionFallback": "Header 