 list items (rendered from the items array or default slot).", "svgViewBox": "0 0 700 280"}, "cssVars": [{"name": "--origam-menu---background", "defaultValue": "{color.surface.raised}", "descriptionKey": "components.menu.css_vars.background", "descriptionFallback": "Menu panel background color."}, {"name": "--origam-menu---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.menu.css_vars.color", "descriptionFallback": "Menu text color."}, {"name": "--origam-menu---border-radius", "defaultValue": "{radius.md}", "descriptionKey": "components.menu.css_vars.border_radius", "descriptionFallback": "Border-radius of the menu panel."}, {"name": "--origam-menu---box-shadow", "defaultValue": "{shadow.lg}", "descriptionKey": "components.menu.css_vars.box_shadow", "descriptionFallback": "Drop shadow applied to the menu panel."}, {"name": "--origam-menu---max-height", "defaultValue": "calc(100vh - 32px)", "descriptionKey": "components.menu.css_vars.max_height", "descriptionFallback": "Maximum height before the menu becomes scrollable."}, {"name": "--origam-menu---z-index", "defaultValue": "{zIndex.dropdown}", "descriptionKey": "components.menu.css_vars.z_index", "descriptionFallback": "Z-index of the menu overlay panel."}, {"name": "--origam-menu---transition-duration", "defaultValue": "{motion.duration.fast}", "descriptionKey": "components.menu.css_vars.transition_duration", "descriptionFallback": "Enter/leave transition duration."}, {"name": "--origam-menu__content---padding", "defaultValue": "{space.1}", "descriptionKey": "components.menu.css_vars.content_padding", "descriptionFallback": "Inner padding of the menu content area."}, {"name": "--origam-menu__content---max-width", "defaultValue": "320px", "descriptionKey": "components.menu.css_vars.content_max_width", "descriptionFallback": "Maximum width of the menu content area."}], "playground": {"controls": [{"kind": "select", "prop": "location", "options": [{"label": "bottom", "value": "bottom"}, {"label": "top", "value": "top"}, {"label": "left", "value": "left"}, {"label": "right", "value": "right"}, {"label": "bottom start", "value": "bottom start"}, {"label": "bottom end", "value": "bottom end"}], "labelKey": "components.menu.playground.location", "defaultValue": "bottom", "labelFallback": "Location"}, {"kind": "switch", "prop": "closeOnContentClick", "labelKey": "components.menu.playground.close_on_content_click", "defaultValue": true, "labelFallback": "Close on content click"}, {"kind": "switch", "prop": "openOnHover", "labelKey": "components.menu.playground.open_on_hover", "defaultValue": false, "labelFallback": "Open on hover"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(default)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "xl", "value": "xl"}], "labelKey": "components.menu.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "select", "prop": "elevation", "options": [{"label": "(default)", "value": ""}, {"label": "0", "value": "0"}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}], "labelKey": "components.menu.playground.elevation", "defaultValue": "", "labelFallback": "Elevation"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('27b4a326-9109-48c2-a95b-b890659ca697', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'messages', 'Messages', 'Form & Input', NULL, 'mdi-message-text-outline', 'components.catalog.messages.description', 'Accessible live region that displays a list of validation or hint messages below form fields. Supports transitions, custom slot content, and full design token customisation.', NULL, NULL, 'origam-messages', NULL, 'packages/ds/src/components/Messages/OrigamMessages.vue', 'origam', NULL, NULL, '/stories/?story=components-messages--design', '/docs/components/Messages/OrigamMessages.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.messages.a11y.live_region", "noteFallback": "The root element carries aria-live=\"polite\" and role=\"status\". Screen readers announce new messages without interrupting the current speech flow."}, {"noteKey": "components.messages.a11y.color_note", "noteFallback": "Color alone is never the sole indicator — message text is always visible. Ensure sufficient contrast ratio (≥4.5:1) when overriding the color prop."}], "roles": ["status"], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "currentColor", "tokenPath": "--origam-messages---color", "descriptionKey": "components.messages.tokens.color", "descriptionFallback": "Inherits the field context color (error=danger, hint=info)."}, {"type": "dimension", "value": "12px", "tokenPath": "--origam-messages---font-size", "descriptionKey": "components.messages.tokens.font_size", "descriptionFallback": "Fixed 12 px per design spec."}, {"type": "dimension", "value": "14px", "tokenPath": "--origam-messages---min-height", "descriptionKey": "components.messages.tokens.min_height", "descriptionFallback": "Prevents layout collapse when messages array is empty."}, {"type": "duration", "value": "var(--origam-motion__duration---normal)", "tokenPath": "--origam-messages__message---transition-duration", "descriptionKey": "components.messages.tokens.message_transition", "descriptionFallback": "Slide-y transition duration for individual message rows."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"30\" y=\"30\" width=\"640\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1.5\"/>\n  <rect x=\"50\" y=\"52\" width=\"580\" height=\"26\" rx=\"3\" fill=\"var(--origam-color__feedback--danger---bgSubtle, rgba(239,68,68,0.06))\"/>\n  <text x=\"340\" y=\"69\" font-size=\"9\" fill=\"var(--origam-color__feedback--danger---fg, #dc2626)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-messages__message — \"This field is required\"</text>\n  <rect x=\"50\" y=\"84\" width=\"580\" height=\"26\" rx=\"3\" fill=\"var(--origam-color__feedback--danger---bgSubtle, rgba(239,68,68,0.04))\"/>\n  <text x=\"340\" y=\"101\" font-size=\"9\" fill=\"var(--origam-color__feedback--danger---fg, #dc2626)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-messages__message — \"Must be a valid email\"</text>\n  <circle cx=\"26\" cy=\"34\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"26\" y=\"38\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"26\" cy=\"56\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"26\" y=\"60\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"26\" cy=\"88\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"26\" y=\"92\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<div\n  class=\"origam-messages\"\n  aria-live=\"polite\"\n  role=\"status\"\n>\n  <transition-group name=\"slide-y-transition\">\n    <div\n      v-for=\"message in normalizedMessages\"\n      :key=\"message\"\n      class=\"origam-messages__message\"\n    >\n      <slot :message=\"message\">{{ message }}</slot>\n    </div>\n  </transition-group>\n</div>", "legend": [{"cls": ".origam-messages", "num": 1, "descriptionKey": "components.messages.anatomy.root", "descriptionFallback": "Root container. Has aria-live=\"polite\" and role=\"status\" for screen-reader announcements."}, {"cls": ".origam-messages__message (row 1)", "num": 2, "descriptionKey": "components.messages.anatomy.message_1", "descriptionFallback": "First message row. Enters/leaves with the slide-y transition."}, {"cls": ".origam-messages__message (row n)", "num": 3, "descriptionKey": "components.messages.anatomy.message_n", "descriptionFallback": "Subsequent message rows — one per entry in the messages array."}], "classes": [{"cls": "origam-messages", "descriptionKey": "components.messages.anatomy.root", "descriptionFallback": "Root container — aria-live=\"polite\" + role=\"status\" live region."}, {"cls": "origam-messages__message", "descriptionKey": "components.messages.anatomy.message", "descriptionFallback": "Individual message row. One per string in the messages prop."}], "svgDesc": "Schematic of the Messages component with 3 numbered parts.", "svgTitle": "Anatomy of OrigamMessages", "rootClass": "origam-messages", "figcaption": "Anatomy of <code>&lt;origam-messages&gt;</code> — 3 parts: the root live-region container, and one <code>__message</code> row per entry in the messages array.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-messages---color", "defaultValue": "currentColor", "descriptionKey": "components.messages.css_vars.color", "descriptionFallback": "Default message text color. Inherits from the parent context (OrigamField injects the error/hint color)."}, {"name": "--origam-messages---font-size", "defaultValue": "12px", "descriptionKey": "components.messages.css_vars.font_size", "descriptionFallback": "Font size of all message rows (fixed 12 px per spec)."}, {"name": "--origam-messages---min-height", "defaultValue": "14px", "descriptionKey": "components.messages.css_vars.min_height", "descriptionFallback": "Minimum height preserved even with no messages, preventing layout jump."}, {"name": "--origam-messages---opacity", "defaultValue": "{opacity.87}", "descriptionKey": "components.messages.css_vars.opacity", "descriptionFallback": "Container opacity."}, {"name": "--origam-messages__message---transition-duration", "defaultValue": "{motion.duration.normal}", "descriptionKey": "components.messages.css_vars.message_transition", "descriptionFallback": "Duration of the slide-y enter/leave transition per message row."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.messages.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "density", "options": [{"label": "(default)", "value": ""}, {"label": "default", "value": "default"}, {"label": "DENSITY.DEFAULT", "value": "DENSITY.DEFAULT"}, {"label": "compact", "value": "compact"}, {"label": "DENSITY.COMPACT", "value": "DENSITY.COMPACT"}, {"label": "DENSITY.COMFORTABLE", "value": "DENSITY.COMFORTABL