INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('ff770489-f018-46f9-b99b-411aa638bceb', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'slider-field', 'SliderField', 'Form & Input', NULL, 'mdi-tune-variant', 'components.catalog.slider_field.description', 'Range slider with thumb, track and tick marks. Supports range (dual-thumb), vertical orientation, and media-scrubber variants.', NULL, NULL, 'origam-slider-field', NULL, 'packages/ds/src/components/SliderField/OrigamSliderField.vue', 'origam', NULL, NULL, '/stories/?story=components-sliderfield--design', '/docs/components/SliderField/OrigamSliderField.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.slider_field.a11y.range_note", "noteFallback": "The native <input type=\"range\"> owns keyboard and pointer math. aria-valuemin, aria-valuemax, aria-valuenow and aria-orientation are managed by the browser natively."}, {"noteKey": "components.slider_field.a11y.label_note", "noteFallback": "Pair with the label prop or an aria-label attribute to identify the slider purpose for screen readers."}, {"noteKey": "components.slider_field.a11y.range_dual_note", "noteFallback": "In range (dual-thumb) mode, each thumb is a separate <input type=\"range\">. Provide distinct aria-label values for the start and end thumbs."}], "roles": ["slider"], "keyboard": [{"key": "Arrow Left / Down", "actionKey": "components.slider_field.a11y.key_decrease", "actionFallback": "Decreases the value by one step."}, {"key": "Arrow Right / Up", "actionKey": "components.slider_field.a11y.key_increase", "actionFallback": "Increases the value by one step."}, {"key": "Home", "actionKey": "components.slider_field.a11y.key_home", "actionFallback": "Jumps to the minimum value."}, {"key": "End", "actionKey": "components.slider_field.a11y.key_end", "actionFallback": "Jumps to the maximum value."}, {"key": "Page Up / Page Down", "actionKey": "components.slider_field.a11y.key_page", "actionFallback": "Increments or decrements by 10% of the total range."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "4px", "tokenPath": "--origam-slider-field__track---height", "descriptionKey": "components.slider_field.tokens.track_height", "descriptionFallback": "Track rail height."}, {"type": "color", "value": "var(--origam-color__surface---disabled)", "tokenPath": "--origam-slider-field__track---background-color", "descriptionKey": "components.slider_field.tokens.track_bg", "descriptionFallback": "Unfilled rail color."}, {"type": "dimension", "value": "16px", "tokenPath": "--origam-slider-field__thumb---size", "descriptionKey": "components.slider_field.tokens.thumb_size", "descriptionFallback": "Thumb diameter."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-slider-field__thumb---background-color", "descriptionKey": "components.slider_field.tokens.thumb_bg", "descriptionFallback": "Thumb background."}, {"type": "number", "value": "1.25", "tokenPath": "--origam-slider-field__thumb---scale-hover", "descriptionKey": "components.slider_field.tokens.thumb_scale_hover", "descriptionFallback": "Thumb scale on hover."}, {"type": "number", "value": "var(--origam-opacity---32)", "tokenPath": "--origam-slider-field---opacity-disabled", "descriptionKey": "components.slider_field.tokens.opacity_disabled", "descriptionFallback": "Opacity when disabled."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"30\" width=\"644\" height=\"120\