ar(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"360\" cy=\"100\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"360\" y=\"104.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"300\" cy=\"135\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"300\" y=\"139.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <line x1=\"46\" y1=\"30\" x2=\"80\" y2=\"14\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"14\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-slider-field</text>\n", "code": "<!-- root: OrigamInput form chrome in \"field\" variant -->\n<div class=\"origam-slider-field\">\n  <!-- label slot (field variant) -->\n  <slot name=\"label\"><origam-label>{{ label }}</origam-label></slot>\n\n  <!-- track: rail + fill + ticks (OrigamSliderFieldTrack sub-component) -->\n  <div class=\"origam-slider-field__container\">\n    <origam-slider-field-track\n      :start=\"startPercent\"\n      :stop=\"stopPercent\"\n      :ticks=\"computedTicks\"\n    />\n    <!-- native <input type=\"range\"> (pointer math owner) -->\n    <input type=\"range\" :min=\"min\" :max=\"max\" :step=\"step\" />\n    <!-- thumb -->\n    <div class=\"origam-slider-field__thumb\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-slider-field", "num": 1, "descriptionKey": "components.slider_field.anatomy.root", "descriptionFallback": "Root container. Wraps inside OrigamInput chrome when variant=\"field\"."}, {"cls": ".origam-slider-field__label", "num": 2, "descriptionKey": "components.slider_field.anatomy.label", "descriptionFallback": "Label slot area. Rendered only in field variant."}, {"cls": ".origam-slider-field__fill", "num": 3, "descriptionKey": "components.slider_field.anatomy.fill", "descriptionFallback": "Active fill bar. Width/height proportional to modelValue between min and max."}, {"cls": ".origam-slider-field__thumb", "num": 4, "descriptionKey": "components.slider_field.anatomy.thumb", "descriptionFallback": "Draggable thumb. Scales on hover/active. Hides at rest when showThumbOnHoverOnly=true."}, {"cls": ".origam-slider-field__tick", "num": 5, "descriptionKey": "components.slider_field.anatomy.tick", "descriptionFallback": "Tick mark dots shown when showTicks is set. One dot per step increment."}], "classes": [{"cls": "origam-slider-field", "descriptionKey": "components.slider_field.anatomy.root", "descriptionFallback": "Root element."}, {"cls": "origam-slider-field__container", "descriptionKey": "components.slider_field.anatomy.container", "descriptionFallback": "Inner container holding track, native input and thumb."}, {"cls": "origam-slider-field__fill", "descriptionKey": "components.slider_field.anatomy.fill", "descriptionFallback": "Active fill from min to current value."}, {"cls": "origam-slider-field__thumb", "descriptionKey": "components.slider_field.anatomy.thumb", "descriptionFallback": "Draggable thumb element."}, {"cls": "origam-slider-field__tick", "descriptionKey": "components.slider_field.anatomy.tick", "descriptionFallback": "Tick mark dot."}], "svgDesc": "Schematic of the SliderField component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamSliderField", "rootClass": "origam-slider-field", "figcaption": "Anatomy of <code>&lt;origam-slider-field&gt;</code> — 5 internal parts: root ①, label ②, track-fill ③, thumb ④ and tick marks ⑤.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-slider-field---transition-duration", "defaultValue": "{motion.duration.fast}", "descriptionKey": "components.slider_field.css_vars.transition_duration", "descriptionFallback": "Transition duration for thumb scale and fill width animations."}, {"name": "--origam-slider-field__track---height", "defaultValue": "4px", "descriptionKey": "components.slider_field.css_vars.track_height", "descriptionFallback": "Track rail height (horizontal orientation)."}, {"name": "--origam-slider-field__track---background-color", "defaultValue": "{color.surface.disabled}", "descriptionKey": "components.slider_field.css_vars.track_bg", "descriptionFallback": "Unfilled track rail background color."}, {"name": "--origam-slider-field__track-fill---background-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.slider_field.css_vars.track_fill_bg", "descriptionFallback": "Active fill color. Overridden by color prop."}, {"name": "--origam-slider-field__thumb---size", "defaultValue": "16px", "descriptionKey": "components.slider_field.css_vars.thumb_size", "descriptionFallback": "Thumb diameter."}, {"name": "--origam-slider-field__thumb---background-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.slider_field.css_vars.thumb_bg", "descriptionFallback": "Thumb background color."}, {"name": "--origam-slider-field__thumb---scale-hover", "defaultValue": "1.25", "descriptionKey": "components.slider_field.css_vars.thumb_scale_hover", "descriptionFallback": "Thumb scale on hover."}, {"name": "--origam-slider-field---opacity-disabled", "defaultValue": "{opacity.32}", "descriptionKey": "components.slider_field.css_vars.opacity_disabled", "descriptionFallback": "Opacity when disabled."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.slider_field.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.slider_field.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.slider_field.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.slider_field.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.slider_field.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.slider_field.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "number", "prop": "modelValue", "labelKey": "components.slider_field.playground.model_value", "defaultValue": 50, "labelFallback": "Value"}, {"kind": "number", "prop": "min", "labelKey": "components.slider_field.playground.min", "defaultValue": 0, "labelFallback": "Min"}, {"kind": "number", "prop": "max", "labelKey": "components.slider_field.playground.max", "defaultValue": 100, "labelFallback": "Max"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "warning", "value": "warning"}, {"label": "danger", "value": "danger"}], "labelKey": "components.slider_field.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.slider_field.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "readonly", "labelKey": "components.slider_field.playground.readonly", "defaultValue": false, "labelFallback": "Readonly"}, {"kind": "switch", "prop": "error", "labelKey": "components.slider_field.playground.error", "defaultValue": false, "labelFallback": "Error"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0a8ec30e-726a-40b1-91c6-deb44ca7079f', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'slider-field-track', 'SliderFieldTrack', 'Form & Input', NULL, 'mdi-ray-start-end', 'components.catalog.slider_field_track.description', 'Internal track sub-component of SliderField. Renders the background rail, the fill bar and optional tick marks. Not intended for standalone use.', NULL, NULL, 'origam-slider-field-track', NULL, 'packages/ds/src/components/SliderField/OrigamSliderFieldTrack.vue', 'origam', NULL, NULL, '/stories/?story=components-slider-field--design', '/docs/components/SliderField/OrigamSliderField.html', 'slider-field', '{"a11y": {"notes": [{"noteKey": "components.slider_field_track.a11y.pointer_events", "noteFallback": "pointer-events: none is set on the root so the track never intercepts thumb interactions. All keyboard and pointer handling lives in the parent SliderField."}, {"noteKey": "components.slider_field_track.a11y.forced_colors", "noteFallback": "Under forced-colors (Windows High Contrast): the root receives a thin solid buttontext border, and background/fill use the highlight system color."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "dimension", "value": "4px", "tokenPath": "--origam-slider-field__track---height", "descriptionKey": "components.slider_field_track.tokens.height", "descriptionFallback": "Default track height / thickness."}, {"type": "color", "value": "var(--origam-color__surface---disabled)", "tokenPath": "--origam-slider-field__track---background-color", "descriptionKey": "components.slider_field_track.tokens.background_color", "descriptionFallback": "Rail background color."}, {"type": "dimension", "value": "var(--origam-radius---full)", "tokenPath": "--origam-slider-field__track---border-radius", "descriptionKey": "components.slider_field_track.tokens.border_radius", "descriptionFallback": "Border radius of the track (pill shape)."}, {"type": "dimension", "value": "4px", "tokenPath": "--origam-slider-field__tick---size", "descriptionKey": "components.slider_field_track.tokens.tick_size", "descriptionFallback": "Tick dot size token."}, {"type": "color", "value": "var(--origam-color__text---disabled)", "tokenPath": "--origam-slider-field__tick---background-color", "descriptionKey": "components.slider_field_track.tokens.tick_color", "descriptionFallback": "Tick dot color in the unfilled zone."}, {"type": "color", "value": "var(--origam-color__action--primary---fg)", "tokenPath": "--origam-slider-field__tick---background-color-active", "descriptionKey": "components.slider_field_track.tokens.tick_color_active", "descriptionFallback": "Tick dot color in the filled zone."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"88\" width=\"620\" height=\"8\" rx=\"4\" fill=\"var(--origam-color__surface---disabled, #d4c7e8)\"/>\n  <rect x=\"40\" y=\"88\" width=\"310\" height=\"8\" rx=\"4\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"80\" cy=\"92\" r=\"4\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\"/>\n  <circle cx=\"175\" cy=\"92\" r=\"4\" fill=\"var(--origam-color__action--primary---fg, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <circle cx=\"270\" cy=\"92\" r=\"4\" fill=\"var(--origam-color__action--primary---fg, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <circle cx=\"350\" cy=\"92\" r=\"4\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\"/>\n  <circle cx=\"450\" cy=\"92\" r=\"4\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\"/>\n  <circle cx=\"550\" cy=\"92\" r=\"4\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\"/>\n  <circle cx=\"40\" cy=\"92\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"40\" y=\"96\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"70\" cy=\"75\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"70\" y=\"79\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"200\" cy=\"75\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"200\" y=\"79\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"450\" cy=\"75\" r=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"450\" y=\"79\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <text x=\"40\" y=\"120\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-style=\"italic\">track root</text>\n  <text x=\"70\" y=\"140\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-style=\"italic\">background</text>\n  <text x=\"200\" y=\"140\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-style=\"italic\">fill (start→stop)</text>\n  <text x=\"450\" y=\"140\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-style=\"italic\">tick marks</text>\n", "code": "<div class=\"origam-slider-field-track\">\n  <!-- background rail -->\n  <div class=\"origam-slider-field-track__background origam-slider-field-track__background--opacity\" />\n\n  <!-- fill bar (start → stop %) -->\n  <div class=\"origam-slider-field-track__fill\" />\n\n  <!-- tick marks (optional) -->\n  <div class=\"origam-slider-field-track__ticks origam-slider-field-track__ticks--always-show\">\n    <div class=\"origam-slider-field-track__tick origam-slider-field-track__tick--first\">\n      <!-- tick label via #item or #item.{index} slot -->\n      <div class=\"origam-slider-field-track__tick-label\">{{ tick.label }}</div>\n    </div>\n  </div>\n</div>", "legend": [{"cls": ".origam-slider-field-track", "num": 1, "descriptionKey": "components.slider_field_track.anatomy.root", "descriptionFallback": "Root element. Position: relative, border-radius: 9999px, pointer-events: none. Size set via --origam-slider-field-track---size."}, {"cls": ".origam-slider-field-track__background", "num": 2, "descriptionKey": "components.slider_field_track.anatomy.background", "descriptionFallback": "Rail background bar. Spans 100% in the track axis. Opacity 0.38 when a fill color is active (--opacity modifier). Animated via slider-field__track---transition."}, {"cls": ".origam-slider-field-track__fill", "num": 3, "descriptionKey": "components.slider_field_track.anatomy.fill", "descriptionFallback": "Fill bar. Positioned from start% to stop% along the track axis using logical CSS properties."}, {"cls": ".origam-slider-field-track__ticks", "num": 4, "descriptionKey": "components.slider_field_track.anatomy.ticks", "descriptionFallback": "Tick container. Rendered only when showTicks is truthy and parsedTicks is non-empty. Children are .origam-slider-field-track__tick elements."}], "classes": [{"cls": "origam-slider-field-track", "descriptionKey": "components.slider_field_track.anatomy.root", "descriptionFallback": "Root track container."}, {"cls": "origam-slider-field-track__background", "descriptionKey": "components.slider_field_track.anatomy.background", "descriptionFallback": "Rail background. Full width/height of the track."}, {"cls": "origam-slider-field-track__background--opacity", "descriptionKey": "components.slider_field_track.anatomy.background_opacity", "descriptionFallback": "Applied when a fill color is active. Sets opacity to 0.38 on the background."}, {"cls": "origam-slider-field-track__fill", "descriptionKey": "components.slider_field_track.anatomy.fill", "descriptionFallback": "Fill bar positioned from start% to stop% along the track."}, {"cls": "origam-slider-field-track__ticks", "descriptionKey": "components.slider_field_track.anatomy.ticks", "descriptionFallback": "Container for tick mark elements."}, {"cls": "origam-slider-field-track__ticks--always-show", "descriptionKey": "components.slider_field_track.anatomy.ticks_always_show", "descriptionFallback": "Applied when showTicks=\"always\". Forces tick opacity to 1."}, {"cls": "origam-slider-field-track__tick", "descriptionKey": "components.slider_field_track.anatomy.tick", "descriptionFallback": "Individual tick dot. Size: tickSize × tickSize, centered on its position."}, {"cls": "origam-slider-field-track__tick--filled", "descriptionKey": "components.slider_field_track.anatomy.tick_filled", "descriptionFallback": "Applied when tick.position is within [start, stop]. Changes background color."}, {"cls": "origam-slider-field-track__tick--first", "descriptionKey": "components.slider_field_track.anatomy.tick_first", "descriptionFallback": "Applied to the first tick (value === min). Label transform is reset to none."}, {"cls": "origam-slider-field-track__tick--last", "descriptionKey": "components.slider_field_track.anatomy.tick_last", "descriptionFallback": "Applied to the last tick (value === max). Label translates −100% to align right."}, {"cls": "origam-slider-field-track__tick-label", "descriptionKey": "components.slider_field_track.anatomy.tick_label", "descriptionFallback": "Tick label text. position: absolute, white-space: nowrap, user-select: none."}], "svgDesc": "Schematic of the slider track with background, fill and tick layers.", "svgTitle": "Anatomy of OrigamSliderFieldTrack", "rootClass": "origam-slider-field-track", "figcaption": "A