INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('7b31f838-7cff-4cba-82d2-204dc85f39d7', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'tab-panel', 'TabPanel', 'Navigation', NULL, 'mdi-tab', 'components.catalog.tab_panel.description', 'A single tab content panel — lazy-mounted by default until first activated, then kept alive via v-show.', NULL, NULL, 'origam-tab-panel', NULL, 'packages/ds/src/components/Tabs/OrigamTabPanel.vue', 'origam', NULL, NULL, '/stories/?story=components-tabs--design', '/docs/components/Tabs/OrigamTabs.html', 'tabs', '{"a11y": {"notes": [{"noteKey": "components.tab_panel.a11y.aria_note", "noteFallback": "OrigamTabPanel sets role=\"tabpanel\" and aria-labelledby pointing to the sibling tab DOM id automatically. No manual ARIA needed."}, {"noteKey": "components.tab_panel.a11y.lazy_note", "noteFallback": "Content is not in the DOM until the panel is first activated (unless eager=true). Screen readers only perceive the content after it is mounted."}, {"noteKey": "components.tab_panel.a11y.vshow_note", "noteFallback": "Inactive panels use v-show (not v-if) after first mount, so content remains in the DOM. Assistive technologies may still reach it via search — the v-show=\"false\" (display: none) does hide it from AT per ARIA spec."}], "roles": ["tabpanel"], "keyboard": [{"key": "Tab", "actionKey": "components.tab_panel.a11y.key_tab", "actionFallback": "Moves focus into the panel content from the tablist."}, {"key": "Shift + Tab", "actionKey": "components.tab_panel.a11y.key_shift_tab", "actionFallback": "Returns focus to the active tab in the tablist."}]}, "tokens": {"excer