ext---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">① = role=\"tabpanel\" · tabindex=0 · aria-labelledby; ② = lazy #default slot</text>\n", "code": "<!-- root: role=\"tabpanel\", tabindex=0, aria-labelledby -->\n<Transition name=\"fade\" mode=\"out-in\">\n  <div\n    v-show=\"isShown\"\n    class=\"origam-tab-panel\"\n    role=\"tabpanel\"\n    tabindex=\"0\"\n    :aria-labelledby=\"tabLabelledBy\"\n  >\n    <!-- lazy slot: only renders after first activation -->\n    <slot v-if=\"hasContent\" name=\"default\" />\n  </div>\n</Transition>", "legend": [{"cls": ".origam-tab-panel", "num": 1, "descriptionKey": "components.tab_panel.anatomy.root", "descriptionFallback": "Root element. Carries <code>role=\"tabpanel\"</code>, <code>tabindex=\"0\"</code> and <code>aria-labelledby</code> pointing to the matching tab id. Hidden via <code>v-show</code> when inactive."}, {"cls": "#default slot", "num": 2, "descriptionKey": "components.tab_panel.anatomy.slot", "descriptionFallback": "Slot content area. Lazy-mounted on first activation via <code>useLazy</code> — renders only after the panel becomes selected for the first time."}], "classes": [{"cls": "origam-tab-panel", "descriptionKey": "components.tab_panel.anatomy.root", "descriptionFallback": "Root element. role=\"tabpanel\", tabindex=0, aria-labelledby, hidden via v-show when inactive."}, {"cls": "origam-tab-panel--active", "descriptionKey": "components.tab_panel.anatomy.active", "descriptionFallback": "Applied when this panel is the selected item in the panels group."}], "svgDesc": "Schematic of the TabPanel component with 2 numbered internal parts.", "svgTitle": "Anatomy of OrigamTabPanel", "rootClass": "origam-tab-panel", "figcaption": "Anatomy of <code>&lt;origam-tab-panel&gt;</code> — 2 parts. The root carries <code>role=\"tabpanel\"</code> and <code>aria-labelledby</code> pointing to the sibling tab; the slot content is lazy-mounted on first activation.", "svgViewBox": "0 0 560 180"}, "cssVars": [{"name": "--origam-tab-panels__panel---padding-block", "defaultValue": "16px", "descriptionKey": "components.tab_panel.css_vars.padding_block", "descriptionFallback": "Vertical padding applied to each tab panel via the parent OrigamTabPanels."}, {"name": "--origam-tab-panels__panel---padding-inline", "defaultValue": "0", "descriptionKey": "components.tab_panel.css_vars.padding_inline", "descriptionFallback": "Horizontal padding applied to each tab panel via the parent OrigamTabPanels."}, {"name": "--origam-tab-panels__panel---transition-duration", "defaultValue": "0.18s", "descriptionKey": "components.tab_panel.css_vars.transition_duration", "descriptionFallback": "Duration of the fade transition when switching panels."}, {"name": "--origam-tab-panels__panel--focus---outline-color", "defaultValue": "currentColor", "descriptionKey": "components.tab_panel.css_vars.focus_outline_color", "descriptionFallback": "Outline color shown on focus-visible for the panel container."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.tab_panel.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.tab_panel.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed panel styles."}, {"name": "id", "type": "string", "descriptionKey": "components.tab_panel.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.tab_panel.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.tab_panel.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.tab_panel.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "eager", "labelKey": "components.tab_panel.playground.eager", "defaultValue": false, "labelFallback": "Eager mount"}], "defaultSlotContent": ""}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0285f230-5b87-46f3-9fd0-10920ef6c3ff', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'tab-panels', 'TabPanels', 'Navigation', NULL, 'mdi-tab', 'components.catalog.tab_panels.description', 'Content container that mirrors the tablist selection — orchestrates OrigamTabPanel children with optional fade transition and swipe support.', NULL, NULL, 'origam-tab-panels', NULL, 'packages/ds/src/components/Tabs/OrigamTabPanels.vue', 'origam', NULL, NULL, '/stories/?story=components-tabs--design', '/docs/components/Tabs/OrigamTabs.html', 'tabs', '{"a11y": {"notes": [{"noteKey": "components.tab_panels.a11y.sync_note", "noteFallback": "OrigamTabPanels has no ARIA role of its own — it is a layout orchestrator. ARIA semantics live on each child OrigamTabPanel (role=\"tabpanel\")."}, {"noteKey": "components.tab_panels.a11y.sync_model_note", "noteFallback": "Keep the v-model in sync with the sibling OrigamTabs v-model. Desynchronised models break the aria-controls / aria-labelledby wiring between tabs and panels."}], "roles": [], "keyboard": [{"key": "Swipe left / right", "actionKey": "components.tab_panels.a11y.swipe", "actionFallback": "When swipeable=true, horizontal swipe navigates to the next/previous panel."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-tab-panels__panel---padding-block", "descriptionKey": "components.tab_panels.tokens.padding_block", "descriptionFallback": "Default vertical padding for panel content."}, {"type": "dimension", "value": "var(--origam-space---0)", "tokenPath": "--origam-tab-panels__panel---padding-inline", "descriptionKey": "components.tab_panels.tokens.padding_inline", "descriptionFallback": "Default horizontal padding for panel content."}, {"type": "duration", "value": "var(--origam-motion__duration---fast)", "tokenPath": "--origam-tabs__panel---transition-duration", "descriptionKey": "components.tab_panels.tokens.transition_duration", "descriptionFallback": "Duration of the fade transition between panels."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"30\" y=\"36\" width=\"540\" height=\"140\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"50\" y=\"56\" width=\"500\" height=\"100\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <rect x=\"70\" y=\"76\" width=\"460\" height=\"60\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"300\" y=\"110\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-tab-panel (active)</text>\n  <circle cx=\"42\" cy=\"44\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"42\" y=\"48.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"62\" cy=\"64\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"62\" y=\"68\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"82\" cy=\"84\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"82\" y=\"88\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <line x1=\"42\" y1=\"32\" x2=\"70\" y2=\"14\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"74\" y=\"12\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-tab-panels</text>\n  <text x=\"300\" y=\"180\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">① root · ② defaults-provider · ③ active origam-tab-panel</text>\n", "code": "<!-- root: manages group + provides transition context -->\n<div class=\"origam-tab-panels\" v-touch=\"touchOptions\">\n  <!-- internal defaults provider forwards transition to all child panels -->\n  <origam-defaults-provider :defaults=\"slotDefaults\">\n    <!-- #default slot: place origam-tab-panel children here -->\n    <slot name=\"default\" v-bind=\"slotProps\" />\n  </origam-defaults-provider>\n</div>", "legend": [{"cls": ".origam-tab-panels", "num": 1, "descriptionKey": "components.tab_panels.anatomy.root", "descriptionFallback": "Root element. Manages the panel group via <code>useGroup</code> and provides transition context via <code>ORIGAM_TAB_PANELS_CTX_KEY</code>."}, {"cls": "OrigamDefaultsProvider (internal)", "num": 2, "descriptionKey": "components.tab_panels.anatomy.defaults_provider", "descriptionFallback": "Internal <code>&lt;OrigamDefaultsProvider&gt;</code> that injects the <code>transition</code> prop into child <code>&lt;OrigamTabPanel&gt;</code> elements without requiring explicit prop drilling."}, {"cls": ".origam-tab-panel--active", "num": 3, "descriptionKey": "components.tab_panels.anatomy.active_panel", "descriptionFallback": "The currently visible panel. Inactive panels remain in the DOM via <code>v-show</code> after first mount."}], "classes": [{"cls": "origam-tab-panels", "descriptionKey": "components.tab_panels.anatomy.root", "descriptionFallback": "Root element. display: block; position: relative. Provides transition context to child panels."}, {"cls": "origam-tab-panels--direction-vertical", "descriptionKey": "components.tab_panels.anatomy.vertical", "descriptionFallback": "Applied when direction=\"vertical\". Switches to display: flex; flex-direction: row."}, {"cls": "origam-tab-panels--swipeable", "descriptionKey": "components.tab_panels.anatomy.swipeable", "descriptionFallback": "Applied when swipeable=true. Adds overflow: hidden and touch-action: pan-y."}], "svgDesc": "Schematic of the TabPanels container with 3 numbered parts.", "svgTitle": "Anatomy of OrigamTabPanels", "rootClass": "origam-tab-panels", "figcaption": "Anatomy of <code>&lt;origam-tab-panels&gt;</code> — 3 layers. The root wraps an <code>&lt;OrigamDefaultsProvider&gt;</code> that forwards the <code>transition</code> prop to child panels. Only the active panel is shown; others are <code>v-show</code>-hidden.", "svgViewBox": "0 0 600 200"}, "cssVars": [{"name": "--origam-tab-panels__panel---padding-block", "defaultValue": "16px", "descriptionKey": "components.tab_panels.css_vars.padding_block", "descriptionFallback": "Vertical padding applied inside the tab panels container."}, {"name": "--origam-tab-panels__panel---padding-inline", "defaultValue": "0", "descriptionKey": "components.tab_panels.css_vars.padding_inline", "descriptionFallback": "Horizontal padding applied inside the tab panels container."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.tab_panels.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "next", "type": "() => void", "descriptionKey": "components.tab_panels.exposed.next", "descriptionFallback": "Programmatically selects the next panel in registration order."}, {"name": "prev", "type": "() => void", "descriptionKey": "components.tab_panels.exposed.prev", "descriptionFallback": "Programmatically selects the previous panel in registration order."}, {"name": "select", "type": "(value: any, selected: boolean) => void", "descriptionKey": "components.tab_panels.exposed.select", "descriptionFallback": "Programmatically selects a panel by its registered value."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.tab_panels.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.tab_panels.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.tab_panels.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.tab_panels.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.tab_panels.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "transition", "options": [{"label": "fade (default)", "value": "fade"}, {"label": "(none)", "value": ""}], "labelKey": "components.tab_panels.playground.transition", "defaultValue": "fade", "labelFallback": "Transition"}, {"kind": "switch", "prop": "swipeable", "labelKey": "components.tab_panels.playground.swipeable", "defaultValue": false, "labelFallback": "Swipeable"}, {"kind": "select", "prop": "direction", "options": [{"label": "horizontal", "value": "horizontal"}, {"label": "vertical", "value": "vertical"}], "labelKey": "components.tab_panels.playground.direction", "defaultValue": "horizontal", "labelFallback": "Direction"}], "defaultSlotContent": ""}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
