INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('5d8ae645-2f13-4e71-af57-8728fd25e764', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'treeview', 'Treeview', 'Data Display', NULL, 'mdi-file-tree', 'components.catalog.treeview.description', 'Hierarchical tree structure with expand/collapse, single/multi selection and optional guide lines. Items are defined via a typed ITreeviewNode list.', NULL, NULL, 'origam-treeview', NULL, 'packages/ds/src/components/Treeview/OrigamTreeview.vue', 'origam', NULL, NULL, '/stories/?story=components-treeview--design', '/docs/components/Treeview/OrigamTreeview.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.treeview.a11y.aria_roles", "noteFallback": "Root element has role=\"tree\"; each node has role=\"treeitem\". aria-selected, aria-expanded and aria-disabled are set reactively."}, {"noteKey": "components.treeview.a11y.multiselect", "noteFallback": "aria-multiselectable is set to true on the tree root when selectMode=\"multiple\"."}], "roles": ["tree", "treeitem"], "keyboard": [{"key": "ArrowRight", "actionKey": "components.treeview.a11y.key_expand", "actionFallback": "Expands a collapsed node, or moves focus to the first child of an already-expanded node."}, {"key": "ArrowLeft", "actionKey": "components.treeview.a11y.key_collapse", "actionFallback": "Collapses an expanded node, or moves focus to the parent node."}, {"key": "ArrowDown / ArrowUp", "actionKey": "components.treeview.a11y.key_vertical", "actionFallback": "Moves focus to the next/previous visible node in the tree."}, {"key": "Enter / Space", "actionKey": "components.treeview.a11y.key_select", "actionFallback": "Selects the focused node (when selectMode is not none)."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---default)", "tokenPath": "--origam-treeview---background-color", "descriptionKey": "components.treeview.tokens.background_color", "descriptionFallback": "Tree background."}, {"type": "color", "value": "var(--origam-color__action--primary---bgSubtle)", "tokenPath": "--origam-treeview---row-bg-selected", "descriptionKey": "components.treeview.tokens.row_bg_selected", "descriptionFallback": "Row background when selected."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-treeview---indent-size", "descriptionKey": "components.treeview.tokens.indent_size", "descriptionFallback": "Indentation per depth level."}, {"type": "color", "value": "var(--origam-color__border---subtle)", "tokenPath": "--origam-treeview---guide-color", "descriptionKey": "components.treeview.tokens.guide_color", "descriptionFallback": "Guide line color."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"380\" height=\"180\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <line x1=\"50\" y1=\"60\" x2=\"50\" y2=\"160\" stroke=\"var(--origam-color__border---subtle, rgba(168,85,247,0.3))\" stroke-width=\"1.5\"/>\n  <rect x=\"30\" y=\"50\" width=\"350\" height=\"36\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\"/>\n  <text x=\"70\" y=\"71\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" font-family=\"''JetBrains Mono'',monospace\">src/</text>\n  <text x=\"40\" y=\"71\" font-size=\"14\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\">›</text>\n  <rect x=\"50\" y=\"100\" width=\"320\" height=\"32\" rx=\"4\" fill=\"transparent\"/>\n  <text x=\"80\" y=\"121\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" font-family=\"''JetBrains Mono'',monospace\">main.ts</text>\n  <rect x=\"50\" y=\"140\" width=\"320\" height=\"32\" rx=\"4\" fill=\"transparent\"/>\n  <text x=\"80\" y=\"161\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" font-family=\"''JetBrains Mono'',monospace\">App.vue</text>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"38\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"38\" y=\"62\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"50\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"50\" y=\"62\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"50\" cy=\"110\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"50\" y=\"114\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<div role=\"tree\" class=\"origam-treeview\" aria-label=\"File tree\">\n  <origam-treeview-node\n    v-for=\"node in items\"\n    :key=\"node.id\"\n    :node=\"node\"\n    :depth=\"0\"\n  />\n</div>", "legend": [{"cls": ".origam-treeview", "num": 1, "descriptionKey": "components.treeview.anatomy.root", "descriptionFallback": "Root element. role=\"tree\", aria-multiselectable when selectMode=\"multiple\"."}, {"cls": ".origam-treeview-node", "num": 2, "descriptionKey": "components.treeview.anatomy.node", "descriptionFallback": "Each node row. role=\"treeitem\". aria-selected, aria-expanded, aria-disabled are set dynamically."}, {"cls": ".origam-treeview-node__chevron", "num": 3, "descriptionKey": "components.treeview.anatomy.chevron", "descriptionFallback": "Expand/collapse indicator. Rotated 90° when the node is expanded."}, {"cls": ".origam-treeview-node__children", "num": 4, "descriptionKey": "components.treeview.anatomy.children", "descriptionFallback": "Container for child nodes. Indented by indent-size per depth level."}], "classes": [{"cls": "origam-treeview", "descriptionKey": "components.treeview.anatomy.root", "descriptionFallback": "Root tree container."}, {"cls": "origam-treeview-node", "descriptionKey": "components.treeview.anatomy.node", "descriptionFallback": "Individual node wrapper."}, {"cls": "origam-treeview-node__chevron", "descriptionKey": "components.treeview.anatomy.chevron", "descriptionFallback": "Expand icon."}, {"cls": "origam-treeview-node__label", "descriptionKey": "components.treeview.anatomy.label", "descriptionFallback": "Node label text."}, {"cls": "origam-treeview-node__children", "descriptionKey": "components.treeview.anatomy.children", "descriptionFallback": "Children container (indented)."}], "svgDesc": "Schematic showing the Treeview root and one TreeviewNode with its parts.", "svgTitle": "Anatomy of OrigamTreeview", "rootClass": "origam-treeview", "figcaption": "Anatomy of <code>&lt;origam-treeview&gt;</code> — the root ① is a <code>role=\"tree\"</code> container; each node ② is a <code>role=\"treeitem\"</code> with a chevron ③ and recursive children ④.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-treeview---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.treeview.css_vars.background_color", "descriptionFallback": "Treeview background color."}, {"name": "--origam-treeview---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.treeview.css_vars.color", "descriptionFallback": "Default node text color."}, {"name": "--origam-treeview---indent-size", "defaultValue": "{space.4}", "descriptionKey": "components.treeview.css_vars.indent_size", "descriptionFallback": "Per-depth indentation size."}, {"name": "--origam-treeview---row-height", "defaultValue": "{space.8}", "descriptionKey": "components.treeview.css_vars.row_height", "descriptionFallback": "Height of each tree row."}, {"name": "--origam-treeview---row-bg-hover", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.treeview.css_vars.row_bg_hover", "descriptionFallback": "Row background on hover."}, {"name": "--origam-treeview---row-bg-selected", "defaultValue": "{color.action.primary.bgSubtle}", "descriptionKey": "components.treeview.css_vars.row_bg_selected", "descriptionFallback": "Row background when selected."}, {"name": "--origam-treeview---guide-color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.treeview.css_vars.guide_color", "descriptionFallback": "Color of the vertical guide lines (show-lines)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.treeview.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}, {"name": "isExpanded", "type": "(id: string) => boolean", "descriptionKey": "components.treeview.exposed.is_expanded", "descriptionFallback": "Returns true if the given node id is currently expanded."}, {"name": "isSelected", "type": "(id: string) => boolean", "descriptionKey": "components.treeview.exposed.is_selected", "descriptionFallback": "Returns true if the given node id is in the selected set."}, {"name": "toggleExpanded", "type": "(id: string) => void", "descriptionKey": "components.treeview.exposed.toggle_expanded", "descriptionFallback": "Programmatically expand or collapse a node by id."}, {"name": "toggleSelected", "type": "(id: string) => void", "descriptionKey": "components.treeview.exposed.toggle_selected", "descriptionFallback": "Programmatically select or deselect a node by id."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.treeview.exposed.css", "descriptionFallback": "Reactive CSS string for computed styles."}, {"name": "id", "type": "string", "descriptionKey": "components.treeview.exposed.id", "descriptionFallback": "Unique style-sheet ID."}, {"name": "load", "type": "() => void", "descriptionKey": "components.treeview.exposed.load", "descriptionFallback": "Injects the style sheet on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.treeview.exposed.unload", "descriptionFallback": "Removes the style sheet on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.treeview.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "selectMode", "options": [{"label": "none", "value": "none"}, {"label": "single", "value": "single"}, {"label": "multiple", "value": "multiple"}], "labelKey": "components.treeview.playground.select_mode", "defaultValue": "none", "labelFallback": "Select mode"}, {"kind": "select", "prop": "selectableNodes", "options": [{"label": "leaf", "value": "leaf"}, {"label": "branch", "value": "branch"}, {"label": "all", "value": "all"}], "labelKey": "components.treeview.playground.selectable_nodes", "defaultValue": "leaf", "labelFallback": "Selectable nodes"}, {"kind": "switch", "prop": "showLines", "labelKey": "components.treeview.playground.show_lines", "defaultValue": true, "labelFallback": "Show guide lines"}, {"kind": "switch", "prop": "expandOnClick", "labelKey": "components.treeview.playground.expand_on_click", "defaultValue": false, "labelFallback": "Expand on row click"}, {"kind": "select", "prop": "color", "options": [{"label": "primary", "value": "primary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.treeview.playground.color", "defaultValue": "primary", "labelFallback": "Selection color"}]}, "previewVariants": [{"label": "default tree", "props": {"showLines": true, "selectMode": "none", "expandOnClick": false}}, {"label": "single select", "props": {"showLines": true, "selectMode": "single", "expandOnClick": true}}, {"label": "no lines", "props": {"showLines": false, "selectMode": "none"}}, {"label": "colored selection", "props": {"color": "primary", "showLines": true, "selectMode": "single"}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('b1ba0008-10cf-4739-a2a6-d39de76724fd', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'treeview-node', 'TreeviewNode', 'Data Display', NULL, 'mdi-file-tree', 'components.catalog.treeview_node.description', 'Single node in a Treeview — renders chevron, icon, label and size badge; recursively renders children when expanded. Handles its own expand/select keyboard interactions.', NULL, NULL, 'origam-treeview-node', NULL, 'packages/ds/src/components/Treeview/OrigamTreeviewNode.vue', 'origam', NULL, NULL, '/stories/?story=components-treeview--design', '/docs/components/Treeview/OrigamTreeview.html', 'treeview', '{"a11y": {"notes": [{"noteKey": "components.treeview_node.a11y.role_note", "noteFallback": "OrigamTreeviewNode uses a wrapper with role=\"none\" and an inner interactive div with role=\"treeitem\". ARIA attributes (aria-expanded, aria-selected, aria-disabled, aria-label) are applied to the inner row only."}, {"noteKey": "components.treeview_node.a11y.group_note", "noteFallback": "The children container uses role=\"group\" with aria-label=\"{node.label} contents\" as required by the ARIA tree pattern."}, {"noteKey": "components.treeview_node.a11y.focus_note", "noteFallback": "Focus-visible outline is applied on the row via :focus-visible (2px solid, outline-offset: -2px)."}, {"noteKey": "components.treeview_node.a11y.decorative_note", "noteFallback": "Guide lines, chevron and icon are all aria-hidden=\"true\". Only the label contributes to the accessible name (supplemented by aria-label=\"node.label\" on the treeitem)."}], "roles": ["treeitem"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.treeview_node.a11y.key_activate", "actionFallback": "Selects the node (if selectable) or toggles expansion (if it has children and is not selectable)."}, {"key": "ArrowRight", "actionKey": "components.treeview_node.a11y.key_arrow_right", "actionFallback": "If collapsed and has children: expands. If expanded and has children: moves focus to first child."}, {"key": "ArrowLeft", "actionKey": "components.treeview_node.a11y.key_arrow_left", "actionFallback": "If expanded: collapses the node. If collapsed: moves focus to the parent treeitem."}, {"key": "Tab", "actionKey": "components.treeview_node.a11y.key_tab", "actionFallback": "Moves focus out of the tree to the next focusable element in the page."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-treeview---indent-size", "descriptionKey": "components.treeview_node.tokens.indent_size", "descriptionFallback": "Indent per depth level."}, {"type": "dimension", "value": "var(--origam-space---8)", "tokenPath": "--origam-treeview---row-height", "descriptionKey": "components.treeview_node.tokens.row_height", "descriptionFallback": "Minimum row height."}, {"type": "color", "value": "var(--origam-color__surface---overlay)", "tokenPath": "--origam-treeview---row-bg-hover", "descriptionKey": "components.treeview_node.tokens.row_bg_hover", "descriptionFallback": "Row background on hover."}, {"type": "color", "value": "var(--origam-color__action--primary---bgSubtle)", "tokenPath": "--origam-treeview---row-bg-selected", "descriptionKey": "components.treeview_node.tokens.row_bg_selected", "descriptionFallback": "Row background when selected."}, {"type": "dimension", "value": "var(--origam-font__size---sm)", "tokenPath": "--origam-treeview---label-font-size", "descriptionKey": "components.treeview_node.tokens.label_font_size", "descriptionFallback": "Font size of the node label."}, {"type": "color", "value": "var(--origam-color__border---subtle)", "tokenPath": "--origam-treeview---guide-color", "descriptionKey": "components.treeview_node.tokens.guide_color", "descriptionFallback": "Color of the vertical guide lines."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"640\" height=\"280\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <!-- node wrapper -->\n  <rect x=\"20\" y=\"30\" width=\"600\" height=\"230\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- row -->\n  <rect x=\"36\" y=\"46\" width=\"568\" height=\"48\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\"/>\n  <!-- guide lines (2 levels) -->\n  <rect x=\"48\" y=\"46\" width=\"2\" height=\"48\" fill=\"var(--origam-color__border---subtle, rgba(168,85,247,0.3))\"/>\n  <rect x=\"64\" y=\"46\" width=\"2\" height=\"48\" fill=\"var(--origam-color__border---subtle, rgba(168,85,247,0.2))\"/>\n  <!-- chevron -->\n  <rect x=\"72\" y=\"58\" width=\"20\" height=\"24\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"82\" y=\"74\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\">›</text>\n  <!-- icon -->\n  <rect x=\"98\" y=\"58\" width=\"24\" height=\"24\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"110\" y=\"74\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #1a1035)\" text-anchor=\"middle\">📁</text>\n  <!-- label -->\n  <rect x=\"130\" y=\"58\" width=\"300\" height=\"24\" rx=\"2\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <text x=\"240\" y=\"74\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #1a1035)\" font-family=\"''JetBrains Mono'',monospace\">node.label</text>\n  <!-- size -->\n  <rect x=\"438\" y=\"58\" width=\"60\" height=\"24\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\"/>\n  <text x=\"468\" y=\"74\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">size</text>\n  <!-- slot node -->\n  <rect x=\"36\" y=\"106\" width=\"568\" height=\"36\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.20))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"320\" y=\"128\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#node slot</text>\n  <!-- children group -->\n  <rect x=\"36\" y=\"154\" width=\"568\" height=\"88\" rx=\"3\" fill=\"var(--origam-color__surface---sunken, #f9f5ff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.20))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"320\" y=\"200\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-treeview-node (recursive children)</text>\n  <!-- numbers -->\n  <circle cx=\"30\" cy=\"38\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"30\" y=\"42.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"44\" cy=\"54\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"44\" y=\"58\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"48\" cy=\"70\" r=\"7\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"48\" y=\"74\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"82\" cy=\"54\" r=\"7\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"82\" y=\"58\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"110\" cy=\"54\" r=\"7\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"110\" y=\"58\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"240\" cy=\"54\" r=\"7\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"240\" y=\"58\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <circle cx=\"468\" cy=\"54\" r=\"7\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"468\" y=\"58\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">7</text>\n  <circle cx=\"320\" cy=\"162\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"320\" y=\"166\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">8</text>\n  <line x1=\"30\" y1=\"26\" x2=\"60\" y2=\"10\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"64\" y=\"8\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-treeview-node</text>\n  <text x=\"320\" y=\"260\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">③ guide lines · ④ chevron · ⑤ icon · ⑥ label · ⑦ size — inside ② row; ⑧ = recursive children</text>\n", "code": "<!-- root: role=\"none\" (ARIA on inner row) -->\n<div class=\"origam-treeview-node\" role=\"none\">\n  <!-- interactive row: role=\"treeitem\" -->\n  <div\n    class=\"origam-treeview-node__row\"\n    role=\"treeitem\"\n    :aria-expanded=\"hasChildren ? isNodeExpanded : undefined\"\n    :aria-selected=\"isSelectable ? isNodeSelected : undefined\"\n    :aria-disabled=\"node.disabled || undefined\"\n    :aria-label=\"node.label\"\n    tabindex=\"0\"\n  >\n    <!-- guide lines (once per depth, v-for + v-if) -->\n    <span class=\"origam-treeview-node__guide\" aria-hidden=\"true\" />\n\n    <!-- chevron: rotates on expand, hidden on leaves -->\n    <span class=\"origam-treeview-node__chevron\" aria-hidden=\"true\">\n      &#8250;\n    </span>\n\n    <!-- icon: custom, folder, or leaf -->\n    <span class=\"origam-treeview-node__icon\" aria-hidden=\"true\" />\n\n    <!-- label text -->\n    <span class=\"origam-treeview-node__label\">{{ node.label }}</span>\n\n    <!-- optional size badge -->\n    <span class=\"origam-treeview-node__size\">{{ node.size }}</span>\n  </div>\n\n  <!-- custom #node slot (after the row) -->\n  <slot name=\"node\" :node=\"node\" :depth=\"depth\" :is-expanded=\"isNodeExpanded\" :is-selected=\"isNodeSelected\" />\n\n  <!-- recursive children (v-if=\"isNodeExpanded && hasChildren\") -->\n  <div class=\"origam-treeview-node__children\" role=\"group\">\n    <origam-treeview-node v-for=\"child in node.children\" :key=\"child.id\" :node=\"child\" :depth=\"depth + 1\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-treeview-node", "num": 1, "descriptionKey": "components.treeview_node.anatomy.root", "descriptionFallback": "Root wrapper, <code>role=\"none\"</code>. Flex column, no ARIA role — ARIA is on the inner row."}, {"cls": ".origam-treeview-node__row", "num": 2, "descriptionKey": "components.treeview_node.anatomy.row", "descriptionFallback": "Interactive row. <code>role=\"treeitem\"</code>, <code>aria-expanded</code>, <code>aria-selected</code>, <code>aria-disabled</code>, <code>tabindex</code>. Handles click and keyboard events."}, {"cls": ".origam-treeview-node__guide", "num": 3, "descriptionKey": "components.treeview_node.anatomy.guide", "descriptionFallback": "Vertical guide line repeated once per depth level (depth > 0 and showLines=true). <code>aria-hidden=\"true\"</code>."}, {"cls": ".origam-treeview-node__chevron", "num": 4, "descriptionKey": "components.treeview_node.anatomy.chevron", "descriptionFallback": "Expand/collapse indicator. Rotates 90° when expanded. Invisible (<code>visibility: hidden</code>) on leaf nodes."}, {"cls": ".origam-treeview-node__icon", "num": 5, "descriptionKey": "components.treeview_node.anatomy.icon", "descriptionFallback": "Node icon — custom <code>node.icon</code>, or a folder emoji (expanded/collapsed), or a document emoji for leaves. <code>aria-hidden=\"true\"</code>."}, {"cls": ".origam-treeview-node__label", "num": 6, "descriptionKey": "components.treeview_node.anatomy.label", "descriptionFallback": "Node label text. <code>flex: 1</code>, truncated with ellipsis. Uses the <code>node.label</code> value."}, {"cls": ".origam-treeview-node__size", "num": 7, "descriptionKey": "components.treeview_node.anatomy.size", "descriptionFallback": "Optional size badge. Only rendered when <code>node.size</code> is provided."}, {"cls": ".origam-treeview-node__children", "num": 8, "descriptionKey": "components.treeview_node.anatomy.children", "descriptionFallback": "Children container, <code>role=\"group\"</code>, <code>aria-label=\"{node.label} contents\"</code>. Shown only when expanded. Recursively renders <code>&lt;OrigamTreeviewNode&gt;</code> for each child."}], "classes": [{"cls": "origam-treeview-node", "descriptionKey": "components.treeview_node.anatomy.root", "descriptionFallback": "Root wrapper. role=\"none\", flex column."}, {"cls": "origam-treeview-node--expanded", "descriptionKey": "components.treeview_node.anatomy.expanded", "descriptionFallback": "Applied when the node is in expanded state."}, {"cls": "origam-treeview-node--selected", "descriptionKey": "components.treeview_node.anatomy.selected", "descriptionFallback": "Applied when the node is in selected state."}, {"cls": "origam-treeview-node--disabled", "descriptionKey": "components.treeview_node.anatomy.disabled", "descriptionFallback": "Applied when node.disabled=true."}, {"cls": "origam-treeview-node__row", "descriptionKey": "components.treeview_node.anatomy.row", "descriptionFallback": "Interactive row element. Carries role=\"treeitem\" and all ARIA attributes."}, {"cls": "origam-treeview-node__row--selected", "descriptionKey": "components.treeview_node.anatomy.row_selected", "descriptionFallback": "Applied to the row when selected."}, {"cls": "origam-treeview-node__row--disabled", "descriptionKey": "components.treeview_node.anatomy.row_disabled", "descriptionFallback": "Applied to the row when disabled."}, {"cls": "origam-treeview-node__row--selectable", "descriptionKey": "components.treeview_node.anatomy.row_selectable", "descriptionFallback": "Applied to the row when the node can be selected."}, {"cls": "origam-treeview-node__guide", "descriptionKey": "components.treeview_node.anatomy.guide", "descriptionFallback": "Vertical guide line. Rendered once per depth level when showLines is active."}, {"cls": "origam-treeview-node__chevron", "descriptionKey": "components.treeview_node.anatomy.chevron", "descriptionFallback": "Expand indicator. Rotates on expand, hidden on leaf nodes."}, {"cls": "origam-treeview-node__chevron--expanded", "descriptionKey": "components.treeview_node.anatomy.chevron_expanded", "descriptionFallback": "Applied when node is expanded. Rotates chevron 90°."}, {"cls": "origam-treeview-node__chevron--hidden", "descriptionKey": "components.treeview_node.anatomy.chevron_hidden", "descriptionFallback": "Applied on leaf nodes (visibility: hidden, space preserved)."}, {"cls": "origam-treeview-node__icon", "descriptionKey": "components.treeview_node.anatomy.icon", "descriptionFallback": "Node icon element. aria-hidden=\"true\"."}, {"cls": "origam-treeview-node__label", "descriptionKey": "components.treeview_node.anatomy.label", "descriptionFallback": "Node label. flex: 1, truncated with ellipsis."}, {"cls": "origam-treeview-node__size", "descriptionKey": "components.treeview_node.anatomy.size", "descriptionFallback": "Size badge. Only rendered when node.size is provided."}, {"cls": "origam-treeview-node__children", "descriptionKey": "components.treeview_node.anatomy.children", "descriptionFallback": "Children container. role=\"group\", shown only when expanded."}], "svgDesc": "Schematic of the TreeviewNode component with 8 numbered internal parts.", "svgTitle": "Anatomy of OrigamTreeviewNode", "rootClass": "origam-treeview-node", "figcaption": "Anatomy of <code>&lt;origam-treeview-node&gt;</code> — 8 parts. The root wrapper holds the interactive row (with guide lines, chevron, icon, label and size) followed by the optional node slot and the recursive children group.", "svgViewBox": "0 0 640 280"}, "cssVars": [{"name": "--origam-treeview---indent-size", "defaultValue": "16px", "descriptionKey": "components.treeview_node.css_vars.indent_size", "descriptionFallback": "Indent per depth level. Applied via CSS calc on the row padding-inline-start."}, {"name": "--origam-treeview---row-height", "defaultValue": "32px", "descriptionKey": "components.treeview_node.css_vars.row_height", "descriptionFallback": "Minimum row height."}, {"name": "--origam-treeview---row-padding-inline", "defaultValue": "8px", "descriptionKey": "components.treeview_node.css_vars.row_padding_inline", "descriptionFallback": "Horizontal padding added to the base indent on the row."}, {"name": "--origam-treeview---row-bg-hover", "defaultValue": "var(--origam-color__surface---overlay)", "descriptionKey": "components.treeview_node.css_vars.row_bg_hover", "descriptionFallback": "Row background on hover."}, {"name": "--origam-treeview---row-bg-selected", "defaultValue": "var(--origam-color__action--primary---bgSubtle)", "descriptionKey": "components.treeview_node.css_vars.row_bg_selected", "descriptionFallback": "Row background when selected."}, {"name": "--origam-treeview---row-color-selected", "defaultValue": "var(--origam-color__action--primary---fgSubtle)", "descriptionKey": "components.treeview_node.css_vars.row_color_selected", "descriptionFallback": "Label color when selected."}, {"name": "--origam-treeview---row-color-disabled", "defaultValue": "var(--origam-color__text---disabled)", "descriptionKey": "components.treeview_node.css_vars.row_color_disabled", "descriptionFallback": "Label color when disabled."}, {"name": "--origam-treeview---chevron-size", "defaultValue": "16px", "descriptionKey": "components.treeview_node.css_vars.chevron_size", "descriptionFallback": "Width and height of the chevron element."}, {"name": "--origam-treeview---chevron-color", "defaultValue": "var(--origam-color__text---secondary)", "descriptionKey": "components.treeview_node.css_vars.chevron_color", "descriptionFallback": "Color of the chevron glyph."}, {"name": "--origam-treeview---guide-color", "defaultValue": "var(--origam-color__border---subtle)", "descriptionKey": "components.treeview_node.css_vars.guide_color", "descriptionFallback": "Color of the vertical guide lines."}, {"name": "--origam-treeview---guide-thickness", "defaultValue": "1px", "descriptionKey": "components.treeview_node.css_vars.guide_thickness", "descriptionFallback": "Thickness of the vertical guide lines."}, {"name": "--origam-treeview---label-font-size", "defaultValue": "0.75rem", "descriptionKey": "components.treeview_node.css_vars.label_font_size", "descriptionFallback": "Font size of the node label."}, {"name": "--origam-treeview---icon-size", "defaultValue": "16px", "descriptionKey": "components.treeview_node.css_vars.icon_size", "descriptionFallback": "Font size of the node icon."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.treeview_node.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "isNodeExpanded", "type": "ComputedRef<boolean>", "descriptionKey": "components.treeview_node.exposed.is_node_expanded", "descriptionFallback": "Reactive ref: true when this node is currently expanded."}, {"name": "isNodeSelected", "type": "ComputedRef<boolean>", "descriptionKey": "components.treeview_node.exposed.is_node_selected", "descriptionFallback": "Reactive ref: true when this node is currently selected."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.treeview_node.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.treeview_node.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.treeview_node.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.treeview_node.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.treeview_node.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "number", "prop": "depth", "labelKey": "components.treeview_node.playground.depth", "defaultValue": 0, "labelFallback": "Depth level"}], "defaultSlotContent": ""}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c5007f06-4c7d-4d61-b37c-d9af197c2c8a', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'video', 'Video', 'Media', NULL, 'mdi-video', 'components.catalog.video.description', 'Full-featured HTML5 video player with custom controls, picture-in-picture, fullscreen, captions, playback rate, cast/AirPlay and double-tap-to-skip. All browser native events are surfaced as Vue emits.', NULL, NULL, 'origam-video', NULL, 'packages/ds/src/components/Video/OrigamVideo.vue', 'origam', NULL, NULL, '/stories/?story=components-video--design', '/docs/components/Video/OrigamVideo.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.video.a11y.captions", "noteFallback": "Subtitles/captions are provided via the tracks prop using WebVTT format. The captions button in the toolbar toggles the active track."}, {"noteKey": "components.video.a11y.autoplay", "noteFallback": "Autoplay is suppressed when prefers-reduced-motion: reduce is active, respecting the user preference."}, {"noteKey": "components.video.a11y.aria", "noteFallback": "The controls bar uses aria-label for icon-only buttons (play, mute, fullscreen). The scrubber is a range input with aria-label, aria-valuemin, aria-valuemax and aria-valuenow."}], "roles": ["region"], "keyboard": [{"key": "Space / K", "actionKey": "components.video.a11y.key_play_pause", "actionFallback": "Toggle play/pause (when focus is on the player or controls)."}, {"key": "ArrowRight / ArrowLeft", "actionKey": "components.video.a11y.key_seek", "actionFallback": "Seek forward/backward by 5 seconds."}, {"key": "ArrowUp / ArrowDown", "actionKey": "components.video.a11y.key_volume", "actionFallback": "Increase/decrease volume by 10%."}, {"key": "M", "actionKey": "components.video.a11y.key_mute", "actionFallback": "Toggle mute."}, {"key": "F", "actionKey": "components.video.a11y.key_fullscreen", "actionFallback": "Toggle fullscreen."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color---black)", "tokenPath": "--origam-video---background-color", "descriptionKey": "components.video.tokens.background_color", "descriptionFallback": "Wrapper background."}, {"type": "dimension", "value": "var(--origam-radius---md)", "tokenPath": "--origam-video---border-radius", "descriptionKey": "components.video.tokens.border_radius", "descriptionFallback": "Corner radius."}, {"type": "color", "value": "var(--origam-color__neutral---950)", "tokenPath": "--origam-video__controls---background-color", "descriptionKey": "components.video.tokens.controls_background_color", "descriptionFallback": "Controls bar background."}, {"type": "color", "value": "var(--origam-color__primary---500)", "tokenPath": "--origam-video__scrubber---color", "descriptionKey": "components.video.tokens.scrubber_color", "descriptionFallback": "Scrubber accent color."}, {"type": "dimension", "value": "var(--origam-space---16)", "tokenPath": "--origam-video---poster-btn-size", "descriptionKey": "components.video.tokens.poster_btn_size", "descriptionFallback": "Size of the centered play button on the poster overlay."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"260\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"200\" rx=\"8\" fill=\"#0a0a0a\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1.5\"/>\n  <rect x=\"20\" y=\"180\" width=\"660\" height=\"40\" rx=\"0\" fill=\"rgba(10,10,10,0.85)\" rx=\"0\"/>\n  <rect x=\"20\" y=\"218\" width=\"660\" height=\"2\" rx=\"0\" fill=\"rgba(255,255,255,0.08)\"/>\n  <rect x=\"280\" y=\"70\" width=\"140\" height=\"80\" rx=\"50\" fill=\"rgba(255,255,255,0.08)\"/>\n  <text x=\"350\" y=\"116\" font-size=\"28\" fill=\"rgba(255,255,255,0.9)\" text-anchor=\"middle\">▶</text>\n  <rect x=\"30\" y=\"184\" width=\"260\" height=\"28\" rx=\"2\" fill=\"rgba(255,255,255,0.05)\"/>\n  <text x=\"140\" y=\"202\" font-size=\"9\" fill=\"rgba(255,255,255,0.7)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">scrubber + time</text>\n  <rect x=\"580\" y=\"184\" width=\"90\" height=\"28\" rx=\"2\" fill=\"rgba(255,255,255,0.05)\"/>\n  <text x=\"625\" y=\"202\" font-size=\"9\" fill=\"rgba(255,255,255,0.7)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">vol · pip · fs</text>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"350\" cy=\"78\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"350\" y=\"82\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"28\" cy=\"188\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"28\" y=\"192\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"140\" cy=\"188\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"140\" y=\"192\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"625\" cy=\"188\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"625\" y=\"192\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<div class=\"origam-video\">\n  <!-- native video element -->\n  <video ref=\"videoRef\" … />\n\n  <!-- poster overlay (before playback) -->\n  <slot name=\"poster\">\n    <div class=\"origam-video__poster\" … />\n  </slot>\n\n  <!-- buffering overlay -->\n  <slot name=\"loading\">\n    <div class=\"origam-video__loading\" … />\n  </slot>\n\n  <!-- error overlay -->\n  <slot name=\"error\" v-bind=\"{ error }\">\n    <div class=\"origam-video__error\" … />\n  </slot>\n\n  <!-- controls toolbar -->\n  <slot name=\"controls\" v-bind=\"scopedBindings\">\n    <div class=\"origam-video__controls\">\n      <!-- scrubber, time, volume, pip, fullscreen … -->\n    </div>\n  </slot>\n</div>", "legend": [{"cls": ".origam-video", "num": 1, "descriptionKey": "components.video.anatomy.root", "descriptionFallback": "Root wrapper. position: relative, aspect-ratio enforced, border-radius from rounded prop."}, {"cls": ".origam-video__poster", "num": 2, "descriptionKey": "components.video.anatomy.poster", "descriptionFallback": "Poster overlay rendered before playback starts. Hides on play. The #poster slot replaces it."}, {"cls": ".origam-video__controls", "num": 3, "descriptionKey": "components.video.anatomy.controls", "descriptionFallback": "Control bar. Overlaid (inset=true, default) or always-visible (inset=false). The #controls slot replaces the entire bar."}, {"cls": ".origam-video__scrubber", "num": 4, "descriptionKey": "components.video.anatomy.scrubber", "descriptionFallback": "Timeline scrubber — range input styled with CSS. Shows buffered region and playhead position."}, {"cls": ".origam-video__actions", "num": 5, "descriptionKey": "components.video.anatomy.actions", "descriptionFallback": "Trailing action buttons: volume, PIP, fullscreen, captions, cast, settings."}], "classes": [{"cls": "origam-video", "descriptionKey": "components.video.anatomy.root", "descriptionFallback": "Root wrapper."}, {"cls": "origam-video__poster", "descriptionKey": "components.video.anatomy.poster", "descriptionFallback": "Pre-playback poster."}, {"cls": "origam-video__loading", "descriptionKey": "components.video.anatomy.loading", "descriptionFallback": "Buffering overlay."}, {"cls": "origam-video__error", "descriptionKey": "components.video.anatomy.error_cls", "descriptionFallback": "Error overlay."}, {"cls": "origam-video__controls", "descriptionKey": "components.video.anatomy.controls", "descriptionFallback": "Controls bar."}], "svgDesc": "Schematic of the Video player with 6 numbered internal parts.", "svgTitle": "Anatomy of OrigamVideo", "rootClass": "origam-video", "figcaption": "Anatomy of <code>&lt;origam-video&gt;</code> — 5 internal parts. The wrapper ① positions the native <code>&lt;video&gt;</code> with its poster overlay ②; the controls bar ③ overlays the bottom edge and contains the scrubber ④ and action buttons ⑤.", "svgViewBox": "0 0 700 260"}, "cssVars": [{"name": "--origam-video---background-color", "defaultValue": "{color.black}", "descriptionKey": "components.video.css_vars.background_color", "descriptionFallback": "Video wrapper background (black by default for letterboxing)."}, {"name": "--origam-video---border-radius", "defaultValue": "{radius.md}", "descriptionKey": "components.video.css_vars.border_radius", "descriptionFallback": "Corner radius of the video wrapper."}, {"name": "--origam-video---controls-background-color", "defaultValue": "{color.neutral.950}", "descriptionKey": "components.video.css_vars.controls_background_color", "descriptionFallback": "Controls bar background (very dark for legibility on any content)."}, {"name": "--origam-video---btn-size", "defaultValue": "{space.8}", "descriptionKey": "components.video.css_vars.btn_size", "descriptionFallback": "Size of control buttons in the toolbar."}, {"name": "--origam-video---scrubber-color", "defaultValue": "{color.primary.500}", "descriptionKey": "components.video.css_vars.scrubber_color", "descriptionFallback": "Accent color of the playhead/thumb on the scrubber."}, {"name": "--origam-video---time-font-size", "defaultValue": "{font.size.xs}", "descriptionKey": "components.video.css_vars.time_font_size", "descriptionFallback": "Font size for the current-time / duration display."}], "exposed": [{"name": "videoRef", "type": "Ref<HTMLVideoElement | null>", "descriptionKey": "components.video.exposed.video_ref", "descriptionFallback": "Direct reference to the underlying HTMLVideoElement. Use for advanced integrations (WebGL, WebAudio, canvas)."}, {"name": "state", "type": "IVideoPlayerState", "descriptionKey": "components.video.exposed.state", "descriptionFallback": "Reactive state object: playing, paused, currentTime, duration, buffered, volume, muted, fullscreen, pip, loading, error, playbackRate."}, {"name": "methods", "type": "IVideoPlayerMethods", "descriptionKey": "components.video.exposed.methods", "descriptionFallback": "Imperative methods: play, pause, togglePlay, seek, setVolume, toggleMute, enterFullscreen, exitFullscreen, toggleFullscreen, requestPip, exitPip, togglePip."}], "playground": {"controls": [{"kind": "select", "prop": "rounded", "options": [{"label": "(default)", "value": ""}, {"label": "ROUNDED.X_SMALL", "value": "ROUNDED.X_SMALL"}, {"label": "x-small", "value": "x-small"}, {"label": "ROUNDED.SMALL", "value": "ROUNDED.SMALL"}, {"label": "small", "value": "small"}, {"label": "default", "value": "default"}, {"label": "ROUNDED.DEFAULT", "value": "ROUNDED.DEFAULT"}, {"label": "ROUNDED.MEDIUM", "value": "ROUNDED.MEDIUM"}, {"label": "medium", "value": "medium"}, {"label": "large", "value": "large"}, {"label": "ROUNDED.LARGE", "value": "ROUNDED.LARGE"}, {"label": "x-large", "value": "x-large"}, {"label": "ROUNDED.X_LARGE", "value": "ROUNDED.X_LARGE"}, {"label": "shaped", "value": "shaped"}, {"label": "ROUNDED.SHAPED", "value": "ROUNDED.SHAPED"}, {"label": "shaped-invert", "value": "shaped-invert"}, {"label": "ROUNDED.SHAPED_INVERT", "value": "ROUNDED.SHAPED_INVERT"}], "labelKey": "components.video.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "switch", "prop": "autoplay", "labelKey": "components.video.playground.autoplay", "defaultValue": false, "labelFallback": "Autoplay"}, {"kind": "switch", "prop": "muted", "labelKey": "components.video.playground.muted", "defaultValue": false, "labelFallback": "Muted"}, {"kind": "switch", "prop": "loop", "labelKey": "components.video.playground.loop", "defaultValue": false, "labelFallback": "Loop"}, {"kind": "select", "prop": "controls", "options": [{"label": "(default)", "value": ""}, {"label": "custom", "value": "custom"}, {"label": "native", "value": "native"}, {"label": "none", "value": "none"}], "labelKey": "components.video.playground.controls", "defaultValue": "", "labelFallback": "Controls"}, {"kind": "switch", "prop": "playsInline", "labelKey": "components.video.playground.plays_inline", "defaultValue": true, "labelFallback": "Plays Inline"}, {"kind": "select", "prop": "preload", "options": [{"label": "(default)", "value": ""}, {"label": "none", "value": "none"}, {"label": "metadata", "value": "metadata"}, {"label": "auto", "value": "auto"}], "labelKey": "components.video.playground.preload", "defaultValue": "", "labelFallback": "Preload"}, {"kind": "switch", "prop": "inset", "labelKey": "components.video.playground.inset", "defaultValue": true, "labelFallback": "Inset"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8aae2ca7-afc9-476b-9a26-59ceb832da2c', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'virtual-scroll', 'VirtualScroll', 'Data Display', NULL, 'mdi-view-list', 'components.catalog.virtual_scroll.description', 'Window-based virtual list renderer that only mounts visible rows, keeping the DOM small for arbitrarily large datasets. Supports both wrapper and renderless modes.', NULL, NULL, 'origam-virtual-scroll', NULL, 'packages/ds/src/components/VirtualScroll/OrigamVirtualScroll.vue', 'origam', NULL, NULL, '/stories/?story=components-virtual-scroll--design', '/docs/components/VirtualScroll/OrigamVirtualScroll.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.virtual_scroll.a11y.dom_size", "noteFallback": "Only visible items are in the DOM — screen readers may announce fewer items than the total count. Add aria-setsize and aria-posinset on each rendered item if the total count matters semantically."}, {"noteKey": "components.virtual_scroll.a11y.focus", "noteFallback": "When scrollToIndex is called programmatically, focus management is the consumer responsibility. Items outside the visible window are unmounted and cannot receive focus."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.virtual_scroll.a11y.key_tab", "actionFallback": "Focuses the scroll container, then navigates through rendered items."}, {"key": "ArrowDown / ArrowUp", "actionKey": "components.virtual_scroll.a11y.key_scroll", "actionFallback": "Scrolls the list when the container has focus."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "48px", "tokenPath": "--origam-virtual-scroll---item-height", "descriptionKey": "components.virtual_scroll.tokens.item_height", "descriptionFallback": "Default estimated item height."}, {"type": "duration", "value": "var(--origam-motion__duration---fast)", "tokenPath": "--origam-virtual-scroll---transition-duration", "descriptionKey": "components.virtual_scroll.tokens.transition_duration", "descriptionFallback": "Item transition duration."}, {"type": "dimension", "value": "var(--origam-space---0)", "tokenPath": "--origam-virtual-scroll---scroll-padding", "descriptionKey": "components.virtual_scroll.tokens.scroll_padding", "descriptionFallback": "Scroll container scroll-padding."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"240\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"100\" y=\"20\" width=\"500\" height=\"200\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" style=\"overflow:hidden\"/>\n  <rect x=\"100\" y=\"20\" width=\"500\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"350\" y=\"36\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">spacer-top (padding-top)</text>\n  <rect x=\"100\" y=\"56\" width=\"500\" height=\"40\" rx=\"2\" fill=\"var(--origam-color__surface---raised, #f8f5fe)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"79\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">virtual-scroll-item #47</text>\n  <rect x=\"100\" y=\"104\" width=\"500\" height=\"40\" rx=\"2\" fill=\"var(--origam-color__surface---raised, #f8f5fe)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"127\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">virtual-scroll-item #48</text>\n  <rect x=\"100\" y=\"152\" width=\"500\" height=\"40\" rx=\"2\" fill=\"var(--origam-color__surface---raised, #f8f5fe)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"175\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">virtual-scroll-item #49</text>\n  <rect x=\"100\" y=\"196\" width=\"500\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"350\" y=\"212\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">spacer-bottom (padding-bottom)</text>\n  <circle cx=\"108\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"108\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"108\" cy=\"64\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"108\" y=\"68\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"108\" cy=\"204\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"108\" y=\"208\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<div ref=\"containerRef\" class=\"origam-virtual-scroll\">\n  <!-- top spacer — fills height of items above viewport -->\n  <div ref=\"markerRef\" class=\"origam-virtual-scroll__spacer\" :style=\"{ ''padding-top'': paddingTop + ''px'' }\" />\n\n  <!-- only currently visible items are mounted -->\n  <origam-virtual-scroll-item\n    v-for=\"(item, index) in computedItems\"\n    :key=\"index\"\n    class=\"origam-virtual-scroll__item\"\n    @update:height=\"handleItemResize(index, $event)\"\n  >\n    <slot :item=\"item.raw\" :index=\"item.index\" />\n  </origam-virtual-scroll-item>\n\n  <!-- bottom spacer — fills height of items below viewport -->\n  <div class=\"origam-virtual-scroll__spacer\" :style=\"{ ''padding-bottom'': paddingBottom + ''px'' }\" />\n</div>", "legend": [{"cls": ".origam-virtual-scroll", "num": 1, "descriptionKey": "components.virtual_scroll.anatomy.root", "descriptionFallback": "Scroll container. overflow-y: auto, height fixed or max-height constrained."}, {"cls": ".origam-virtual-scroll__spacer", "num": 2, "descriptionKey": "components.virtual_scroll.anatomy.spacer", "descriptionFallback": "Top spacer div. padding-top dynamically set to fill the height of all items above the visible window."}, {"cls": ".origam-virtual-scroll__spacer (bottom)", "num": 3, "descriptionKey": "components.virtual_scroll.anatomy.spacer_bottom", "descriptionFallback": "Bottom spacer div. padding-bottom fills the height of all items below the visible window."}], "classes": [{"cls": "origam-virtual-scroll", "descriptionKey": "components.virtual_scroll.anatomy.root", "descriptionFallback": "Scroll container."}, {"cls": "origam-virtual-scroll__spacer", "descriptionKey": "components.virtual_scroll.anatomy.spacer", "descriptionFallback": "Spacer divs (top and bottom)."}, {"cls": "origam-virtual-scroll__item", "descriptionKey": "components.virtual_scroll.anatomy.item", "descriptionFallback": "Each rendered item wrapper."}], "svgDesc": "Schematic showing the virtual scroll container with spacers and visible items.", "svgTitle": "Anatomy of OrigamVirtualScroll", "rootClass": "origam-virtual-scroll", "figcaption": "Anatomy of <code>&lt;origam-virtual-scroll&gt;</code> — the container ① holds a top spacer ② (padding-top), the currently visible VirtualScrollItems, and a bottom spacer ③ (padding-bottom). Items outside the viewport are unmounted.", "svgViewBox": "0 0 700 240"}, "cssVars": [{"name": "--origam-virtual-scroll---item-height", "defaultValue": "48px", "descriptionKey": "components.virtual_scroll.css_vars.item_height", "descriptionFallback": "Default estimated item height used for initial spacer calculation (48px = standard list row)."}, {"name": "--origam-virtual-scroll---scroll-padding", "defaultValue": "{space.0}", "descriptionKey": "components.virtual_scroll.css_vars.scroll_padding", "descriptionFallback": "scroll-padding on the scroll container, so focused items are not obscured by sticky headers."}, {"name": "--origam-virtual-scroll---transition-duration", "defaultValue": "{motion.duration.fast}", "descriptionKey": "components.virtual_scroll.css_vars.transition_duration", "descriptionFallback": "Item appear/disappear transition duration (fast to avoid jank during rapid scrolling)."}], "exposed": [{"name": "scrollToIndex", "type": "(index: number) => void", "descriptionKey": "components.virtual_scroll.exposed.scroll_to_index", "descriptionFallback": "Programmatically scrolls to bring the item at the given index into view."}, {"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.virtual_scroll.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.virtual_scroll.exposed.css", "descriptionFallback": "Reactive CSS string for computed styles."}, {"name": "id", "type": "string", "descriptionKey": "components.virtual_scroll.exposed.id", "descriptionFallback": "Unique style-sheet ID."}, {"name": "load", "type": "() => void", "descriptionKey": "components.virtual_scroll.exposed.load", "descriptionFallback": "Injects the style sheet on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.virtual_scroll.exposed.unload", "descriptionFallback": "Removes the style sheet on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.virtual_scroll.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "height", "options": [{"label": "200px", "value": "200"}, {"label": "300px", "value": "300"}, {"label": "400px", "value": "400"}, {"label": "500px", "value": "500"}], "labelKey": "components.virtual_scroll.playground.height", "defaultValue": "300", "labelFallback": "Container height"}, {"kind": "switch", "prop": "renderless", "labelKey": "components.virtual_scroll.playground.renderless", "defaultValue": false, "labelFallback": "Renderless mode"}]}, "previewVariants": [{"label": "wrapper", "props": {"height": 300, "renderless": false}}, {"label": "fixed height", "props": {"height": 300, "itemHeight": 48, "renderless": false}}, {"label": "renderless", "props": {"renderless": true}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c6c79491-53df-498a-a4db-34a4371ec861', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'watermark', 'Watermark', 'Utilities & Providers', NULL, 'mdi-watermark', 'components.catalog.watermark.description', 'Absolutely-positioned repeating diagonal overlay wrapping a content slot. Renders a tiled SVG data-URL with text or image glyph. Supports anti-tamper MutationObserver, pointer-events pass-through and full visual customisation.', NULL, NULL, 'origam-watermark', NULL, 'packages/ds/src/components/Watermark/OrigamWatermark.vue', 'origam', NULL, NULL, '/stories/?story=components-watermark--design', '/docs/components/Watermark/OrigamWatermark.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.watermark.a11y.visual_only", "noteFallback": "The overlay is purely visual. It carries aria-hidden=\"true\" so screen readers skip it entirely — only the wrapped content is announced."}, {"noteKey": "components.watermark.a11y.pointer_events", "noteFallback": "With pointerEvents=\"none\" (default), all interactive elements inside the slot remain keyboard and pointer accessible."}, {"noteKey": "components.watermark.a11y.security", "noteFallback": "The watermark is NOT a security feature. antiTamper adds dissuasion only — a determined user can always disable JS. Do not rely on it to protect sensitive data."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"60\" y=\"20\" width=\"580\" height=\"180\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"110\" font-size=\"14\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"sans-serif\">Wrapped content</text>\n  <g opacity=\"0.10\" transform=\"translate(60,20)\">\n    <text x=\"30\" y=\"50\" font-size=\"18\" fill=\"#7c3aed\" transform=\"rotate(-30, 30, 50)\" font-family=\"sans-serif\">DRAFT</text>\n    <text x=\"180\" y=\"90\" font-size=\"18\" fill=\"#7c3aed\" transform=\"rotate(-30, 180, 90)\" font-family=\"sans-serif\">DRAFT</text>\n    <text x=\"340\" y=\"60\" font-size=\"18\" fill=\"#7c3aed\" transform=\"rotate(-30, 340, 60)\" font-family=\"sans-serif\">DRAFT</text>\n    <text x=\"100\" y=\"140\" font-size=\"18\" fill=\"#7c3aed\" transform=\"rotate(-30, 100, 140)\" font-family=\"sans-serif\">DRAFT</text>\n    <text x=\"280\" y=\"160\" font-size=\"18\" fill=\"#7c3aed\" transform=\"rotate(-30, 280, 160)\" font-family=\"sans-serif\">DRAFT</text>\n    <text x=\"440\" y=\"140\" font-size=\"18\" fill=\"#7c3aed\" transform=\"rotate(-30, 440, 140)\" font-family=\"sans-serif\">DRAFT</text>\n  </g>\n  <circle cx=\"68\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"68\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"350\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"350\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"350\" cy=\"100\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"350\" y=\"104\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<component :is=\"tag\" ref=\"rootEl\" class=\"origam-watermark\">\n  <!-- wrapped content -->\n  <slot />\n  <!-- tiled overlay — position:absolute, inset:0 -->\n  <div ref=\"layerEl\" class=\"origam-watermark__layer\" :style=\"layerStyles\" />\n</component>", "legend": [{"cls": ".origam-watermark", "num": 1, "descriptionKey": "components.watermark.anatomy.root", "descriptionFallback": "Root wrapper. position: relative; display: block. Receives the tag prop."}, {"cls": ".origam-watermark__layer", "num": 2, "descriptionKey": "components.watermark.anatomy.layer", "descriptionFallback": "Absolutely-positioned overlay (inset: 0). background-image set to a data:image/svg+xml data-URL. pointer-events: none by default."}, {"cls": "[#default slot]", "num": 3, "descriptionKey": "components.watermark.anatomy.slot", "descriptionFallback": "Wrapped content rendered at z-index 0, below the overlay layer."}], "classes": [{"cls": "origam-watermark", "descriptionKey": "components.watermark.anatomy.root", "descriptionFallback": "Root wrapper with position:relative."}, {"cls": "origam-watermark__layer", "descriptionKey": "components.watermark.anatomy.layer", "descriptionFallback": "Absolutely-positioned tiled SVG overlay."}], "svgDesc": "Schematic showing the watermark wrapper with the tiled overlay layer above the slot content.", "svgTitle": "Anatomy of OrigamWatermark", "rootClass": "origam-watermark", "figcaption": "Anatomy of <code>&lt;origam-watermark&gt;</code> — the root ① is position:relative; the overlay layer ② is absolutely inset with a tiled SVG data-URL background; the slot content ③ sits beneath (pointer-events passes through by default).", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-watermark---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.watermark.css_vars.color", "descriptionFallback": "Default glyph color token (currentColor in data-URL context; override with explicit value)."}, {"name": "--origam-watermark---opacity-low", "defaultValue": "0.05", "descriptionKey": "components.watermark.css_vars.opacity_low", "descriptionFallback": "Low opacity level (very subtle)."}, {"name": "--origam-watermark---opacity-medium", "defaultValue": "0.1", "descriptionKey": "components.watermark.css_vars.opacity_medium", "descriptionFallback": "Medium opacity level (default)."}, {"name": "--origam-watermark---opacity-high", "defaultValue": "0.2", "descriptionKey": "components.watermark.css_vars.opacity_high", "descriptionFallback": "High opacity level (more prominent)."}, {"name": "--origam-watermark---gap-tight", "defaultValue": "60px", "descriptionKey": "components.watermark.css_vars.gap_tight", "descriptionFallback": "Tight tile gap (dense pattern)."}, {"name": "--origam-watermark---gap-medium", "defaultValue": "120px", "descriptionKey": "components.watermark.css_vars.gap_medium", "descriptionFallback": "Medium tile gap (default)."}, {"name": "--origam-watermark---z-index", "defaultValue": "1", "descriptionKey": "components.watermark.css_vars.z_index", "descriptionFallback": "Z-index of the overlay layer."}], "exposed": [{"name": "patternUrl", "type": "Ref<string>", "descriptionKey": "components.watermark.exposed.pattern_url", "descriptionFallback": "Reactive data-URL of the generated SVG tile. Can be used as a background-image in custom CSS."}, {"name": "rootEl", "type": "Ref<HTMLElement | null>", "descriptionKey": "components.watermark.exposed.root_el", "descriptionFallback": "Reference to the root wrapper element."}, {"name": "layerEl", "type": "Ref<HTMLElement | null>", "descriptionKey": "components.watermark.exposed.layer_el", "descriptionFallback": "Reference to the overlay layer element. Used internally by the MutationObserver."}], "playground": {"controls": [{"kind": "text", "prop": "text", "labelKey": "components.watermark.playground.text", "defaultValue": "CONFIDENTIAL", "labelFallback": "Text"}, {"kind": "number", "prop": "opacity", "labelKey": "components.watermark.playground.opacity", "defaultValue": 0.1, "labelFallback": "Opacity"}, {"kind": "number", "prop": "angle", "labelKey": "components.watermark.playground.angle", "defaultValue": -30, "labelFallback": "Angle (degrees)"}, {"kind": "number", "prop": "gap", "labelKey": "components.watermark.playground.gap", "defaultValue": 120, "labelFallback": "Gap (px)"}, {"kind": "number", "prop": "fontSize", "labelKey": "components.watermark.playground.font_size", "defaultValue": 16, "labelFallback": "Font size (px)"}, {"kind": "switch", "prop": "antiTamper", "labelKey": "components.watermark.playground.anti_tamper", "defaultValue": false, "labelFallback": "Anti-tamper"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0dc61271-7ac8-4163-980a-ab1d755afc70', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'component', 'window', 'Window', 'Navigation', NULL, 'mdi-view-carousel', 'components.catalog.window.description', 'Slide-based content switcher with previous/next navigation, touch swipe, keyboard support and configurable transitions. The base for Carousel, Stepper and Tab panels.', NULL, NULL, 'origam-window', NULL, 'packages/ds/src/components/Window/OrigamWindow.vue', 'origam', NULL, NULL, '/stories/?story=components-window--design', '/docs/components/Window/OrigamWindow.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.window.a11y.role", "noteFallback": "Consider adding role=\"region\" and aria-label to the window to make the slide region identifiable to screen readers."}, {"noteKey": "components.window.a11y.arrow_buttons", "noteFallback": "Arrow buttons are OrigamBtn with icon props — always provide aria-label (e.g. \"Previous slide\", \"Next slide\") via the prevProps/nextProps slots."}, {"noteKey": "components.window.a11y.live_region", "noteFallback": "For auto-advancing windows (e.g. carousel), add aria-live=\"polite\" on the active slide container so screen readers announce the new content."}], "roles": ["region"], "keyboard": [{"key": "ArrowLeft / ArrowRight", "actionKey": "components.window.a11y.key_horizontal", "actionFallback": "Navigate to the previous/next slide when direction=\"horizontal\"."}, {"key": "ArrowUp / ArrowDown", "actionKey": "components.window.a11y.key_vertical", "actionFallback": "Navigate to the previous/next slide when direction=\"vertical\"."}, {"key": "Tab", "actionKey": "components.window.a11y.key_tab", "actionFallback": "Moves focus through arrow buttons and content inside the active slide."}]}, "tokens": {"excerpt": [{"type": "duration", "value": "var(--origam-motion__duration---slow)", "tokenPath": "--origam-window---transition-duration", "descriptionKey": "components.window.tokens.transition_duration", "descriptionFallback": "Slide transition duration."}, {"type": "cubicBezier", "value": "var(--origam-motion__easing---standard)", "tokenPath": "--origam-window---transition-easing", "descriptionKey": "components.window.tokens.transition_easing", "descriptionFallback": "Slide transition easing."}, {"type": "color", "value": "var(--origam-color__text---primary)", "tokenPath": "--origam-window__controls---color", "descriptionKey": "components.window.tokens.controls_color", "descriptionFallback": "Arrow button icon color."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"260\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"200\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"30\" y=\"30\" width=\"640\" height=\"180\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\"/>\n  <rect x=\"30\" y=\"30\" width=\"640\" height=\"180\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.20))\" stroke-width=\"1\" stroke-dasharray=\"5 3\"/>\n  <rect x=\"170\" y=\"60\" width=\"360\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"125\" font-size=\"13\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"sans-serif\">WindowItem content</text>\n  <circle cx=\"50\" cy=\"120\" r=\"20\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"50\" y=\"124\" font-size=\"14\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\">‹</text>\n  <circle cx=\"650\" cy=\"120\" r=\"20\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"650\" y=\"124\" font-size=\"14\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\">›</text>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"38\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"38\" y=\"42\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"350\" cy=\"60\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"350\" y=\"64\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"50\" cy=\"100\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"50\" y=\"104\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"650\" cy=\"100\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"650\" y=\"104\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <text x=\"350\" y=\"248\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">④ prev and ⑤ next rendered when showArrows is set</text>\n", "code": "<component :is=\"tag\" ref=\"rootRef\" class=\"origam-window\">\n  <div class=\"origam-window__container\">\n    <!-- default slot: OrigamWindowItem children -->\n    <slot name=\"default\" v-bind=\"group\" />\n\n    <!-- navigation controls -->\n    <div v-if=\"showArrows !== false\" class=\"origam-window__controls\">\n      <slot name=\"arrows\" v-bind=\"{ prevProps, nextProps, canMoveBack, canMoveForward }\">\n        <slot name=\"prev\" v-bind=\"{ props: prevProps, canMove: canMoveBack }\">\n          <origam-btn v-if=\"canMoveBack\" v-bind=\"prevProps\" />\n        </slot>\n        <origam-spacer v-if=\"!canMoveBack\" />\n        <slot name=\"next\" v-bind=\"{ props: nextProps, canMove: canMoveForward }\">\n          <origam-btn v-if=\"canMoveForward\" v-bind=\"nextProps\" />\n        </slot>\n      </slot>\n    </div>\n  </div>\n\n  <!-- outside the container — for indicators etc. -->\n  <slot name=\"additional\" v-bind=\"group\" />\n</component>", "legend": [{"cls": ".origam-window", "num": 1, "descriptionKey": "components.window.anatomy.root", "descriptionFallback": "Root element. position: relative; overflow: hidden. Receives tag, rounded, elevation and bgColor."}, {"cls": ".origam-window__container", "num": 2, "descriptionKey": "components.window.anatomy.container", "descriptionFallback": "Inner flex column. display: flex; flex-direction: column; height: inherit. Hosts the #default slot (WindowItem children)."}, {"cls": "origam-window-item", "num": 3, "descriptionKey": "components.window.anatomy.item", "descriptionFallback": "Each slide — rendered inside OrigamWindowItem. Only the active item is visible; transitions are handled by OrigamTransition wrapping each item."}, {"cls": ".origam-window__controls [prev]", "num": 4, "descriptionKey": "components.window.anatomy.prev", "descriptionFallback": "Previous arrow button. Absolute-positioned on the left/top edge. Hidden when showArrows=false or canMoveBack=false."}, {"cls": ".origam-window__controls [next]", "num": 5, "descriptionKey": "components.window.anatomy.next", "descriptionFallback": "Next arrow button. Absolute-positioned on the right/bottom edge."}], "classes": [{"cls": "origam-window", "descriptionKey": "components.window.anatomy.root", "descriptionFallback": "Root wrapper."}, {"cls": "origam-window__container", "descriptionKey": "components.window.anatomy.container", "descriptionFallback": "Flex column container for slides."}, {"cls": "origam-window__controls", "descriptionKey": "components.window.anatomy.controls", "descriptionFallback": "Arrow buttons container (absolute inset)."}, {"cls": "origam-window-item", "descriptionKey": "components.window.anatomy.item", "descriptionFallback": "Individual slide wrapper."}, {"cls": "origam-window-item--active", "descriptionKey": "components.window.anatomy.item_active", "descriptionFallback": "Applied to the currently active WindowItem."}], "svgDesc": "Schematic of the Window component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamWindow", "rootClass": "origam-window", "figcaption": "Anatomy of <code>&lt;origam-window&gt;</code> — 5 internal parts. The root ① wraps the container ② which holds the active WindowItem ③. Prev ④ and next ⑤ arrow buttons overlay the container sides.", "svgViewBox": "0 0 700 260"}, "cssVars": [{"name": "--origam-window---overflow", "defaultValue": "hidden", "descriptionKey": "components.window.css_vars.overflow", "descriptionFallback": "Overflow of the root element (hidden to clip exiting slides)."}, {"name": "--origam-window---transition-duration", "defaultValue": "{motion.duration.slow}", "descriptionKey": "components.window.css_vars.transition_duration", "descriptionFallback": "Slide transition duration."}, {"name": "--origam-window---transition-easing", "defaultValue": "{motion.easing.standard}", "descriptionKey": "components.window.css_vars.transition_easing", "descriptionFallback": "Easing function for slide transitions."}, {"name": "--origam-window---controls-color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.window.css_vars.controls_color", "descriptionFallback": "Icon color of the arrow buttons."}, {"name": "--origam-window---controls-hover-color", "defaultValue": "{color.action.primary.fg}", "descriptionKey": "components.window.css_vars.controls_hover_color", "descriptionFallback": "Arrow button icon color on hover."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.window.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}, {"name": "group", "type": "GroupProvide", "descriptionKey": "components.window.exposed.group", "descriptionFallback": "Group selection context provided to all WindowItem children. Used to wire the active state."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.window.exposed.css", "descriptionFallback": "Reactive CSS string for computed styles."}, {"name": "id", "type": "string", "descriptionKey": "components.window.exposed.id", "descriptionFallback": "Unique style-sheet ID."}, {"name": "load", "type": "() => void", "descriptionKey": "components.window.exposed.load", "descriptionFallback": "Injects the style sheet on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.window.exposed.unload", "descriptionFallback": "Removes the style sheet on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.window.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "showArrows", "options": [{"label": "false", "value": "false"}, {"label": "true", "value": "true"}, {"label": "hover", "value": "hover"}], "labelKey": "components.window.playground.show_arrows", "defaultValue": "true", "labelFallback": "Show arrows"}, {"kind": "select", "prop": "direction", "options": [{"label": "horizontal", "value": "horizontal"}, {"label": "v