INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0f270128-3256-432c-880a-4741a529d8d9', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'composable', 'use-style', 'useStyle', NULL, 'Commons', 'mdi-code-tags', '', 'Injects a dynamic <style> tag into document.head scoped to a generated element id, allowing components to apply per-instance CSS that cannot be expressed as inline styles (e.g. pseudo-element rules, :hover selectors, @keyframes). Also exposes the lower-level useStyleTag for raw CSS string injection. Both composables manage their own lifecycle: they load on mount and unload on scope dispose.', NULL, 'function useStyle(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('b25847ed-1490-4ed9-b9d8-e22afaaff676', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'composable', 'use-style-tag', 'useStyleTag', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useStyleTag(css: MaybeRef<string>, options?: IStyleTagOptions = {}): { id: string; css: Ref<string, string> | ShallowRef<string, string> | WritableComputedRef<string, string>; unload: () => void; load: () => void; isLoaded: Readonly<...>; }', NULL, NULL, 'packages/ds/src/composables/Commons/styleTag.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('fe1d359d-2acf-4491-8271-13d729478eb8', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'composable', 'use-teleport', 'useTeleport', NULL, 'Commons', 'mdi-arrow-top-right-bold-box-outline', '', 'Resolves the Vue Teleport target for overlay components. Accepts true (disable teleport — render inline), false (teleport to document.body), a CSS selector string (teleport to the matched element), or a raw Element. Creates an .origam-overlay-container div inside the target when one does not already exist, so multiple overlays sharing the same target stack correctly without polluting the host''s direct children.', NULL, 'function useTeleport(
