INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('1241e400-498e-4e59-ac57-e9ea4d5b257d', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'composable', 'use-video-player', 'useVideoPlayer', NULL, 'Video', 'mdi-video-outline', '', 'Headless video player composable. Composes the media-shared useMediaPlayer base and adds video-only state (fullscreen, pip) plus methods (enterFullscreen, exitFullscreen, toggleFullscreen, requestPip, exitPip, togglePip). Handles the iOS Safari webkitEnterFullscreen fallback and the document-level fullscreenchange listener.', NULL, 'function useVideoPlayer(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('836e423f-5f5d-4048-8b6d-4ac0f65f117d', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'composable', 'use-virtual', 'useVirtual', NULL, 'Commons', 'mdi-view-list-outline', '', 'Virtual-scroll engine for large datasets. Maintains a dynamic window of visible items, computes per-item offsets via a debounced binary-search algorithm, tracks scroll velocity for predictive buffering, and exposes scrollToIndex with optional animated scrolling through useGoTo. SSR-safe — all DOM access is guarded.', NULL, 'function useVirtual<T>(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('54a90e13-9b44-409f-a5a5-149167f0dfc1', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'composable', 'use-v-model', 'useVModel', NULL, 'Commons', 'mdi-swap-horizontal', '', 'Implements a controlled / uncontrolled prop contract for any component prop bound via v-model. When the parent provides both the prop and the matching onUpdate:prop listener the component operates in controlled mode; otherwise it manages its own internal ref. Supports kebab-case / camelCase prop alias pairs and optional in/out value transformers.', NULL, 'function useVModel<
