INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('1088b672-799a-43a4-8128-fce59d7ba949', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'interface', 'i-chart-pyramid-slice', 'IChartPyramidSlice', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_pyramid_slice.description', 'Single slice descriptor produced by the pyramid geometry engine. Exposes the pre-computed SVG <path d="…"> for the trapezoid, the label anchor position, and all data needed to render accessibility text and tooltip content.', 'export interface IChartPyramidSlice {
