INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('09f52228-1938-4dc5-8964-e3c9a89c30cf', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'interface', 'i-chart-radar-props', 'IChartRadarProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_radar_props.description', 'Props for <OrigamChartRadar> — the radar / spider chart. Tightly-typed wrapper around <OrigamChart type="radar"> with only the options relevant to radar charts. No type prop is exposed — the family is fixed to the radar geometry. Extends IChartBaseProps.', 'export interface IChartRadarProps extends IChartBaseProps {
