INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('90cc50ad-0263-4415-8c30-e8d627b25b42', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'interface', 'i-chart-sankey-node', 'IChartSankeyNode', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_sankey_node.description', 'Internal node descriptor produced by the Sankey layout engine. All coordinates are in SVG-user-unit space. Nodes are inferred from the union of all from and to strings in IChartSankeyDatum; column is assigned by topological depth (Kahn''s algorithm).', 'export interface IChartSankeyNode {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('38bda385-aa3c-4230-8f62-7fcffb3e655e', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'interface', 'i-chart-sankey-props', 'IChartSankeyProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_sankey_props.description', 'Props for <OrigamChartSankey>. The component consumes series[0] only — each item in series[0].data must conform to IChartSankeyDatum ({ from, to, value }). Nodes are inferred automatically; columns are assigned by topological depth. Extends IChartBaseProps.', 'export interface IChartSankeyProps extends IChartBaseProps {
