INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('dbabb938-54a1-411c-adab-bca51432aaf8', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'interface', 'i-chart-scales', 'IChartScales', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_scales.description', 'Pair of pixel-mapping functions produced by useChart from the data range and viewBox size. Pure functions — safe to call from computed refs. x maps a value or category index to an SVG horizontal coordinate; y maps a numeric value to an SVG vertical coordinate.', 'export interface IChartScales {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('240b8cdd-bf5d-4fea-b8d4-6a1871260a5a', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'interface', 'i-chart-secondary-y-axis', 'IChartSecondaryYAxis', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_secondary_y_axis.description', 'Configuration object for the secondary (right-hand) Y axis on a cartesian chart. When passed to secondaryYAxis on OrigamChartCartesian, series with yAxis: 1 are projected against this scale. Omit to use the primary left axis only.', 'export interface IChartSecondaryYAxis {
