INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2e8b110a-5bb0-4ef1-9f77-9339416487c7', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'interface', 'i-chart-series-point', 'IChartSeriesPoint', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_series_point.description', 'Object form of a single data point inside IChartSeries.data. Required for scatter charts where the X axis is not a simple categories[index]. The optional z field turns the point into a bubble by scaling its dot radius.', 'export interface IChartSeriesPoint {
