INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5e0bc2df-e769-4056-a2e5-cb7c34d3e3af', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '6624b143-59e0-4141-97d9-09924f47d80d', 'props', 'IActivatorProps', true, NULL, '', 'Props controlling how the overlay is triggered. Includes activator selector/element, open-on strategy (click, hover, focus, context-menu), close-on-content-click, delay settings inherited from IDelayProps, and an optional target override.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7271812b-3ce1-415d-8a48-397fbc202f67', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '6624b143-59e0-4141-97d9-09924f47d80d', 'isActive', 'Ref<boolean>', true, NULL, '', 'Reactive flag representing the open/closed state of the overlay. useActivator reads and writes this ref to toggle the overlay on user interaction.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dd907ae1-c37e-4315-b6bd-c623c0ac45ef', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '6624b143-59e0-4141-97d9-09924f47d80d', 'isTop', 'Ref<boolean>', true, NULL, '', 'Reactive flag set by the overlay stack manager. When true, this overlay is the topmost one; when it becomes false while hover/focus-triggered, the composable auto-closes the overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('09b1f572-0c59-422d-a17f-ca48375153df', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '6fc8e560-fd79-40c9-9723-aa4360ae7732', 'props', 'IActiveProps & Record<string, any>', true, NULL, '', 'Component props. Reads `props[prop]` (default: `props.active`).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e0c6ddcb-9459-4d02-a0cd-421ebc3ecb5d', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '6fc8e560-fd79-40c9-9723-aa4360ae7732', 'prop', 'string', false, '''active''', '', 'The prop key to read for the active value. Use "modelValue" for components with a v-model binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8c6b5be8-0a93-422f-a852-d74e888a3efa', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '6fc8e560-fd79-40c9-9723-aa4360ae7732', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--active` class.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9d75e388-9714-4d80-ace1-f9c8b61996ca', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '7d54830f-9a7c-42fc-bf01-e109a6822107', 'props', 'IAdjacentProps', true, NULL, '', 'Props carrying prependIcon, appendIcon, prependAvatar, and appendAvatar values. The composable reads these to determine whether the outer prepend/append regions should render.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c1ebf925-e742-43c4-835d-0d0ef9ab6cbb', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '7d54830f-9a7c-42fc-bf01-e109a6822107', 'prependIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the prepend slot. When provided, takes precedence over props.prependIcon, enabling status-aware icon swapping without prop mutation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6585f5b8-92c5-4cf1-aaeb-8bc5006d68e1', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '7d54830f-9a7c-42fc-bf01-e109a6822107', 'appendIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the append slot. Same semantics as prependIcon but for the trailing position.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a41536d5-51dc-443c-97fe-466f61cd1e9b', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '5cc63385-854b-450e-8fba-16d0dc2dfcca', 'props', 'IAdjacentInnerProps', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('195f47f7-b74f-4de4-92d2-2f76d743f262', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '64b6127f-6c38-4eec-a21f-dccb49eb4263', 'props', '{ aspectRatio?: string | number }', true, NULL, '', 'Object carrying an optional aspectRatio value. Accepts a numeric ratio (1.777 for 16:9), a division expression string ("16/9"), or is left undefined to use window.innerWidth / window.innerHeight as the ratio.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8b626870-c9b0-498f-adb8-94fac0c0b486', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '9609765d-dacb-4bed-bbb6-c87822598c54', 'props', 'IUseAudioProps', true, NULL, '', 'Props object with audio (URL of the audio source) and playAudio (boolean flag). When playAudio changes to true the composable calls onPlay(); when it changes to false it calls onStop(). When audio changes, wasPlayed and isPlaying are reset.', 0, false, NULL, NULL);
