INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bc0f4b0d-6432-4579-9424-2bc2674218fb', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '58fc4ba6-8323-40f0-bd7c-a9dfeaa64c1f', 'milliseconds', 'number', true, NULL, '', 'Total countdown duration in milliseconds. This is the initial value of time and the value it resets to on reset().', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f04214d1-d787-444f-9565-d5602d091398', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '96737fb1-8b1b-4086-820a-85827749fe1e', 'options', 'IUseSnackbarGroupOptions', false, '{}', '', 'Optional configuration. id (string) namespaces the stack so multiple independent stacks can coexist on the same page (default: SNACKBAR_GROUP_DEFAULT_ID). max (number) caps the stack size with FIFO eviction. defaultDuration (ms) is the fallback auto-dismiss delay for items that omit their own (default: 5000 ms).', 0, false, NULL, NULL);
