INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('458a743e-435c-44e9-aa1a-1097400d4d16', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '18362b1b-e010-400f-9521-26ee4a71046f', 'isActive', 'Readonly<Ref<boolean>>', true, NULL, '', 'Reactive open/closed state. When it flips to true, useStack registers the component in the global stack and computes a new z-index. When false, the entry is removed and z-index is released.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b74cfa08-b6f2-4d8e-b500-1a99642c488d', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '18362b1b-e010-400f-9521-26ee4a71046f', 'zIndex', 'Readonly<Ref<string | number>>', true, NULL, '', 'Base z-index to start from when no other overlays are open. Typically comes from the component props (e.g. zIndex="200").', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c7ad3efb-32de-4b30-826e-7d3640abcbf2', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '18362b1b-e010-400f-9521-26ee4a71046f', 'disableGlobalStack', 'Readonly<Ref<boolean>>', true, NULL, '', 'When true, skips registration in GLOBAL_STACK. Use for overlays that manage their own z-index independently (e.g. nested teleport roots) and should not compete with the global stacking order.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('992d869f-f74e-4f84-b23e-26c450051eae', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'cbcb1087-4703-4b7c-a932-ea81268386fc', 'props', 'TStateEffectProps', true, NULL, '', 'Component props implementing all eight axes: IColorProps & IBgColorProps & IBorderProps & IRoundedProps & IElevationProps & IPaddingProps & IMarginProps & { gap? }. Also reads props.status when present to force the matching semantic intent (overrides color/bgColor).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('10bfa40c-eb66-48c0-a45c-769bd4c96b20', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'cbcb1087-4703-4b7c-a932-ea81268386fc', 'isHover', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive hover state from useHover. When true, the composable applies the override values from hoverState for each axis.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e39491d7-8cfa-4197-a186-d4d3f42b1b69', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'cbcb1087-4703-4b7c-a932-ea81268386fc', 'isActive', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive active/selected state from useActive. When true (and isHover is false), override values from activeState are applied. Hover takes priority when both are engaged simultaneously.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0655c4ff-a728-4ee6-a8e9-dd157e5457c8', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'cbcb1087-4703-4b7c-a932-ea81268386fc', 'hoverState', 'ComputedRef<IHoverState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useHover. Contains per-axis override values (color, bgColor, border, rounded, elevation, padding, margin, gap) to apply while hovered.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('eb92b7a5-d6a2-4789-bed0-469042ca453e', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'cbcb1087-4703-4b7c-a932-ea81268386fc', 'activeState', 'ComputedRef<IActiveState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useActive. Same shape as IHoverState — per-axis overrides applied while the item is selected/active.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('05bb7630-74fe-41aa-bc0b-147d048332b4', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'cbcb1087-4703-4b7c-a932-ea81268386fc', 'isDisabled', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, colorClasses is emptied (utility classes suppressed) so the disabled opacity veil is not overridden by a tokenised background.', 5, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('58177460-aa86-4992-be52-d11e5d588964', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'cbcb1087-4703-4b7c-a932-ea81268386fc', 'flat', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, elevationClasses and elevationStyles resolve to empty. Bridges the flat prop of Btn / Card without requiring a separate useElevation call.', 6, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0f2bac51-4c89-48b6-b3ae-493eaa2534eb', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'dd64d04a-8daa-47ab-953d-0b7accab491e', 'props', 'object', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5d60c6f0-2d5f-43c2-acc0-c285e192ef2c', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'dd64d04a-8daa-47ab-953d-0b7accab491e', 'options', 'IStateFlagOptions<S>', true, NULL, NULL, NULL, 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ad1643f8-a20d-4403-b77f-da0117a93043', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '60390812-b9cc-40ed-882e-ab2d05c80cd9', 'props', 'IStatusProps & IAdjacentProps', true, NULL, '', 'Component props. Reads status (TStatus: success | info | warning | error), statusIconPosition (prepend | append | both | replace), prependIcon, appendIcon, and icon. When status is set and statusIconPosition is replace, the status icon overwrites props.icon; when prepend/append/both, it fills the matching slot only if no explicit icon prop was passed.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('04328824-7a13-4bfc-a731-b58064bf4b6e', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '60390812-b9cc-40ed-882e-ab2d05c80cd9', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name used to build the BEM modifier class `{name}--{status}` (e.g. origam-alert--success). Defaults to the current Vue instance name.', 1, false, NULL, NULL);
