INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9f7856f5-2bce-4e20-97c7-ebbec054d5f9', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'f21bdfcc-ba8b-4a92-9cdb-213df8461484', 'options', 'IUseTextareaRichOptions', true, NULL, '', 'Configuration object. value: () => string — getter for the initial HTML content (bound to the parent v-model). onUpdate: (html: string) => void — called with sanitised HTML on every change. onFormat: (command, value?) => void — called after each format command (lets the host open a link popover on Cmd+K). disabled: () => boolean — suppresses all commands and keyboard shortcuts when true.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1b3a57ce-9e50-4b8d-a309-c5d7e264fbf4', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'fb6fb277-1017-475b-ae8d-575596d854bf', 'props', 'T | Ref<TColor>', true, NULL, '', 'Either the component props object (paired with `name`) or a plain Ref<TColor>.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('09f7d826-c581-4cca-bf0e-a7b296c9cb6b', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'fb6fb277-1017-475b-ae8d-575596d854bf', 'name', 'K', false, NULL, '', 'The key to read from the props object. Typically "color". Omit when passing a plain Ref.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('627b10e3-ba33-47e8-9de8-a4287d1d8857', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '2f01f69c-b685-442a-9328-9d697f84bb59', 'fn', '(...args: T) => R', true, NULL, '', 'The function to throttle. Called immediately on the first invocation within each window. The return value is discarded — the wrapper always returns void.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f34e13c6-d22f-443f-aff1-8d8220b8dc75', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '2f01f69c-b685-442a-9328-9d697f84bb59', 'wait', 'number', true, NULL, '', 'Throttle window in milliseconds. No call will execute within wait ms of the previous execution.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b824f2ca-12a9-49b2-a43e-ae0416da1a7e', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '221e6dea-7978-4b4b-a365-0b476783a283', 'source', 'WatchSource<boolean>', true, NULL, '', 'Reactive boolean source (ref, computed, or getter). When it evaluates to true the scope is started; when false the scope is stopped.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bc02faa9-d07d-4b4e-9a0d-1fda542a035f', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '221e6dea-7978-4b4b-a365-0b476783a283', 'fn', '(reset: () => void) => void', true, NULL, '', 'Callback run inside the new effectScope. Receives a `reset()` function that can be called from inside the scope to stop the current scope and immediately restart it — useful for subscriptions that need to re-initialise when an inner condition changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('91559e29-26d8-4cd3-9ab7-e81c61f315d2', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '688658ab-4ab4-4843-b8b8-d30e2856f0d7', 'isActive', 'Ref<boolean>', true, NULL, '', 'Whether the drawer is currently open. The composable writes to this ref when a fling gesture settles.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4b36abfb-5499-4665-a049-673ab8142f5c', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '20da485e-d890-4c37-9efe-71427d81496f', 'date', 'Date', true, NULL, 'utils.detail.add_days.param_date', 'The base date. Not mutated.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('47fc1a83-4e3c-41f5-94e3-fc4090e4c10d', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '688658ab-4ab4-4843-b8b8-d30e2856f0d7', 'isTemporary', 'Ref<boolean>', true, NULL, '', 'When true the drawer is temporary (modal overlay). The touch zone logic also activates for touches anywhere inside the element body, not only at the edge.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('769cb695-4aa7-4d97-811a-34616237c7fb', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '688658ab-4ab4-4843-b8b8-d30e2856f0d7', 'width', 'Ref<number>', true, NULL, '', 'Pixel width (or height for top/bottom positions) of the drawer. Used to compute drag progress as a fraction in [0, 1].', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('def7abf8-8315-42a0-9a62-63f78ae173a7', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '688658ab-4ab4-4843-b8b8-d30e2856f0d7', 'touchless', 'Ref<boolean>', true, NULL, '', 'When true all touch handling is disabled. Lets the consumer disable swipe gestures without unmounting the composable.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('35f2c53e-6088-4ecc-a6e8-748d90689b0f', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '688658ab-4ab4-4843-b8b8-d30e2856f0d7', 'position', 'Ref<''left'' | ''right'' | ''top'' | ''bottom''>', true, NULL, '', 'The edge from which the drawer slides in. Determines the touch zone, coordinate axis, and transform direction.', 4, false, NULL, NULL);
