INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('972cd4f2-2bf2-433d-b018-cf667f0cc447', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'dd5aeb97-71a8-4a14-9794-1d5eb6cf7d76', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for validation CSS class names (e.g. `origam-text-field--error`).', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d774ca0a-127b-43dc-91f0-b5d866fbfce5', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'dd5aeb97-71a8-4a14-9794-1d5eb6cf7d76', 'id', 'MaybeRef<string | number>', false, 'getUid()', '', 'Unique field ID used to register with the parent form. Defaults to an auto-generated UID.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0f0e575f-f7fc-4e4f-ae53-29a79bd3cf8e', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'a1eaa510-fbfa-43c7-88ef-860112079338', 'props', '{ variant?: string } | Ref<string | undefined>', true, NULL, '', 'Either the component props object (reads `props.variant`) or a bare reactive ref / computed to the variant string. The composable detects which form is passed via `isRef`.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b7b234e6-8be6-4b8d-aeaa-1bc693f04291', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'a1eaa510-fbfa-43c7-88ef-860112079338', 'name', 'string', false, 'getCurrentInstanceName()', '', 'The BEM block prefix. Defaults to the current component name (e.g. `origam-btn`). The class produced will be `{name}--variant-{variant}`.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2d60c0a9-b419-4349-91a1-4207c0d9e642', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '1241e400-498e-4e59-ac57-e9ea4d5b257d', 'options', 'IUseVideoPlayerOptions', false, '{}', '', 'Accepts `videoRef` (bring your own typed ref), `autoplay`, `muted`, `loop`, `preload`. All optional. Autoplay is suppressed when prefers-reduced-motion is active.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3e0d543b-e6c4-4fe4-98a4-4dd75e1d94a9', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '836e423f-5f5d-4048-8b6d-4ac0f65f117d', 'props', 'IVirtualProps', true, NULL, '', 'Reads `itemHeight` (expected row height in px, used to estimate the initial window), `height` (container height as string / number), `scrollDuration` (ms, default 300), `scrollEasing` (easing name, default easeInOutCubic).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e5c5ce3c-c32f-4fd0-b224-542343d6d9b1', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '836e423f-5f5d-4048-8b6d-4ac0f65f117d', 'items', 'Ref<readonly T[]>', true, NULL, '', 'The full dataset ref. The composable slices this array to produce `computedItems`. Changing the ref triggers an offset recalculation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('abbe290b-e2c0-446a-bab7-1bf55bb6423e', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '54a90e13-9b44-409f-a5a5-149167f0dfc1', 'props', 'Props', true, NULL, '', 'The component props object returned by defineProps. The composable reads `props[prop]` and inspects `vm.vnode.props` to detect whether the listener is wired.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('adc3464b-b243-4958-93d6-2dcf35a72460', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '54a90e13-9b44-409f-a5a5-149167f0dfc1', 'prop', 'Prop', true, NULL, '', 'The prop key to observe, e.g. `"modelValue"` for a standard v-model binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d8ec4e28-ecf5-42e9-b52e-d7ab13daf02a', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '54a90e13-9b44-409f-a5a5-149167f0dfc1', 'defaultValue', 'MaybeRefOrGetter<Props[Prop] | undefined>', false, NULL, '', 'Value used to initialise the internal ref when the prop is undefined on first render.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3c7bfe39-3328-41e2-8d9b-7de6f0723a66', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '54a90e13-9b44-409f-a5a5-149167f0dfc1', 'transformIn', '(value?: Props[Prop]) => Inner', false, '(v?: Props[Prop]) => v as Inner', '', 'Optional transform applied to the external prop value before exposing it to the component. Useful for converting a string to a number, or normalising null / undefined.', 3, false, NULL, NULL);
