INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9139e3ed-8763-45bd-89de-842ec528b1f8', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '027472c6-67d5-429f-a153-19ce7fe73c42', 'options', 'MaybeRefOrGetter<IUseWatermarkOptions>', false, '{}', '', 'Options bag (static object, reactive ref, or getter function). Reads: `text`, `image` (URL), `opacity` (default 0.15), `angle` (degrees, default -30), `gap` (tile spacing in px, default 100), `fontSize` (px, default 16), `fontFamily`, `color`, `fontWeight`, `pointerEvents` ("none" | "auto"), `zIndex`, `antiTamper` (enable MutationObserver re-injection). Passing a ref makes patternUrl update reactively when options change.', 0, false, NULL, NULL);
