INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('69493620-ac1c-4cd4-8689-8fdd19737fa7', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', '76f15eaf-90de-4656-9032-e30048422846', 'rtl', 'boolean', NULL, NULL, true, NULL, NULL, NULL, 'When true, forces the component subtree into right-to-left layout regardless of the current locale.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a02d53e3-a8d5-4717-bc20-cdf7ea2b11f8', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', '210b5b0e-9d47-4918-a6d9-881592c7ac45', 'location', 'TAnchor', NULL, NULL, true, NULL, NULL, NULL, 'Anchor descriptor that combines a side ("top", "bottom", "left", "right", "center") with an optional alignment ("start", "end"). Controls where the floating content appears relative to its target.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('244a2664-4507-4f5c-9a7a-82a2f767f053', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', '96856749-4de1-4356-88a0-e617dde3a87e', 'locationStrategy', 'TLocationStrategy | TLocationStrategyFn', NULL, NULL, true, NULL, NULL, NULL, 'Named strategy ("connected" | "static") or a custom strategy function. The connected strategy aligns the floating panel to the activator; static keeps it in place.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('85808332-1f7a-4ddd-bb2d-e5b99b330efe', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', '96856749-4de1-4356-88a0-e617dde3a87e', 'location', 'TAnchor', NULL, NULL, true, NULL, NULL, NULL, 'Side and alignment where the floating content appears relative to the activator (e.g. "bottom start", "top end").', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5f70c97d-a409-45cb-b6ad-42da0e9d0a67', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', '96856749-4de1-4356-88a0-e617dde3a87e', 'origin', 'TAnchor | ''auto'' | ''overlap''', NULL, NULL, true, NULL, NULL, NULL, 'The anchor point on the floating content itself. "auto" mirrors the location; "overlap" places the panel over the activator.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('904d7559-87df-4ac3-a4df-2f8c2e91ee18', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', '96856749-4de1-4356-88a0-e617dde3a87e', 'offset', 'number | string | Array<number>', NULL, NULL, true, NULL, NULL, NULL, 'Gap in pixels between the activator and the floating content. An array of two values sets [main-axis, cross-axis] offsets independently.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4b8c4bdb-1600-4099-be92-835c6c728b31', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', '96856749-4de1-4356-88a0-e617dde3a87e', 'viewportMargin', 'number', NULL, NULL, true, NULL, '12', NULL, 'Minimum breathing room in pixels between the floating content and each viewport edge. Defaults to 12 so panels never overlap browser chrome.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('550a474f-291b-478f-9535-95c8d453d84b', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', '0b9d325e-219b-4df8-8c9f-a3832c7683da', 'contentEl', 'Ref<HTMLElement | undefined>', NULL, NULL, false, NULL, NULL, NULL, 'Reactive reference to the floating content element. The strategy reads its dimensions and writes its position here.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8c86b561-5fe7-4242-9134-e63f21ffd527', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', '0b9d325e-219b-4df8-8c9f-a3832c7683da', 'target', 'Ref<HTMLElement | [x: number, y: number] | undefined>', NULL, NULL, false, NULL, NULL, NULL, 'Reactive reference to the anchor element or an [x, y] pixel coordinate. When set to coordinates, the floating panel anchors to a virtual point (used by context menus).', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('db94c735-fd76-4343-9ebc-854a787bce20', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', '0b9d325e-219b-4df8-8c9f-a3832c7683da', 'isActive', 'Ref<boolean>', NULL, NULL, false, NULL, NULL, NULL, 'Reactive flag that reflects whether the floating content is currently visible. Strategies may skip recalculation when false.', 2, false, NULL, NULL);
