INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9cc8073a-b8d5-447d-8870-2bfcce184f98', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', 'bee1d971-ded0-4dde-b2ed-4e940c0bd48d', 'highlightLines', 'number[] | string | null', '', 'primitive', NULL, false, 'null', 'components.code.props.highlight_lines.description', 'Lines to highlight. Accepts a 1-based array ([2, 5, 6]) or a range string (''2,5-7''). Null/empty disables.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9768097e-91ec-43e3-a7eb-680c7f163123', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', 'bee1d971-ded0-4dde-b2ed-4e940c0bd48d', 'copyable', 'boolean', '', 'primitive', NULL, false, 'true', 'components.code.props.copyable.description', 'Shows the copy-to-clipboard button. True by default — most code blocks benefit from it.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bb386b53-e211-4034-98de-d529c65fb16e', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', 'bee1d971-ded0-4dde-b2ed-4e940c0bd48d', 'format', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.format.description', 'Auto-format the code before highlighting. Reserved — currently a no-op that warns in dev mode. Prettier is not bundled at runtime to keep the tarball small.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('122ecb8a-1e13-4ee8-90a8-c4080e87385b', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', 'bee1d971-ded0-4dde-b2ed-4e940c0bd48d', 'wrap', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.wrap.description', 'Wraps long lines instead of scrolling horizontally.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5aec376b-700d-405d-b44b-9bfaf002cd9a', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', 'bee1d971-ded0-4dde-b2ed-4e940c0bd48d', 'filename', 'string', '', 'primitive', NULL, false, 'undefined', 'components.code.props.filename.description', 'Optional filename rendered in the header bar (e.g. ''App.vue''). When present AND copyable=true, the header hosts the copy button; otherwise the copy button floats in the top-right corner.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bae10572-eebe-4c1d-8493-52788afd314b', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', 'bee1d971-ded0-4dde-b2ed-4e940c0bd48d', 'compact', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.compact.description', 'Renders as a single-line inline pill (ideal for install commands). Header, filename and line numbers are suppressed; the copy button collapses to a small icon.', 8, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('66eda368-ac1a-4639-a7bf-8fe22597bca2', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', 'bee1d971-ded0-4dde-b2ed-4e940c0bd48d', 'prompt', 'string', '', 'primitive', NULL, false, 'undefined', 'components.code.props.prompt.description', 'Decorative prefix rendered before the code (e.g. ''$'' for shell commands). Purely visual — not copied to clipboard.', 9, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('469f2b11-b185-440c-bbd0-16f772f1f775', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', 'bee1d971-ded0-4dde-b2ed-4e940c0bd48d', 'hideHeader', 'boolean', NULL, NULL, NULL, false, NULL, NULL, 'Do not render the header bar (filename / language badge / copy button). For a block embedded in a surface that already shows that information, such as a tab of OrigamCodeGroup.', 10, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2e955818-5c25-48eb-afb4-a9d4fae9af75', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', 'bee1d971-ded0-4dde-b2ed-4e940c0bd48d', 'flat', 'boolean', NULL, NULL, NULL, false, NULL, NULL, 'Flatten the block into its host: no border, no radius, no elevation, no outer margin.', 11, false, NULL, NULL);
