INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('87d28d8d-5c74-433f-a3c5-32c3cf032d8e', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:15.031198+00', '2c486986-9f3d-4ae0-adde-3d55d8366c4c', 'downloadable', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.downloadable.description', 'Adds a "Download" row to the config cog menu when true. Requires downloadUrl to be set.', 6, false, NULL, NULL);
