INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bfec36d2-644e-4d89-ba81-6ee37a8f8e58', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'd2a5f979-1016-4536-b45f-71ef898feebf', 'dismiss', '() => void', '', 'Convenience wrapper for snapTo("closed"). Blocked when persistent=true (falls back to the lowest non-zero snap).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2128a8aa-747b-450e-9d4c-ea85803ccace', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'd2a5f979-1016-4536-b45f-71ef898feebf', 'currentSnapHeight', 'ComputedRef<number>', '', 'Resolved pixel height of the current snap point. SSR-safe (returns 0 when window is absent). Used to compute the sheet height style: currentSnapHeight + dragOffset.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7b40113f-d914-4402-b743-50884a53c402', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '95b6294d-a85a-45f1-b076-2156d57c1605', 'sizeClasses', 'ComputedRef<string[]>', '', 'Component-local BEM modifier class (e.g. "origam-btn--size-small") plus the typographic utility class (e.g. "origam--text-sm") bridging the legacy to modern taxonomy.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a2441461-d9d8-4312-8c0a-0864c20f62c6', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '95b6294d-a85a-45f1-b076-2156d57c1605', 'sizeStyles', 'ComputedRef<string[]>', '', 'Inline width and height declarations for custom numeric or CSS-length sizes (when the value is not a named preset).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fd5e98cc-013b-482d-a823-e4fc41524a51', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'b93eae87-55be-45b7-afa1-a36eeb97ea4e', 'min', 'ComputedRef<number>', '', 'Parsed minimum value. Defaults to 0 when props.min is undefined or null.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bb8cd930-3e3e-4e5a-8db0-f58029aa5a4e', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'b93eae87-55be-45b7-afa1-a36eeb97ea4e', 'max', 'ComputedRef<number>', '', 'Parsed maximum value. Defaults to 100 when props.max is undefined or null.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('91363e0c-eecf-4069-8535-793e0624e86d', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'b93eae87-55be-45b7-afa1-a36eeb97ea4e', 'step', 'ComputedRef<number>', '', 'Parsed step value. 0 means no stepping (any value between min and max is valid). Positive values define the snap grid.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7e4b1ab4-d0d8-4f72-a543-e9e14f98c352', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'b93eae87-55be-45b7-afa1-a36eeb97ea4e', 'decimals', 'ComputedRef<number>', '', 'Number of decimal places to preserve in roundValue output. Derived from max(getDecimals(step), getDecimals(min)) to match the precision implied by the step grid.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('835f6440-34c6-4bda-bd5c-35d618f1d6e1', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'b93eae87-55be-45b7-afa1-a36eeb97ea4e', 'roundValue', '(value: string | number) => number', '', 'Snap a raw value to the nearest valid step, clamped to [min, max]. Handles the min-offset edge case so that a step=5 min=3 grid snaps to 3, 8, 13, … rather than 0, 5, 10, ….', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('04c6da4c-20d8-4721-9e85-c4605eb74555', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '58fc4ba6-8323-40f0-bd7c-a9dfeaa64c1f', 'time', 'ShallowRef<number>', '', 'Remaining milliseconds. Starts at the initial milliseconds value, decrements on each tick, and bottoms out at 0. Bind to a progress bar width to visualise the countdown.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0c65f6a0-85f8-45d3-8688-b38345753720', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '58fc4ba6-8323-40f0-bd7c-a9dfeaa64c1f', 'clear', '() => void', '', 'Stops the interval without resetting time. Use to pause the countdown (e.g. while the user is hovering the snackbar).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b18e9ed5-bf1f-4115-9811-c977a33e3e7c', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '58fc4ba6-8323-40f0-bd7c-a9dfeaa64c1f', 'reset', '() => void', '', 'Clears the interval and resets time to the initial milliseconds value on the next tick. Use when the snackbar content changes and the countdown should restart.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('39f7ddf6-0461-4353-abed-ea5985f4eaa9', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '58fc4ba6-8323-40f0-bd7c-a9dfeaa64c1f', 'start', '(el?: HTMLElement) => void', '', 'Start (or resume) the countdown. Reads the CSS transitionDuration of el to synchronise tick frequency with the progress bar animation. Falls back to 200 ms when no element is provided or no transition is set. Clears any existing interval before starting.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f330a1ed-fe72-41b4-b624-311a7a5f0bcd', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '96737fb1-8b1b-4086-820a-85827749fe1e', 'items', 'Readonly<Ref<ReadonlyArray<ISnackbarGroupItem>>>', '', 'Reactive read-only snapshot of the current stack. Mutate only through notify / dismiss / dismissAll — direct writes are blocked at the TypeScript level.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('11fcc6df-9549-414b-a190-f6c737b0854b', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '96737fb1-8b1b-4086-820a-85827749fe1e', 'notify', '(opts: ISnackbarGroupItemOptions) => string', '', 'Push a new item onto the stack. Accepts ISnackbarGroupItemOptions (message, variant, icon, duration, onDismiss callback…). Returns the generated item id so the caller can dismiss it early.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('29d0db7e-abed-423b-bba1-0dd767bacf15', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '96737fb1-8b1b-4086-820a-85827749fe1e', 'dismiss', '(itemId: string) => void', '', 'Remove the item with the given id from the stack, cancel its auto-dismiss timer, and invoke its onDismiss callback if any.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b4b6a9fe-5129-4127-be24-0922495de5c6', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '96737fb1-8b1b-4086-820a-85827749fe1e', 'dismissAll', '() => void', '', 'Dismiss every item in the stack in one call. Iterates a snapshot of the ids so mid-loop mutations are safe.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e383bb31-5413-481f-9ed7-c0dbf9394d80', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '90cbaafc-7564-4b1a-ae5d-2be09b94206d', 'sortBy', 'Ref<Array<IDataTableSortItem>>', '', 'Reactive array of active sort descriptors, each with a key (column key) and an order (asc | desc). Driven by useVModel against the host table props.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fc0d31ad-129f-4021-b7bc-b278b0848377', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '90cbaafc-7564-4b1a-ae5d-2be09b94206d', 'toggleSort', '(column: IInternalDataTableHeader) => void', '', 'Cycle the sort state for a column: none → asc → desc → none (or asc when mustSort=true). Respects multiSort — when false, replaces the entire sortBy array with a single entry.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0b0e950a-5e5d-48c0-9c60-a4fc221a5f27', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '90cbaafc-7564-4b1a-ae5d-2be09b94206d', 'isSorted', '(column: IInternalDataTableHeader) => boolean', '', 'Returns true when the column has an active sort entry in sortBy. Used by header cells to show the sort icon.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ef93c397-cbe5-4cc8-b4b6-d5900ec41c9f', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '564f753b-c74d-4e7d-adc0-ad5eeb3196a5', 'ssrBootStyles', 'ComputedRef<CSSProperties | []>', '', 'An object `{ transition: "none !important" }` when the component has not yet booted, or an empty array after the first animation frame. Spread onto the root element via :style to suppress hydration-flash transitions.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9d2c84a0-52d8-42cf-a59f-944315f48159', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '564f753b-c74d-4e7d-adc0-ad5eeb3196a5', 'isBooted', 'Readonly<ShallowRef<boolean>>', '', 'False on the server and during the first rAF after mount, true thereafter. Useful as a guard before running DOM-dependent logic that assumes the component is fully hydrated.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d5fc230a-897a-4351-85c6-e36e0f732758', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'ce867961-cb39-483f-99f9-5a03e9fe9569', NULL, 'number', 'utils.detail.apc_acontrast.returns', 'Signed APCA contrast value. Absolute value >= 45 is the recommended minimum for body text.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1d0b99df-b618-4338-8d04-5a8668186ec6', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '18362b1b-e010-400f-9521-26ee4a71046f', 'globalTop', 'Readonly<ShallowRef<boolean>>', '', 'True when this component is the last entry in GLOBAL_STACK (topmost overlay on the page). Updated asynchronously via setTimeout to avoid synchronous circular reads during stack registration.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e4bb6709-7639-4ef9-8331-a752064364fc', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '18362b1b-e010-400f-9521-26ee4a71046f', 'localTop', 'ComputedRef<boolean>', '', 'True when this overlay has no active child overlays (nothing opened on top of it within its own sub-tree). Used to decide whether clicks on the backdrop should close this overlay.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6e891f8d-5d40-4269-9a16-798d042a7836', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '18362b1b-e010-400f-9521-26ee4a71046f', 'stackStyles', 'ComputedRef<{ zIndex: number }>', '', 'Style object containing the computed zIndex. Spread onto the overlay root element so it automatically rises above the previous topmost overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ef487322-ca50-465a-9152-23f14201c2f4', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'cbcb1087-4703-4b7c-a932-ea81268386fc', 'colorClasses / colorStyles', 'ComputedRef<string[]>', '', 'Tokenised intent values emit a utility class (origam--bg-primary); custom CSS colors emit an inline style. Both are empty when disabled/hover/active is true (state-inline path takes over).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a7181383-e9b4-40f7-be2d-a2b2f0a8ec9c', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'cbcb1087-4703-4b7c-a932-ea81268386fc', 'borderClasses / borderStyles', 'ComputedRef<string[]>', '', 'Delegated to useBorder with a reactive proxy that swaps to hoverState/activeState.border when the state is engaged.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('173163fd-e828-4bc0-ae1d-e31c0cad0efb', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'cbcb1087-4703-4b7c-a932-ea81268386fc', 'roundedClasses / roundedStyles', 'ComputedRef<string[]>', '', 'Delegated to useRounded. State-aware: applies hoverState/activeState.rounded when engaged.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9b50cf9b-1dbe-40f0-8ff8-a1981dce131e', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'cbcb1087-4703-4b7c-a932-ea81268386fc', 'elevationClasses / elevationStyles', 'ComputedRef<string[]>', '', 'Delegated to useElevation. Cleared when flat=true. State-aware via the pickEffective resolver.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e02b2138-f52a-4747-a07b-92faecef7968', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'cbcb1087-4703-4b7c-a932-ea81268386fc', 'paddingClasses / paddingStyles', 'ComputedRef<string[]>', '', 'Delegated to usePadding via a reactive getter proxy to preserve dependency tracking across state swaps.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('22265ed7-1af6-49fe-9c37-b8d410c59b21', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'cbcb1087-4703-4b7c-a932-ea81268386fc', 'marginClasses / marginStyles', 'ComputedRef<string[]>', '', 'Delegated to useMargin via a reactive getter proxy.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cddc77dd-e8be-442b-97ad-5f94a89fd035', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'cbcb1087-4703-4b7c-a932-ea81268386fc', 'gapClasses / gapStyles', 'ComputedRef<string[]>', '', 'Gap has no dedicated composable. Emits an inline style (gap: Npx or gap: <value>) when a gap override is present. gapClasses is always empty.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('23b4aa63-85b3-48bc-88f0-62ce85c495c6', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '60390812-b9cc-40ed-882e-ab2d05c80cd9', 'icon', 'ComputedRef<string | undefined>', '', 'Resolved center/replace icon. Returns the status icon when statusIconPosition="replace" and no explicit props.icon was provided, otherwise passes through props.icon.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('86be2339-a244-44ab-af13-fa6184ee29f6', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '60390812-b9cc-40ed-882e-ab2d05c80cd9', 'prependIcon', 'ComputedRef<string | undefined>', '', 'Resolved prepend-slot icon. Injects the status icon when statusIconPosition is prepend or both and props.prependIcon is unset.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3e11605d-aa8f-4062-967c-37b64a25ea01', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '60390812-b9cc-40ed-882e-ab2d05c80cd9', 'appendIcon', 'ComputedRef<string | undefined>', '', 'Resolved append-slot icon. Injects the status icon when statusIconPosition is append or both and props.appendIcon is unset.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1307afe0-8898-491d-bcc2-e58cd878ee79', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '60390812-b9cc-40ed-882e-ab2d05c80cd9', 'statusClasses', 'ComputedRef<string[]>', '', 'Array containing `{name}--{status}` when a status is set, empty otherwise. Bind to the root element for SCSS state selectors.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('06ea2c30-7802-4e4b-a75b-8a2fc0203409', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '60390812-b9cc-40ed-882e-ab2d05c80cd9', 'statusIntent', 'ComputedRef<TColor | undefined>', '', 'The resolved TColor intent for the current status (success→success, info→info, warning→warning, error→danger). Undefined when no status is set. Consumed by useStateEffect to force the semantic surface color.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f41565cf-31ea-4b3b-99d6-74577b460d5b', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'ae591263-cea7-4661-bfa7-9a9ccbb53f34', 'isStuck', 'ShallowRef<boolean | "top" | "bottom">', '', 'Current stuck state. "top" = anchored at the top of the viewport (sidebar shorter than viewport or scrolled to top), "bottom" = anchored at the bottom edge, true = stuck mid-page (sidebar taller than viewport, user scrolled past the top edge), false = not sticky (isSticky prop is false).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('066ac73c-a9c5-4f2f-aace-733269cecd1c', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'ae591263-cea7-4661-bfa7-9a9ccbb53f34', 'stickyStyles', 'ComputedRef<Array<CSSProperties | undefined>>', '', 'Two-element style array to spread on the element. The first resets top/bottom/height when isSticky is enabled. The second applies the computed positional offset: the layoutItem top when not yet stuck, or the scrolled stuckPosition when stuck mid-page or at the bottom.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c741bbd9-f8ad-4940-a3f2-6676a2734890', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '0f270128-3256-432c-880a-4741a529d8d9', 'id', 'ComputedRef<string>', '', 'The element id used as the CSS scope selector (#id). Apply this id to the root element of the component so the injected styles target only this instance.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d0a372a9-e53a-4eaf-8904-b5cfa7d7e0de', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '0f270128-3256-432c-880a-4741a529d8d9', 'css', 'ShallowRef<string>', '', 'The current generated CSS string. Reactive — updates whenever the styles ComputedRef changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ad5860f2-a26d-4a34-bac9-d696b483e845', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '0f270128-3256-432c-880a-4741a529d8d9', 'load / unload', '() => void', '', 'Manually control style tag injection. Normally called automatically on mount / scope dispose. Call load() to re-inject after an explicit unload().', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cc65136d-4454-4693-b724-f9ebee2a8eed', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '0f270128-3256-432c-880a-4741a529d8d9', 'isLoaded', 'Readonly<ShallowRef<boolean>>', '', 'True when the <style> tag is currently present in document.head.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('72542672-3c57-4b97-a77e-3cb7499952c1', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'fe1d359d-2acf-4491-8271-13d729478eb8', 'teleportTarget', 'ComputedRef<Element | undefined>', '', 'The resolved .origam-overlay-container element inside the target, or undefined when teleport is disabled (target=true) or the app is running on the server (SSR). Pass directly to <Teleport :to="teleportTarget">.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('117f6b64-7c84-4b43-85af-1a42a8dae8f0', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'f21bdfcc-ba8b-4a92-9cdb-213df8461484', 'hostRef', 'Ref<HTMLElement | undefined>', '', 'Template ref to assign to the contenteditable element. The composable uses it to read and write innerHTML, attach the selectionchange listener, and focus the element before applying a format command.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('652d3d63-0cb6-40fb-a15d-a80bc95c6075', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'f21bdfcc-ba8b-4a92-9cdb-213df8461484', 'active', 'ITextareaRichActiveState', '', 'Reactive object tracking the formatting state at the current caret position. Properties: bold, italic, underline, code, link (booleans), listBullet, listOrdered (booleans), heading (0 | 1 | 2 | 3). Bind to toolbar button :active props.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('551fe47b-adb3-4c7d-b345-9aec91f0f998', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'f21bdfcc-ba8b-4a92-9cdb-213df8461484', 'format', '(command: TTextareaToolbarCommand, value?: string) => void', '', 'Apply a formatting command. Delegates to document.execCommand for bold, italic, underline, lists, and headings. Handles link creation (value = URL) and inline code toggling (insertHTML). Calls onFormat and onUpdate after every change.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('36fd666c-bcf4-45de-b666-4d9d6393323c', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'f21bdfcc-ba8b-4a92-9cdb-213df8461484', 'isFormatActive', '(command: TTextareaToolbarCommand) => boolean', '', 'Returns whether the given command is active at the current caret position. Reads from the reactive active object — a convenience wrapper for toolbar binding.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5c0facfc-e33c-4a19-b334-f66193c8d676', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'f21bdfcc-ba8b-4a92-9cdb-213df8461484', 'setValue', '(html: string) => void', '', 'Imperatively update the contenteditable innerHTML with sanitised HTML. No-ops when hostRef is unset or when the content is already identical (avoids cursor jump).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('65cfb5dc-ab30-4357-9f31-f43ec669bd83', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'f21bdfcc-ba8b-4a92-9cdb-213df8461484', 'onInput / onKeydown / onPaste', '(event) => void', '', 'Event handlers to bind on the host element. onInput emits sanitised HTML. onKeydown intercepts Cmd/Ctrl+B/I/U/E/K and Cmd+Shift+7/8 for list shortcuts. onPaste strips HTML to sanitised form (or escapes plain text) before inserting.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('844bf2fa-a314-41a9-8152-1bec2ac0da29', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'fb6fb277-1017-475b-ae8d-575596d854bf', 'textColorClasses', 'ComputedRef<string[]>', '', 'Utility class names (e.g. ["origam--color-primary"]) to bind via :class.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2e45f075-3701-425f-818c-e39904e4d07a', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'fb6fb277-1017-475b-ae8d-575596d854bf', 'textColorStyles', 'ComputedRef<string[]>', '', 'Inline CSS declarations (e.g. ["color: #6d28d9"]) to bind via :style. For gradients, includes background-image + background-clip: text.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c905b788-f29b-4acd-87a9-193e6ca521be', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', 'b22ac144-635a-4931-823e-511072ca5967', 'theme', 'Readonly<Ref<TTheme>>', '', 'The current brand theme value: ''auto'' | ''light'' | ''dark'' | string (custom brand). Read-only reactive ref.', 0, false, NULL, NULL);
