INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a5055233-18b2-47f2-b617-402ed5ae1f96', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '836e423f-5f5d-4048-8b6d-4ac0f65f117d', 'containerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to the scrollable container element. The composable reads `scrollTop` from it and listens to `handleScroll` / `handleScrollend`.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3844388a-0a53-4151-a4f7-c86fcc3f8b21', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '836e423f-5f5d-4048-8b6d-4ac0f65f117d', 'markerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to a zero-height element at the top of the list content area. Its `offsetTop` is used to compute an offset if there is padding or a header above the virtual list.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e8e268c0-5f0b-4686-a644-ca388dd685a8', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '836e423f-5f5d-4048-8b6d-4ac0f65f117d', 'computedItems', 'ComputedRef<Array<{ raw: T; index: number }>>', '', 'The slice of items currently in the render window. Each entry carries the original `raw` item and its absolute `index` in the full list.', 2, false, NULL, NULL);
