INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('736ab7af-9a99-4a33-9f77-4d2d01fddb46', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '836e423f-5f5d-4048-8b6d-4ac0f65f117d', 'scrollToIndex', '(index: number, options?: Partial<IGoToOptions>) => void', '', 'Programmatically scroll the container to a specific item index. Defers the scroll if the list has not yet measured (first render not complete). Pass `{ duration: 0 }` for instant scroll.', 5, false, NULL, NULL);
