INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9d680d9c-3b08-4c20-bcdc-9378b3380b74', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '836e423f-5f5d-4048-8b6d-4ac0f65f117d', 'handleItemResize', '(index: number, height: number) => void', '', 'Call when a rendered item changes its measured height. Updates the size cache and triggers an offset recalculation. Wire via a ResizeObserver on each rendered row.', 8, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bacc491e-673c-4034-b0c4-76f5aedd8ecb', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '54a90e13-9b44-409f-a5a5-149167f0dfc1', '(model)', 'Ref<TInnerVal<Inner>> & { readonly externalValue: Props[Prop] }', '', 'A writable computed ref. Reading it returns the current value (controlled or internal). Writing it updates the internal ref and emits `update:prop`. The `externalValue` accessor returns the raw prop value without transformIn applied.', 0, false, NULL, NULL);
