INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bd4cddb5-3a75-4e9c-bdbd-10619d5884d3', '2026-11-18 16:12:00.654951+00', '2026-11-18 16:12:00.654951+00', '17b0a5b5-3863-47f9-bd1f-28150ad78b8d', 'true', 'types.detail.file_size.true', 'File sizes are displayed using the SI divisor (1 000) — KB, MB, GB.', 1, false, NULL, NULL);
